# Re-entrancy guard: while a frozen teacher is being constructed, the teacher's
# own __init__ must not try to load another teacher (would recurse forever).
_COLT_TEACHER_LOADING = False


def _extend_colt_cached_attention_mask(
    prompt_attention_mask: Optional[torch.Tensor],
    *,
    past_seen_tokens: int,
    current_length: int,
    batch_size: int,
    device: torch.device,
    current_attention_mask: Optional[torch.Tensor] = None,
    mask_prompt: bool = False,
) -> torch.Tensor:
    """Build the 2D mask required by a cached CoLT decoding step.

    Transformers expects a cached decoding mask to span both the existing KV
    cache and the current query tokens.  CoLT adds latent tokens to that cache,
    so retaining only a one-token mask makes left-padded prompt positions
    attendable again after prefill.
    """
    if past_seen_tokens < 0:
        raise ValueError(f"past_seen_tokens must be non-negative, received {past_seen_tokens}.")
    if current_length <= 0:
        raise ValueError(f"current_length must be positive, received {current_length}.")

    if prompt_attention_mask is not None:
        if prompt_attention_mask.ndim != 2:
            raise ValueError(
                "CoLT cached decoding requires a rank-2 prompt attention_mask; "
                f"received shape {tuple(prompt_attention_mask.shape)}."
            )
        if prompt_attention_mask.shape[0] != batch_size:
            raise ValueError(
                "CoLT cached decoding prompt attention_mask batch size does not match inputs: "
                f"mask={prompt_attention_mask.shape[0]}, inputs={batch_size}."
            )
        prompt_attention_mask = prompt_attention_mask.to(device=device)
        cached_latent_length = past_seen_tokens - prompt_attention_mask.shape[1]
        if cached_latent_length < 0:
            raise ValueError(
                "CoLT cache is shorter than the prompt attention_mask: "
                f"cache={past_seen_tokens}, prompt={prompt_attention_mask.shape[1]}."
            )
        mask_dtype = prompt_attention_mask.dtype
        cached_prefix_mask = torch.zeros_like(prompt_attention_mask) if mask_prompt else prompt_attention_mask
    else:
        cached_latent_length = past_seen_tokens
        mask_dtype = torch.long
        cached_prefix_mask = torch.empty((batch_size, 0), dtype=mask_dtype, device=device)

    if current_attention_mask is None:
        current_attention_mask = torch.ones(
            (batch_size, current_length),
            dtype=mask_dtype,
            device=device,
        )
    else:
        if current_attention_mask.ndim != 2:
            raise ValueError(
                "CoLT cached decoding requires a rank-2 current attention_mask; "
                f"received shape {tuple(current_attention_mask.shape)}."
            )
        if current_attention_mask.shape != (batch_size, current_length):
            raise ValueError(
                "CoLT cached decoding current attention_mask shape does not match inputs: "
                f"mask={tuple(current_attention_mask.shape)}, expected={(batch_size, current_length)}."
            )
        current_attention_mask = current_attention_mask.to(device=device, dtype=mask_dtype)

    cached_latent_mask = torch.ones(
        (batch_size, cached_latent_length),
        dtype=mask_dtype,
        device=device,
    )
    return torch.cat((cached_prefix_mask, cached_latent_mask, current_attention_mask), dim=1)


def _normalize_colt_row_mask(
    row_mask: Optional[torch.Tensor],
    *,
    batch_size: int,
    device: torch.device,
    name: str,
) -> Optional[torch.Tensor]:
    """Validate and move a per-example CoLT control mask."""
    if row_mask is None:
        return None
    if not isinstance(row_mask, torch.Tensor):
        row_mask = torch.as_tensor(row_mask)
    if row_mask.ndim != 1 or row_mask.shape[0] != batch_size:
        raise ValueError(
            f"{name} must have shape ({batch_size},), received {tuple(row_mask.shape)}."
        )
    return row_mask.to(device=device, dtype=torch.bool)


def _resolve_colt_loss_row_mask(
    labels: Optional[torch.Tensor],
    *,
    batch_size: int,
    device: torch.device,
    visual_only: Optional[torch.Tensor] = None,
) -> torch.Tensor:
    """Return examples that have supervised targets for custom CoLT losses.

    CoLT reconstructs CoT and answer targets from ``input_ids``. Therefore the
    normal SFT ``labels`` mask must be applied explicitly here instead of being
    treated as documentation-only metadata.
    """
    if labels is None:
        active_rows = torch.ones(batch_size, dtype=torch.bool, device=device)
    else:
        if labels.ndim != 2 or labels.shape[0] != batch_size:
            raise ValueError(
                "CoLT labels must have shape (batch_size, sequence_length); "
                f"received {tuple(labels.shape)} for batch size {batch_size}."
            )
        active_rows = labels.ne(-100).any(dim=1).to(device=device)

    visual_only_rows = _normalize_colt_row_mask(
        visual_only,
        batch_size=batch_size,
        device=device,
        name="colt_visual_only",
    )
    if visual_only_rows is not None:
        active_rows = active_rows & ~visual_only_rows
    return active_rows


def _resolve_colt_visual_cot_rows(
    visual_cot: Optional[torch.Tensor],
    *,
    batch_size: int,
    device: torch.device,
    bboxes: Optional[List[List[List[float]]]] = None,
    step_bboxes: Optional[List[List[List[List[float]]]]] = None,
) -> torch.Tensor:
    """Resolve the rows eligible for the visual-CoT information bottleneck."""
    explicit_rows = _normalize_colt_row_mask(
        visual_cot,
        batch_size=batch_size,
        device=device,
        name="colt_visual_cot",
    )
    if explicit_rows is not None:
        return explicit_rows

    inferred_rows = torch.zeros(batch_size, dtype=torch.bool, device=device)
    if bboxes is not None:
        if len(bboxes) != batch_size:
            raise ValueError(
                f"colt_bboxes must contain one entry per sample ({batch_size}), received {len(bboxes)}."
            )
        inferred_rows |= torch.tensor([bool(sample_bboxes) for sample_bboxes in bboxes], device=device)
    if step_bboxes is not None:
        if len(step_bboxes) != batch_size:
            raise ValueError(
                "colt_step_bboxes must contain one entry per sample "
                f"({batch_size}), received {len(step_bboxes)}."
            )
        inferred_rows |= torch.tensor(
            [bool(sample_step_bboxes) for sample_step_bboxes in step_bboxes],
            device=device,
        )
    return inferred_rows


def _mask_colt_visual_cot_prompt_rows(
    attention_mask: torch.Tensor,
    *,
    current_seq_len: int,
    rows_to_mask: torch.Tensor,
) -> torch.Tensor:
    """Hide the complete question KV prefix for selected visual-CoT rows."""
    if attention_mask.ndim != 2:
        raise ValueError(
            "CoLT visual-CoT answer attention_mask must be rank 2; "
            f"received shape {tuple(attention_mask.shape)}."
        )
    if rows_to_mask.ndim != 1 or rows_to_mask.shape[0] != attention_mask.shape[0]:
        raise ValueError(
            "CoLT visual-CoT row mask must match the attention_mask batch dimension; "
            f"received {tuple(rows_to_mask.shape)} for {attention_mask.shape[0]} rows."
        )
    if current_seq_len < 0 or current_seq_len > attention_mask.shape[1]:
        raise ValueError(
            "CoLT question cache length must fit inside the answer attention mask; "
            f"received current_seq_len={current_seq_len}, mask_length={attention_mask.shape[1]}."
        )
    masked_attention_mask = attention_mask.clone()
    masked_attention_mask[rows_to_mask.to(device=attention_mask.device), :current_seq_len] = 0
    return masked_attention_mask


class Qwen3VLVisionMLP(nn.Module):
    def __init__(self, config):
        super().__init__()
        self.hidden_size = config.hidden_size
        self.intermediate_size = config.intermediate_size
        self.linear_fc1 = nn.Linear(self.hidden_size, self.intermediate_size, bias=True)
        self.linear_fc2 = nn.Linear(self.intermediate_size, self.hidden_size, bias=True)
        self.act_fn = ACT2FN[config.hidden_act]

    def forward(self, hidden_state):
        return self.linear_fc2(self.act_fn(self.linear_fc1(hidden_state)))


class Qwen3VLVisionPatchEmbed(nn.Module):
    def __init__(self, config) -> None:
        super().__init__()
        self.patch_size = config.patch_size
        self.temporal_patch_size = config.temporal_patch_size
        self.in_channels = config.in_channels
        self.embed_dim = config.hidden_size

        kernel_size = [self.temporal_patch_size, self.patch_size, self.patch_size]
        self.proj = nn.Conv3d(self.in_channels, self.embed_dim, kernel_size=kernel_size, stride=kernel_size, bias=True)

    def forward(self, hidden_states: torch.Tensor) -> torch.Tensor:
        target_dtype = self.proj.weight.dtype
        hidden_states = hidden_states.view(
            -1, self.in_channels, self.temporal_patch_size, self.patch_size, self.patch_size
        )
        hidden_states = self.proj(hidden_states.to(dtype=target_dtype)).view(-1, self.embed_dim)
        return hidden_states


class Qwen3VLVisionRotaryEmbedding(nn.Module):
    inv_freq: torch.Tensor  # fix linting for `register_buffer`

    def __init__(self, dim: int, theta: float = 10000.0) -> None:
        super().__init__()
        inv_freq = 1.0 / (theta ** (torch.arange(0, dim, 2, dtype=torch.float) / dim))
        self.register_buffer("inv_freq", inv_freq, persistent=False)

    def forward(self, seqlen: int) -> torch.Tensor:
        seq = torch.arange(seqlen, device=self.inv_freq.device, dtype=self.inv_freq.dtype)
        freqs = torch.outer(seq, self.inv_freq)
        return freqs


class Qwen3VLVisionPatchMerger(nn.Module):
    def __init__(self, config: Qwen3VLVisionConfig, use_postshuffle_norm=False) -> None:
        super().__init__()
        self.hidden_size = config.hidden_size * (config.spatial_merge_size**2)
        self.use_postshuffle_norm = use_postshuffle_norm
        self.norm = nn.LayerNorm(self.hidden_size if use_postshuffle_norm else config.hidden_size, eps=1e-6)
        self.linear_fc1 = nn.Linear(self.hidden_size, self.hidden_size)
        self.act_fn = nn.GELU()
        self.linear_fc2 = nn.Linear(self.hidden_size, config.out_hidden_size)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        x = self.norm(x.view(-1, self.hidden_size) if self.use_postshuffle_norm else x).view(-1, self.hidden_size)
        x = self.linear_fc2(self.act_fn(self.linear_fc1(x)))
        return x


def rotate_half(x):
    """Rotates half the hidden dims of the input."""
    x1 = x[..., : x.shape[-1] // 2]
    x2 = x[..., x.shape[-1] // 2 :]
    return torch.cat((-x2, x1), dim=-1)


def apply_rotary_pos_emb_vision(
    q: torch.Tensor, k: torch.Tensor, cos: torch.Tensor, sin: torch.Tensor
) -> tuple[torch.Tensor, torch.Tensor]:
    orig_q_dtype = q.dtype
    orig_k_dtype = k.dtype
    q, k = q.float(), k.float()
    cos, sin = cos.unsqueeze(-2).float(), sin.unsqueeze(-2).float()
    q_embed = (q * cos) + (rotate_half(q) * sin)
    k_embed = (k * cos) + (rotate_half(k) * sin)
    q_embed = q_embed.to(orig_q_dtype)
    k_embed = k_embed.to(orig_k_dtype)
    return q_embed, k_embed


def repeat_kv(hidden_states: torch.Tensor, n_rep: int) -> torch.Tensor:
    """
    This is the equivalent of torch.repeat_interleave(x, dim=1, repeats=n_rep). The hidden states go from (batch,
    num_key_value_heads, seqlen, head_dim) to (batch, num_attention_heads, seqlen, head_dim)
    """
    batch, num_key_value_heads, slen, head_dim = hidden_states.shape
    if n_rep == 1:
        return hidden_states
    hidden_states = hidden_states[:, :, None, :, :].expand(batch, num_key_value_heads, n_rep, slen, head_dim)
    return hidden_states.reshape(batch, num_key_value_heads * n_rep, slen, head_dim)


def eager_attention_forward(
    module: nn.Module,
    query: torch.Tensor,
    key: torch.Tensor,
    value: torch.Tensor,
    attention_mask: Optional[torch.Tensor],
    scaling: float,
    dropout: float = 0.0,
    **kwargs: Unpack[TransformersKwargs],
):
    key_states = repeat_kv(key, module.num_key_value_groups)
    value_states = repeat_kv(value, module.num_key_value_groups)

    attn_weights = torch.matmul(query, key_states.transpose(2, 3)) * scaling
    if attention_mask is not None:
        causal_mask = attention_mask[:, :, :, : key_states.shape[-2]]
        attn_weights = attn_weights + causal_mask

    attn_weights = nn.functional.softmax(attn_weights, dim=-1, dtype=torch.float32).to(query.dtype)
    attn_weights = nn.functional.dropout(attn_weights, p=dropout, training=module.training)
    attn_output = torch.matmul(attn_weights, value_states)
    attn_output = attn_output.transpose(1, 2).contiguous()

    return attn_output, attn_weights


class Qwen3VLVisionAttention(nn.Module):
    def __init__(self, config: Qwen3VLVisionConfig) -> None:
        super().__init__()
        self.dim = config.hidden_size
        self.num_heads = config.num_heads
        self.head_dim = self.dim // self.num_heads
        self.num_key_value_groups = 1  # needed for eager attention
        self.qkv = nn.Linear(self.dim, self.dim * 3, bias=True)
        self.proj = nn.Linear(self.dim, self.dim)
        self.scaling = self.head_dim**-0.5
        self.config = config
        self.attention_dropout = 0.0
        self.is_causal = False

    def forward(
        self,
        hidden_states: torch.Tensor,
        cu_seqlens: torch.Tensor,
        rotary_pos_emb: Optional[torch.Tensor] = None,
        position_embeddings: Optional[tuple[torch.Tensor, torch.Tensor]] = None,
        **kwargs,
    ) -> torch.Tensor:
        seq_length = hidden_states.shape[0]
        query_states, key_states, value_states = (
            self.qkv(hidden_states).reshape(seq_length, 3, self.num_heads, -1).permute(1, 0, 2, 3).unbind(0)
        )
        cos, sin = position_embeddings
        query_states, key_states = apply_rotary_pos_emb_vision(query_states, key_states, cos, sin)

        query_states = query_states.transpose(0, 1).unsqueeze(0)
        key_states = key_states.transpose(0, 1).unsqueeze(0)
        value_states = value_states.transpose(0, 1).unsqueeze(0)

        attention_interface: Callable = eager_attention_forward
        if self.config._attn_implementation != "eager":
            attention_interface = ALL_ATTENTION_FUNCTIONS[self.config._attn_implementation]

        if self.config._attn_implementation == "flash_attention_2":
            # Flash Attention 2: Use cu_seqlens for variable length attention
            max_seqlen = (cu_seqlens[1:] - cu_seqlens[:-1]).max()
            attn_output, _ = attention_interface(
                self,
                query_states,
                key_states,
                value_states,
                attention_mask=None,
                scaling=self.scaling,
                dropout=0.0 if not self.training else self.attention_dropout,
                cu_seq_lens_q=cu_seqlens,
                cu_seq_lens_k=cu_seqlens,
                max_length_q=max_seqlen,
                max_length_k=max_seqlen,
                is_causal=False,
                **kwargs,
            )
        else:
            # Other implementations: Process each chunk separately
            lengths = cu_seqlens[1:] - cu_seqlens[:-1]
            splits = [
                torch.split(tensor, lengths.tolist(), dim=2) for tensor in (query_states, key_states, value_states)
            ]

            attn_outputs = [
                attention_interface(
                    self,
                    q,
                    k,
                    v,
                    attention_mask=None,
                    scaling=self.scaling,
                    dropout=0.0 if not self.training else self.attention_dropout,
                    is_causal=False,
                    **kwargs,
                )[0]
                for q, k, v in zip(*splits)
            ]
            attn_output = torch.cat(attn_outputs, dim=1)

        attn_output = attn_output.reshape(seq_length, -1).contiguous()
        attn_output = self.proj(attn_output)
        return attn_output


class Qwen3VLVisionBlock(GradientCheckpointingLayer):
    def __init__(self, config, attn_implementation: str = "sdpa") -> None:
        super().__init__()
        self.norm1 = nn.LayerNorm(config.hidden_size, eps=1e-6)
        self.norm2 = nn.LayerNorm(config.hidden_size, eps=1e-6)
        self.attn = Qwen3VLVisionAttention(config=config)
        self.mlp = Qwen3VLVisionMLP(config=config)

    def forward(
        self,
        hidden_states: torch.Tensor,
        cu_seqlens: torch.Tensor,
        rotary_pos_emb: Optional[torch.Tensor] = None,
        position_embeddings: Optional[tuple[torch.Tensor, torch.Tensor]] = None,
        **kwargs,
    ) -> torch.Tensor:
        hidden_states = hidden_states + self.attn(
            self.norm1(hidden_states),
            cu_seqlens=cu_seqlens,
            rotary_pos_emb=rotary_pos_emb,
            position_embeddings=position_embeddings,
            **kwargs,
        )
        hidden_states = hidden_states + self.mlp(self.norm2(hidden_states))
        return hidden_states


class Qwen3VLTextRotaryEmbedding(nn.Module):
    inv_freq: torch.Tensor  # fix linting for `register_buffer`

    def __init__(self, config: Qwen3VLTextConfig, device=None):
        super().__init__()
        if hasattr(config, "rope_scaling") and config.rope_scaling is not None:
            self.rope_type = config.rope_scaling.get("rope_type", "default")
        else:
            self.rope_type = "default"
        self.max_seq_len_cached = config.max_position_embeddings
        self.original_max_seq_len = config.max_position_embeddings

        self.config = config
        self.rope_init_fn = ROPE_INIT_FUNCTIONS[self.rope_type]

        inv_freq, self.attention_scaling = self.rope_init_fn(self.config, device)
        self.register_buffer("inv_freq", inv_freq, persistent=False)
        self.original_inv_freq = self.inv_freq

        self.mrope_section = config.rope_scaling.get("mrope_section", [24, 20, 20])

    def apply_interleaved_mrope(self, freqs, mrope_section):
        """Apply interleaved MRoPE to 3D rotary embeddings.
        Reorganizes frequency layout from chunked [TTT...HHH...WWW] to
        interleaved [THTHWHTHW...TT], preserving frequency continuity.
        args:
            x: (3, bs, seq_len, head_dim // 2)
            mrope_section: (3,)
        returns:
            x_t: (bs, seq_len, head_dim // 2)
        """
        freqs_t = freqs[0]  # just overwrite the first dimension T
        for dim, offset in enumerate((1, 2), start=1):  # H, W
            length = mrope_section[dim] * 3
            idx = slice(offset, length, 3)
            freqs_t[..., idx] = freqs[dim, ..., idx]
        return freqs_t

    @torch.no_grad()
    @dynamic_rope_update  # power user: used with advanced RoPE types (e.g. dynamic rope)
    def forward(self, x, position_ids):
        # In contrast to other models, Qwen3VL has different position ids for the grids
        # So we expand the inv_freq to shape (3, ...)
        if position_ids.ndim == 2:
            position_ids = position_ids[None, ...].expand(3, position_ids.shape[0], -1)
        inv_freq_expanded = self.inv_freq[None, None, :, None].float().expand(3, position_ids.shape[1], -1, 1)
        position_ids_expanded = position_ids[:, :, None, :].float()  # shape (3, bs, 1, positions)

        device_type = x.device.type if isinstance(x.device.type, str) and x.device.type != "mps" else "cpu"
        with torch.autocast(device_type=device_type, enabled=False):  # Force float32
            freqs = (inv_freq_expanded.float() @ position_ids_expanded.float()).transpose(2, 3)
            freqs = self.apply_interleaved_mrope(freqs, self.mrope_section)
            emb = torch.cat((freqs, freqs), dim=-1)
            cos = emb.cos() * self.attention_scaling
            sin = emb.sin() * self.attention_scaling

        return cos.to(dtype=x.dtype), sin.to(dtype=x.dtype)


@use_kernel_forward_from_hub("RMSNorm")
class Qwen3VLTextRMSNorm(nn.Module):
    def __init__(self, hidden_size, eps: float = 1e-6) -> None:
        """
        Qwen3VLTextRMSNorm is equivalent to T5LayerNorm
        """
        super().__init__()
        self.weight = nn.Parameter(torch.ones(hidden_size))
        self.variance_epsilon = eps

    def forward(self, hidden_states: torch.Tensor) -> torch.Tensor:
        input_dtype = hidden_states.dtype
        hidden_states = hidden_states.to(torch.float32)
        variance = hidden_states.pow(2).mean(-1, keepdim=True)
        hidden_states = hidden_states * torch.rsqrt(variance + self.variance_epsilon)
        return self.weight * hidden_states.to(input_dtype)

    def extra_repr(self):
        return f"{tuple(self.weight.shape)}, eps={self.variance_epsilon}"


def apply_rotary_pos_emb(q, k, cos, sin, position_ids=None, unsqueeze_dim=1):
    """Applies Rotary Position Embedding to the query and key tensors.

    Args:
        q (`torch.Tensor`): The query tensor.
        k (`torch.Tensor`): The key tensor.
        cos (`torch.Tensor`): The cosine part of the rotary embedding.
        sin (`torch.Tensor`): The sine part of the rotary embedding.
        position_ids (`torch.Tensor`, *optional*):
            Deprecated and unused.
        unsqueeze_dim (`int`, *optional*, defaults to 1):
            The 'unsqueeze_dim' argument specifies the dimension along which to unsqueeze cos[position_ids] and
            sin[position_ids] so that they can be properly broadcasted to the dimensions of q and k. For example, note
            that cos[position_ids] and sin[position_ids] have the shape [batch_size, seq_len, head_dim]. Then, if q and
            k have the shape [batch_size, heads, seq_len, head_dim], then setting unsqueeze_dim=1 makes
            cos[position_ids] and sin[position_ids] broadcastable to the shapes of q and k. Similarly, if q and k have
            the shape [batch_size, seq_len, heads, head_dim], then set unsqueeze_dim=2.
    Returns:
        `tuple(torch.Tensor)` comprising of the query and key tensors rotated using the Rotary Position Embedding.
    """
    cos = cos.unsqueeze(unsqueeze_dim)
    sin = sin.unsqueeze(unsqueeze_dim)
    q_embed = (q * cos) + (rotate_half(q) * sin)
    k_embed = (k * cos) + (rotate_half(k) * sin)
    return q_embed, k_embed


class Qwen3VLTextAttention(nn.Module):
    """Multi-headed attention from 'Attention Is All You Need' paper"""

    def __init__(self, config: Qwen3VLTextConfig, layer_idx: int):
        super().__init__()
        self.config = config
        self.layer_idx = layer_idx
        self.head_dim = getattr(config, "head_dim", config.hidden_size // config.num_attention_heads)
        self.num_key_value_groups = config.num_attention_heads // config.num_key_value_heads
        self.scaling = self.head_dim**-0.5
        self.attention_dropout = config.attention_dropout
        self.is_causal = True

        self.q_proj = nn.Linear(
            config.hidden_size, config.num_attention_heads * self.head_dim, bias=config.attention_bias
        )
        self.k_proj = nn.Linear(
            config.hidden_size, config.num_key_value_heads * self.head_dim, bias=config.attention_bias
        )
        self.v_proj = nn.Linear(
            config.hidden_size, config.num_key_value_heads * self.head_dim, bias=config.attention_bias
        )
        self.o_proj = nn.Linear(
            config.num_attention_heads * self.head_dim, config.hidden_size, bias=config.attention_bias
        )
        self.q_norm = Qwen3VLTextRMSNorm(self.head_dim, eps=config.rms_norm_eps)  # unlike olmo, only on the head dim!
        self.k_norm = Qwen3VLTextRMSNorm(
            self.head_dim, eps=config.rms_norm_eps
        )  # thus post q_norm does not need reshape

    @deprecate_kwarg("past_key_value", new_name="past_key_values", version="4.58")
    def forward(
        self,
        hidden_states: torch.Tensor,
        position_embeddings: tuple[torch.Tensor, torch.Tensor],
        attention_mask: Optional[torch.Tensor],
        past_key_values: Optional[Cache] = None,
        cache_position: Optional[torch.LongTensor] = None,
        **kwargs: Unpack[FlashAttentionKwargs],
    ) -> tuple[torch.Tensor, Optional[torch.Tensor]]:
        input_shape = hidden_states.shape[:-1]
        hidden_shape = (*input_shape, -1, self.head_dim)

        query_states = self.q_norm(self.q_proj(hidden_states).view(hidden_shape)).transpose(1, 2)
        key_states = self.k_norm(self.k_proj(hidden_states).view(hidden_shape)).transpose(1, 2)
        value_states = self.v_proj(hidden_states).view(hidden_shape).transpose(1, 2)

        cos, sin = position_embeddings
        query_states, key_states = apply_rotary_pos_emb(query_states, key_states, cos, sin)

        if past_key_values is not None:
            # sin and cos are specific to RoPE models; cache_position needed for the static cache
            cache_kwargs = {"sin": sin, "cos": cos, "cache_position": cache_position}
            key_states, value_states = past_key_values.update(key_states, value_states, self.layer_idx, cache_kwargs)

        attention_interface: Callable = eager_attention_forward
        if self.config._attn_implementation != "eager":
            attention_interface = ALL_ATTENTION_FUNCTIONS[self.config._attn_implementation]

        attn_output, attn_weights = attention_interface(
            self,
            query_states,
            key_states,
            value_states,
            attention_mask,
            dropout=0.0 if not self.training else self.attention_dropout,
            scaling=self.scaling,
            **kwargs,
        )

        attn_output = attn_output.reshape(*input_shape, -1).contiguous()
        attn_output = self.o_proj(attn_output)
        return attn_output, attn_weights


class Qwen3VLTextMLP(nn.Module):
    def __init__(self, config):
        super().__init__()
        self.config = config
        self.hidden_size = config.hidden_size
        self.intermediate_size = config.intermediate_size
        self.gate_proj = nn.Linear(self.hidden_size, self.intermediate_size, bias=False)
        self.up_proj = nn.Linear(self.hidden_size, self.intermediate_size, bias=False)
        self.down_proj = nn.Linear(self.intermediate_size, self.hidden_size, bias=False)
        self.act_fn = ACT2FN[config.hidden_act]

    def forward(self, x):
        down_proj = self.down_proj(self.act_fn(self.gate_proj(x)) * self.up_proj(x))
        return down_proj


class Qwen3VLTextDecoderLayer(GradientCheckpointingLayer):
    def __init__(self, config: Qwen3VLTextConfig, layer_idx: int):
        super().__init__()
        self.hidden_size = config.hidden_size

        self.self_attn = Qwen3VLTextAttention(config=config, layer_idx=layer_idx)

        self.mlp = Qwen3VLTextMLP(config)
        self.input_layernorm = Qwen3VLTextRMSNorm(config.hidden_size, eps=config.rms_norm_eps)
        self.post_attention_layernorm = Qwen3VLTextRMSNorm(config.hidden_size, eps=config.rms_norm_eps)

    @deprecate_kwarg("past_key_value", new_name="past_key_values", version="4.58")
    def forward(
        self,
        hidden_states: torch.Tensor,
        position_embeddings: tuple[torch.Tensor, torch.Tensor],
        attention_mask: Optional[torch.Tensor] = None,
        position_ids: Optional[torch.LongTensor] = None,
        past_key_values: Optional[Cache] = None,
        use_cache: Optional[bool] = False,
        cache_position: Optional[torch.LongTensor] = None,
        **kwargs: Unpack[TransformersKwargs],
    ) -> torch.Tensor:
        residual = hidden_states
        hidden_states = self.input_layernorm(hidden_states)
        # Self Attention
        hidden_states, _ = self.self_attn(
            hidden_states=hidden_states,
            attention_mask=attention_mask,
            position_ids=position_ids,
            past_key_values=past_key_values,
            use_cache=use_cache,
            cache_position=cache_position,
            position_embeddings=position_embeddings,
            **kwargs,
        )
        hidden_states = residual + hidden_states

        # Fully Connected
        residual = hidden_states
        hidden_states = self.post_attention_layernorm(hidden_states)
        hidden_states = self.mlp(hidden_states)
        hidden_states = residual + hidden_states
        return hidden_states


def _colt_activation_checkpointing_enabled() -> bool:
    return os.environ.get("COLT_ACTIVATION_CHECKPOINTING", "0").strip().lower() in {
        "1",
        "true",
        "yes",
        "on",
    }


def _set_colt_cache_layer(
    cache: Cache,
    layer_idx: int,
    key_states: Optional[torch.Tensor],
    value_states: Optional[torch.Tensor],
    sequence_length: Optional[int] = None,
) -> None:
    """Replace one cache layer without mutating tensors tracked by autograd."""
    if not hasattr(cache, "layers") or layer_idx >= len(cache.layers):
        raise TypeError("CoLT activation checkpointing requires a cache with pre-created layers.")
    if (key_states is None) != (value_states is None):
        raise ValueError("CoLT cache key/value states must be provided together.")

    layer = cache.layers[layer_idx]
    if key_states is None:
        layer.keys = None
        layer.values = None
        layer.is_initialized = False
        return

    layer.keys = key_states
    layer.values = value_states
    layer.is_initialized = True
    layer.dtype = key_states.dtype
    layer.device = key_states.device
    if sequence_length is not None and hasattr(layer, "cumulative_length"):
        layer.cumulative_length = sequence_length


def _checkpoint_colt_decoder_layer(
    decoder_layer: nn.Module,
    hidden_states: torch.Tensor,
    attention_mask: Optional[torch.Tensor],
    position_ids: torch.LongTensor,
    past_key_values: Cache,
    cache_position: torch.LongTensor,
    position_embeddings: tuple[torch.Tensor, torch.Tensor],
    config: Qwen3VLTextConfig,
    layer_idx: int,
    layer_kwargs: dict[str, Any],
) -> tuple[torch.Tensor, torch.Tensor, torch.Tensor]:
    """Checkpoint one decoder layer while preserving differentiable KV state.

    The standard Transformers checkpoint wrapper drops ``past_key_values`` because
    mutating a cache during checkpoint recomputation is unsafe. CoLT needs the
    cache for latent recurrence, so the cache layer is made functional here: the
    checkpoint function receives the previous K/V tensors and returns the updated
    tensors as ordinary autograd outputs. The caller installs those outputs into
    the external cache only after the checkpoint call returns.
    """
    if not hasattr(past_key_values, "layers") or layer_idx >= len(past_key_values.layers):
        raise TypeError("CoLT activation checkpointing requires a cache with pre-created layers.")

    cache_layer = past_key_values.layers[layer_idx]
    if cache_layer.is_initialized and cache_layer.keys is not None and cache_layer.keys.numel() > 0:
        past_key_states = cache_layer.keys
        past_value_states = cache_layer.values
        past_sequence_length = cache_layer.get_seq_length()
    else:
        past_key_states = None
        past_value_states = None
        past_sequence_length = 0
    next_sequence_length = past_sequence_length + hidden_states.shape[1]

    def forward_layer(
        layer_hidden_states: torch.Tensor,
        layer_past_key_states: Optional[torch.Tensor],
        layer_past_value_states: Optional[torch.Tensor],
    ) -> tuple[torch.Tensor, torch.Tensor, torch.Tensor]:
        local_cache = DynamicCache(config=config)
        _set_colt_cache_layer(
            local_cache,
            layer_idx,
            layer_past_key_states,
            layer_past_value_states,
            sequence_length=past_sequence_length if layer_past_key_states is not None else None,
        )
        layer_hidden_states = decoder_layer(
            layer_hidden_states,
            attention_mask=attention_mask,
            position_ids=position_ids,
            past_key_values=local_cache,
            cache_position=cache_position,
            position_embeddings=position_embeddings,
            **layer_kwargs,
        )
        updated_layer = local_cache.layers[layer_idx]
        return layer_hidden_states, updated_layer.keys, updated_layer.values

    layer_hidden_states, updated_key_states, updated_value_states = torch_checkpoint(
        forward_layer,
        hidden_states,
        past_key_states,
        past_value_states,
        use_reentrant=False,
    )
    _set_colt_cache_layer(
        past_key_values,
        layer_idx,
        updated_key_states,
        updated_value_states,
        sequence_length=next_sequence_length,
    )
    return layer_hidden_states, updated_key_states, updated_value_states


@dataclass
@auto_docstring(
    custom_intro="""
    Base class for Llava outputs, with hidden states and attentions.
    """
)
class Qwen3VLModelOutputWithPast(ModelOutput):
    r"""
    past_key_values (`Cache`, *optional*, returned when `use_cache=True` is passed or when `config.use_cache=True`):
        It is a [`~cache_utils.Cache`] instance. For more details, see our [kv cache guide](https://huggingface.co/docs/transformers/en/kv_cache).

        Contains pre-computed hidden-states (key and values in the self-attention blocks) that can be used (see
        `past_key_values` input) to speed up sequential decoding.
    rope_deltas (`torch.LongTensor` of shape `(batch_size, )`, *optional*):
        The rope index difference between sequence length and multimodal rope.
    """

    last_hidden_state: Optional[torch.FloatTensor] = None
    past_key_values: Optional[Cache] = None
    hidden_states: Optional[tuple[torch.FloatTensor]] = None
    attentions: Optional[tuple[torch.FloatTensor]] = None
    rope_deltas: Optional[torch.LongTensor] = None


@auto_docstring
class Qwen3VLPreTrainedModel(PreTrainedModel):
    config: Qwen3VLConfig
    base_model_prefix = "model"
    supports_gradient_checkpointing = True
    _no_split_modules = ["Qwen3VLTextDecoderLayer", "Qwen3VLVisionBlock"]
    _skip_keys_device_placement = "past_key_values"
    _supports_flash_attn = True
    _supports_sdpa = True

    _can_compile_fullgraph = True
    _supports_attention_backend = True
    _can_record_outputs = {
        "hidden_states": Qwen3VLTextDecoderLayer,
        "attentions": Qwen3VLTextAttention,
    }

    def _init_weights(self, module):
        # LaRe's native ``nn.MultiheadAttention`` has already performed its
        # constructor initialization.  Re-running its torch reset while ZeRO-3
        # holds a partitioned ``in_proj_weight`` makes the weight appear
        # one-dimensional and crashes Xavier initialization.  Other LaRe
        # modules still follow the ordinary missing-key initialization below;
        # the extractor itself is then reset to its intentional zero-residual
        # safe start.
        if getattr(module, "_colt_lare_constructor_initialized", False):
            return
        super()._init_weights(module)
        if isinstance(module, LaReLatentRefocusingExtractor):
            initializer_range = float(
                getattr(self.config.get_text_config(), "initializer_range", 0.02)
            )
            # Module.apply initializes children before their parent.  Resetting
            # here therefore survives both ordinary post_init and HF's
            # missing-key initialization under ZeRO-3.
            module.reset_safe_output(initializer_range)
            safe_stats = module.safe_initialization_stats()
            if safe_stats is not None:
                output_norm, gate_bias = safe_stats
                print(
                    "[colt-lare] missing-key safe init "
                    f"output_norm={output_norm:.6f} gate_bias={gate_bias:.6f}",
                    flush=True,
                )


class Qwen3VLVisionModel(Qwen3VLPreTrainedModel):
    config: Qwen3VLVisionConfig
    _no_split_modules = ["Qwen3VLVisionBlock"]

    def __init__(self, config, *inputs, **kwargs) -> None:
        super().__init__(config, *inputs, **kwargs)
        self.spatial_merge_size = config.spatial_merge_size
        self.patch_size = config.patch_size
        self.spatial_merge_unit = self.spatial_merge_size * self.spatial_merge_size

        self.patch_embed = Qwen3VLVisionPatchEmbed(
            config=config,
        )

        self.pos_embed = nn.Embedding(config.num_position_embeddings, config.hidden_size)
        self.num_grid_per_side = int(config.num_position_embeddings**0.5)

        head_dim = config.hidden_size // config.num_heads
        self.rotary_pos_emb = Qwen3VLVisionRotaryEmbedding(head_dim // 2)

        self.blocks = nn.ModuleList([Qwen3VLVisionBlock(config) for _ in range(config.depth)])
        self.merger = Qwen3VLVisionPatchMerger(
            config=config,
            use_postshuffle_norm=False,
        )

        self.deepstack_visual_indexes = config.deepstack_visual_indexes
        self.deepstack_merger_list = nn.ModuleList(
            [
                Qwen3VLVisionPatchMerger(
                    config=config,
                    use_postshuffle_norm=True,
                )
                for _ in range(len(config.deepstack_visual_indexes))
            ]
        )

        self.gradient_checkpointing = False

    def rot_pos_emb(self, grid_thw: torch.Tensor) -> torch.Tensor:
        merge_size = self.spatial_merge_size

        max_hw = int(grid_thw[:, 1:].max().item())
        freq_table = self.rotary_pos_emb(max_hw)  # (max_hw, dim // 2)
        device = freq_table.device

        total_tokens = int(torch.prod(grid_thw, dim=1).sum().item())
        pos_ids = torch.empty((total_tokens, 2), dtype=torch.long, device=device)

        offset = 0
        for num_frames, height, width in grid_thw:
            merged_h, merged_w = height // merge_size, width // merge_size

            block_rows = torch.arange(merged_h, device=device)  # block row indices
            block_cols = torch.arange(merged_w, device=device)  # block col indices
            intra_row = torch.arange(merge_size, device=device)  # intra-block row offsets
            intra_col = torch.arange(merge_size, device=device)  # intra-block col offsets

            # Compute full-resolution positions
            row_idx = block_rows[:, None, None, None] * merge_size + intra_row[None, None, :, None]
            col_idx = block_cols[None, :, None, None] * merge_size + intra_col[None, None, None, :]

            row_idx = row_idx.expand(merged_h, merged_w, merge_size, merge_size).reshape(-1)
            col_idx = col_idx.expand(merged_h, merged_w, merge_size, merge_size).reshape(-1)

            coords = torch.stack((row_idx, col_idx), dim=-1)

            if num_frames > 1:
                coords = coords.repeat(num_frames, 1)

            num_tokens = coords.shape[0]
            pos_ids[offset : offset + num_tokens] = coords
            offset += num_tokens

        embeddings = freq_table[pos_ids]  # lookup rotary embeddings
        embeddings = embeddings.flatten(1)
        return embeddings

    def fast_pos_embed_interpolate(self, grid_thw):
        grid_ts, grid_hs, grid_ws = grid_thw[:, 0], grid_thw[:, 1], grid_thw[:, 2]

        idx_list = [[] for _ in range(4)]
        weight_list = [[] for _ in range(4)]

        for t, h, w in zip(grid_ts, grid_hs, grid_ws):
            h_idxs = torch.linspace(0, self.num_grid_per_side - 1, h)
            w_idxs = torch.linspace(0, self.num_grid_per_side - 1, w)

            h_idxs_floor = h_idxs.int()
            w_idxs_floor = w_idxs.int()
            h_idxs_ceil = (h_idxs.int() + 1).clip(max=self.num_grid_per_side - 1)
            w_idxs_ceil = (w_idxs.int() + 1).clip(max=self.num_grid_per_side - 1)

            dh = h_idxs - h_idxs_floor
            dw = w_idxs - w_idxs_floor

            base_h = h_idxs_floor * self.num_grid_per_side
            base_h_ceil = h_idxs_ceil * self.num_grid_per_side

            indices = [
                (base_h[None].T + w_idxs_floor[None]).flatten(),
                (base_h[None].T + w_idxs_ceil[None]).flatten(),
                (base_h_ceil[None].T + w_idxs_floor[None]).flatten(),
                (base_h_ceil[None].T + w_idxs_ceil[None]).flatten(),
            ]

            weights = [
                ((1 - dh)[None].T * (1 - dw)[None]).flatten(),
                ((1 - dh)[None].T * dw[None]).flatten(),
                (dh[None].T * (1 - dw)[None]).flatten(),
                (dh[None].T * dw[None]).flatten(),
            ]

            for i in range(4):
                idx_list[i].extend(indices[i].tolist())
                weight_list[i].extend(weights[i].tolist())

        idx_tensor = torch.tensor(idx_list, dtype=torch.long, device=self.pos_embed.weight.device)
        weight_tensor = torch.tensor(
            weight_list, dtype=self.pos_embed.weight.dtype, device=self.pos_embed.weight.device
        )
        pos_embeds = self.pos_embed(idx_tensor) * weight_tensor[:, :, None]
        patch_pos_embeds = pos_embeds[0] + pos_embeds[1] + pos_embeds[2] + pos_embeds[3]

        patch_pos_embeds = patch_pos_embeds.split([h * w for h, w in zip(grid_hs, grid_ws)])

        patch_pos_embeds_permute = []
        merge_size = self.config.spatial_merge_size
        for pos_embed, t, h, w in zip(patch_pos_embeds, grid_ts, grid_hs, grid_ws):
            pos_embed = pos_embed.repeat(t, 1)
            pos_embed = (
                pos_embed.view(t, h // merge_size, merge_size, w // merge_size, merge_size, -1)
                .permute(0, 1, 3, 2, 4, 5)
                .flatten(0, 4)
            )
            patch_pos_embeds_permute.append(pos_embed)
        patch_pos_embeds = torch.cat(patch_pos_embeds_permute)
        return patch_pos_embeds

    def forward(self, hidden_states: torch.Tensor, grid_thw: torch.Tensor, **kwargs) -> torch.Tensor:
        """
        Args:
            hidden_states (`torch.Tensor` of shape `(seq_len, hidden_size)`):
                The final hidden states of the model.
            grid_thw (`torch.Tensor` of shape `(num_images_or_videos, 3)`):
                The temporal, height and width of feature shape of each image in LLM.

        Returns:
            `torch.Tensor`: hidden_states.
        """
        hidden_states = self.patch_embed(hidden_states)

        pos_embeds = self.fast_pos_embed_interpolate(grid_thw)
        hidden_states = hidden_states + pos_embeds

        rotary_pos_emb = self.rot_pos_emb(grid_thw)

        seq_len, _ = hidden_states.size()
        hidden_states = hidden_states.reshape(seq_len, -1)
        rotary_pos_emb = rotary_pos_emb.reshape(seq_len, -1)
        emb = torch.cat((rotary_pos_emb, rotary_pos_emb), dim=-1)
        position_embeddings = (emb.cos(), emb.sin())

        cu_seqlens = torch.repeat_interleave(grid_thw[:, 1] * grid_thw[:, 2], grid_thw[:, 0]).cumsum(
            dim=0,
            # Select dtype based on the following factors:
            #  - FA2 requires that cu_seqlens_q must have dtype int32
            #  - torch.onnx.export requires that cu_seqlens_q must have same dtype as grid_thw
            # See https://github.com/huggingface/transformers/pull/34852 for more information
            dtype=grid_thw.dtype if torch.jit.is_tracing() else torch.int32,
        )
        cu_seqlens = F.pad(cu_seqlens, (1, 0), value=0)

        deepstack_feature_lists = []
        for layer_num, blk in enumerate(self.blocks):
            hidden_states = blk(
                hidden_states,
                cu_seqlens=cu_seqlens,
                position_embeddings=position_embeddings,
                **kwargs,
            )
            if layer_num in self.deepstack_visual_indexes:
                deepstack_feature = self.deepstack_merger_list[self.deepstack_visual_indexes.index(layer_num)](
                    hidden_states
                )
                deepstack_feature_lists.append(deepstack_feature)

        hidden_states = self.merger(hidden_states)

        return hidden_states, deepstack_feature_lists


@auto_docstring(
    custom_intro=(
        "Text part of Qwen3VL, "
        "not a pure text-only model, as DeepStack integrates visual features into the early hidden states."
    )
)
class Qwen3VLTextModel(Qwen3VLPreTrainedModel):
    config: Qwen3VLTextConfig
    _no_split_modules = ["Qwen3VLTextDecoderLayer"]

    def __init__(self, config: Qwen3VLTextConfig):
        super().__init__(config)
        self.padding_idx = config.pad_token_id
        self.vocab_size = config.vocab_size

        self.embed_tokens = nn.Embedding(config.vocab_size, config.hidden_size, self.padding_idx)
        self.layers = nn.ModuleList(
            [Qwen3VLTextDecoderLayer(config, layer_idx) for layer_idx in range(config.num_hidden_layers)]
        )
        self.norm = Qwen3VLTextRMSNorm(config.hidden_size, eps=config.rms_norm_eps)
        self.rotary_emb = Qwen3VLTextRotaryEmbedding(config=config)
        self.gradient_checkpointing = False

        # Initialize weights and apply final processing
        self.post_init()

    @check_model_inputs
    @auto_docstring
    def forward(
        self,
        input_ids: Optional[torch.LongTensor] = None,
        attention_mask: Optional[torch.Tensor] = None,
        position_ids: Optional[torch.LongTensor] = None,
        past_key_values: Optional[Cache] = None,
        inputs_embeds: Optional[torch.FloatTensor] = None,
        use_cache: Optional[bool] = None,
        cache_position: Optional[torch.LongTensor] = None,
        # args for deepstack
        visual_pos_masks: Optional[torch.Tensor] = None,
        deepstack_visual_embeds: Optional[list[torch.Tensor]] = None,
        **kwargs: Unpack[FlashAttentionKwargs],
    ) -> Union[tuple, BaseModelOutputWithPast]:
        r"""
        visual_pos_masks (`torch.Tensor` of shape `(batch_size, seqlen)`, *optional*):
            The mask of the visual positions.
        deepstack_visual_embeds (`list[torch.Tensor]`, *optional*):
            The deepstack visual embeddings. The shape is (num_layers, visual_seqlen, embed_dim).
            The feature is extracted from the different visual encoder layers, and fed to the decoder
            hidden states. It's from the paper DeepStack(https://arxiv.org/abs/2406.04334).
        """
        # print("In forward function of Qwen3VLTextModel")
        # print(f"input_ids : {input_ids}")
        # print(f"inputs_embeds : {inputs_embeds.shape if inputs_embeds is not None else None}")
        # print(f"position_ids : {position_ids.shape if position_ids is not None else None}")
        # print(f"attention_mask : {attention_mask.shape if attention_mask is not None else None}")
        # print(f"past_key_values : {past_key_values.shape if past_key_values is not None else None}")
        # print(f"cache_position : {cache_position.shape if cache_position is not None else None}")
        if (input_ids is None) ^ (inputs_embeds is not None):
            raise ValueError("You must specify exactly one of input_ids or inputs_embeds")

        # torch.jit.trace() doesn't support cache objects in the output
        if use_cache and past_key_values is None and not torch.jit.is_tracing():
            past_key_values = DynamicCache(config=self.config)
        if inputs_embeds is None:
            inputs_embeds = self.embed_tokens(input_ids)

        if cache_position is None:
            past_seen_tokens = past_key_values.get_seq_length() if past_key_values is not None else 0
            cache_position = torch.arange(
                past_seen_tokens, past_seen_tokens + inputs_embeds.shape[1], device=inputs_embeds.device
            )

        # the hard coded `3` is for temporal, height and width.
        if position_ids is None:
            position_ids = cache_position.view(1, 1, -1).expand(3, inputs_embeds.shape[0], -1)
        elif position_ids.ndim == 2:
            position_ids = position_ids[None, ...].expand(3, position_ids.shape[0], -1)

        if position_ids.ndim == 3 and position_ids.shape[0] == 4:
            text_position_ids = position_ids[0]
            position_ids = position_ids[1:]
        else:
            text_position_ids = position_ids[0]

        attention_mask = create_causal_mask(
            config=self.config,
            input_embeds=inputs_embeds,
            attention_mask=attention_mask,
            cache_position=cache_position,
            past_key_values=past_key_values,
            position_ids=text_position_ids,
        )

        hidden_states = inputs_embeds

        # create position embeddings to be shared across the decoder layers
        position_embeddings = self.rotary_emb(hidden_states, position_ids)

        use_colt_activation_checkpointing = (
            self.training
            and _colt_activation_checkpointing_enabled()
            and past_key_values is not None
        )
        if use_colt_activation_checkpointing and not isinstance(past_key_values, Cache):
            raise TypeError("CoLT activation checkpointing requires a Transformers Cache instance.")

        # decoder layers
        for layer_idx, decoder_layer in enumerate(self.layers):
            if use_colt_activation_checkpointing:
                hidden_states, _, _ = _checkpoint_colt_decoder_layer(
                    decoder_layer=decoder_layer,
                    hidden_states=hidden_states,
                    attention_mask=attention_mask,
                    position_ids=text_position_ids,
                    past_key_values=past_key_values,
                    cache_position=cache_position,
                    position_embeddings=position_embeddings,
                    config=self.config,
                    layer_idx=layer_idx,
                    layer_kwargs=kwargs,
                )
            else:
                layer_outputs = decoder_layer(
                    hidden_states,
                    attention_mask=attention_mask,
                    position_ids=text_position_ids,
                    past_key_values=past_key_values,
                    cache_position=cache_position,
                    position_embeddings=position_embeddings,
                    **kwargs,
                )
                hidden_states = layer_outputs

            # add visual features to the hidden states of first several layers
            if deepstack_visual_embeds is not None and layer_idx in range(len(deepstack_visual_embeds)):
                hidden_states = self._deepstack_process(
                    hidden_states,
                    visual_pos_masks,
                    deepstack_visual_embeds[layer_idx],
                )

        hidden_states = self.norm(hidden_states)

        return BaseModelOutputWithPast(
            last_hidden_state=hidden_states,
            past_key_values=past_key_values,
        )

    def _deepstack_process(
        self, hidden_states: torch.Tensor, visual_pos_masks: torch.Tensor, visual_embeds: torch.Tensor
    ):
        visual_pos_masks = visual_pos_masks.to(hidden_states.device)
        visual_embeds = visual_embeds.to(hidden_states.device, hidden_states.dtype)
        local_this = hidden_states[visual_pos_masks, :].clone() + visual_embeds
        hidden_states[visual_pos_masks, :] = local_this
        return hidden_states


@auto_docstring
class Qwen3VLModel(Qwen3VLPreTrainedModel):
    base_model_prefix = ""
    _checkpoint_conversion_mapping = {}
    # Reference: fix gemma3 grad acc #37208
    accepts_loss_kwargs = False
    config: Qwen3VLConfig
    _no_split_modules = ["Qwen3VLTextDecoderLayer", "Qwen3VLVisionBlock"]

    def __init__(self, config):
        super().__init__(config)
        self.visual = Qwen3VLVisionModel._from_config(config.vision_config)
        self.language_model = Qwen3VLTextModel._from_config(config.text_config)
        self.rope_deltas = None  # cache rope_deltas here
        self._colt_cache_visual_features = (
            os.environ.get("COLT_VISUAL_GROUNDING", "0") == "1"
            or os.environ.get("COLT_LARE_REFOCUS", "0") == "1"
            or (
                "COLT_LARE_REFOCUS" not in os.environ
                and bool(getattr(config, "colt_lare_refocus", False))
            )
        )
        self._colt_visual_embeds = None
        self._colt_image_grid_thw = None

        # Initialize weights and apply final processing
        self.post_init()

    def get_input_embeddings(self):
        return self.language_model.get_input_embeddings()

    def set_input_embeddings(self, value):
        self.language_model.set_input_embeddings(value)

    def set_decoder(self, decoder):
        self.language_model = decoder

    def get_decoder(self):
        return self.language_model

    def get_rope_index(
        self,
        input_ids: Optional[torch.LongTensor] = None,
        image_grid_thw: Optional[torch.LongTensor] = None,
        video_grid_thw: Optional[torch.LongTensor] = None,
        attention_mask: Optional[torch.Tensor] = None,
    ) -> tuple[torch.Tensor, torch.Tensor]:
        """Different from the original implementation, Qwen3VL use timestamps rather than absolute time position ids."""

        # Since we use timestamps to seperate videos, like <t1> <vision_start> <frame1> <vision_end> <t2> <vision_start> <frame2> <vision_end>, the video_grid_thw should also be split
        if video_grid_thw is not None:
            video_grid_thw = torch.repeat_interleave(video_grid_thw, video_grid_thw[:, 0], dim=0)
            video_grid_thw[:, 0] = 1

        spatial_merge_size = self.config.vision_config.spatial_merge_size
        image_token_id = self.config.image_token_id
        video_token_id = self.config.video_token_id
        vision_start_token_id = self.config.vision_start_token_id
        mrope_position_deltas = []
        if input_ids is not None and (image_grid_thw is not None or video_grid_thw is not None):
            total_input_ids = input_ids
            if attention_mask is None:
                attention_mask = torch.ones_like(total_input_ids)
            position_ids = torch.ones(
                3,
                input_ids.shape[0],
                input_ids.shape[1],
                dtype=input_ids.dtype,
                device=input_ids.device,
            )
            image_index, video_index = 0, 0
            attention_mask = attention_mask.to(total_input_ids.device)
            for i, input_ids in enumerate(total_input_ids):
                input_ids = input_ids[attention_mask[i] == 1]
                image_nums, video_nums = 0, 0
                vision_start_indices = torch.argwhere(input_ids == vision_start_token_id).squeeze(1)
                vision_tokens = input_ids[vision_start_indices + 1]
                image_nums = (vision_tokens == image_token_id).sum()
                video_nums = (vision_tokens == video_token_id).sum()
                input_tokens = input_ids.tolist()
                llm_pos_ids_list: list = []
                st = 0
                remain_images, remain_videos = image_nums, video_nums
                for _ in range(image_nums + video_nums):
                    if image_token_id in input_tokens and remain_images > 0:
                        ed_image = input_tokens.index(image_token_id, st)
                    else:
                        ed_image = len(input_tokens) + 1
                    if video_token_id in input_tokens and remain_videos > 0:
                        ed_video = input_tokens.index(video_token_id, st)
                    else:
                        ed_video = len(input_tokens) + 1
                    if ed_image < ed_video:
                        t, h, w = (
                            image_grid_thw[image_index][0],
                            image_grid_thw[image_index][1],
                            image_grid_thw[image_index][2],
                        )
                        image_index += 1
                        remain_images -= 1
                        ed = ed_image

                    else:
                        t, h, w = (
                            video_grid_thw[video_index][0],
                            video_grid_thw[video_index][1],
                            video_grid_thw[video_index][2],
                        )
                        video_index += 1
                        remain_videos -= 1
                        ed = ed_video
                    llm_grid_t, llm_grid_h, llm_grid_w = (
                        t.item(),
                        h.item() // spatial_merge_size,
                        w.item() // spatial_merge_size,
                    )
                    text_len = ed - st

                    st_idx = llm_pos_ids_list[-1].max() + 1 if len(llm_pos_ids_list) > 0 else 0
                    llm_pos_ids_list.append(torch.arange(text_len).view(1, -1).expand(3, -1) + st_idx)

                    # t_index is always 0 because llm_grid_t is always 1 (we use timestamps to encode the temporal information for videos)
                    t_index = torch.arange(llm_grid_t).view(-1, 1).expand(-1, llm_grid_h * llm_grid_w).flatten()
                    h_index = torch.arange(llm_grid_h).view(1, -1, 1).expand(llm_grid_t, -1, llm_grid_w).flatten()
                    w_index = torch.arange(llm_grid_w).view(1, 1, -1).expand(llm_grid_t, llm_grid_h, -1).flatten()
                    llm_pos_ids_list.append(torch.stack([t_index, h_index, w_index]) + text_len + st_idx)
                    st = ed + llm_grid_t * llm_grid_h * llm_grid_w

                if st < len(input_tokens):
                    st_idx = llm_pos_ids_list[-1].max() + 1 if len(llm_pos_ids_list) > 0 else 0
                    text_len = len(input_tokens) - st
                    llm_pos_ids_list.append(torch.arange(text_len).view(1, -1).expand(3, -1) + st_idx)

                llm_positions = torch.cat(llm_pos_ids_list, dim=1).reshape(3, -1)
                position_ids[..., i, attention_mask[i] == 1] = llm_positions.to(position_ids.device)
                mrope_position_deltas.append(llm_positions.max() + 1 - len(total_input_ids[i]))
            mrope_position_deltas = torch.tensor(mrope_position_deltas, device=input_ids.device).unsqueeze(1)
            return position_ids, mrope_position_deltas
        else:
            if attention_mask is not None:
                position_ids = attention_mask.long().cumsum(-1) - 1
                position_ids.masked_fill_(attention_mask == 0, 1)
                position_ids = position_ids.unsqueeze(0).expand(3, -1, -1).to(attention_mask.device)
                max_position_ids = position_ids.max(0, keepdim=False)[0].max(-1, keepdim=True)[0]
                mrope_position_deltas = max_position_ids + 1 - attention_mask.shape[-1]
            else:
                position_ids = (
                    torch.arange(input_ids.shape[1], device=input_ids.device)
                    .view(1, 1, -1)
                    .expand(3, input_ids.shape[0], -1)
                )
                mrope_position_deltas = torch.zeros(
                    [input_ids.shape[0], 1],
                    device=input_ids.device,
                    dtype=input_ids.dtype,
                )

            return position_ids, mrope_position_deltas

    def get_video_features(
        self, pixel_values_videos: torch.FloatTensor, video_grid_thw: Optional[torch.LongTensor] = None
    ):
        """
        Encodes videos into continuous embeddings that can be forwarded to the language model. The deepstack visual features are also returned.

        Args:
            pixel_values_videos (`torch.FloatTensor` of shape `(batch_size, num_channels, image_size, image_size)`):
                The tensors corresponding to the input videos.
            video_grid_thw (`torch.LongTensor` of shape `(num_videos, 3)`, *optional*):
                The temporal, height and width of feature shape of each video in LLM.
        """
        # Same implementation as for images
        return self.get_image_features(pixel_values_videos, video_grid_thw)

    def get_image_features(self, pixel_values: torch.FloatTensor, image_grid_thw: Optional[torch.LongTensor] = None):
        """
        Encodes images into continuous embeddings that can be forwarded to the language model. The deepstack visual features are also returned.

        Args:
            pixel_values (`torch.FloatTensor` of shape `(batch_size, num_channels, image_size, image_size)`):
                The tensors corresponding to the input images.
            image_grid_thw (`torch.LongTensor` of shape `(num_images, 3)`, *optional*):
                The temporal, height and width of feature shape of each image in LLM.
        """
        pixel_values = pixel_values.type(self.visual.dtype)
        image_embeds, deepstack_image_embeds = self.visual(pixel_values, grid_thw=image_grid_thw)
        split_sizes = (image_grid_thw.prod(-1) // self.visual.spatial_merge_size**2).tolist()
        image_embeds = torch.split(image_embeds, split_sizes)
        return image_embeds, deepstack_image_embeds

    def get_placeholder_mask(
        self,
        input_ids: torch.LongTensor,
        inputs_embeds: torch.FloatTensor,
        image_features: Optional[torch.FloatTensor] = None,
        video_features: Optional[torch.FloatTensor] = None,
    ):
        """
        Obtains multimodal placeholder mask from `input_ids` or `inputs_embeds`, and checks that the placeholder token count is
        equal to the length of multimodal features. If the lengths are different, an error is raised.
        """
        if input_ids is None:
            special_image_mask = inputs_embeds == self.get_input_embeddings()(
                torch.tensor(self.config.image_token_id, dtype=torch.long, device=inputs_embeds.device)
            )
            special_image_mask = special_image_mask.all(-1)
            special_video_mask = inputs_embeds == self.get_input_embeddings()(
                torch.tensor(self.config.video_token_id, dtype=torch.long, device=inputs_embeds.device)
            )
            special_video_mask = special_video_mask.all(-1)
        else:
            special_image_mask = input_ids == self.config.image_token_id
            special_video_mask = input_ids == self.config.video_token_id

        n_image_tokens = special_image_mask.sum()
        special_image_mask = special_image_mask.unsqueeze(-1).expand_as(inputs_embeds).to(inputs_embeds.device)
        if image_features is not None and inputs_embeds[special_image_mask].numel() != image_features.numel():
            raise ValueError(
                f"Image features and image tokens do not match: tokens: {n_image_tokens}, features {image_features.shape[0]}"
            )

        n_video_tokens = special_video_mask.sum()
        special_video_mask = special_video_mask.unsqueeze(-1).expand_as(inputs_embeds).to(inputs_embeds.device)
        if video_features is not None and inputs_embeds[special_video_mask].numel() != video_features.numel():
            raise ValueError(
                f"Videos features and video tokens do not match: tokens: {n_video_tokens}, features {video_features.shape[0]}"
            )

        return special_image_mask, special_video_mask

    @auto_docstring
    @check_model_inputs
    def forward(
        self,
        input_ids: torch.LongTensor = None,
        attention_mask: Optional[torch.Tensor] = None,
        position_ids: Optional[torch.LongTensor] = None,
        past_key_values: Optional[Cache] = None,
        inputs_embeds: Optional[torch.FloatTensor] = None,
        pixel_values: Optional[torch.Tensor] = None,
        pixel_values_videos: Optional[torch.FloatTensor] = None,
        image_grid_thw: Optional[torch.LongTensor] = None,
        video_grid_thw: Optional[torch.LongTensor] = None,
        cache_position: Optional[torch.LongTensor] = None,
        # use_cache = False,
        **kwargs: Unpack[TransformersKwargs],
    ) -> Union[tuple, Qwen3VLModelOutputWithPast]:
        r"""
        image_grid_thw (`torch.LongTensor` of shape `(num_images, 3)`, *optional*):
            The temporal, height and width of feature shape of each image in LLM.
        video_grid_thw (`torch.LongTensor` of shape `(num_videos, 3)`, *optional*):
            The temporal, height and width of feature shape of each video in LLM.
        """
        # print("In forward function of Qwen3VL model")
        # print(f"input_ids : {input_ids.shape}")
        # print(f"input_ids : {input_ids}")
        # print(f"pixel_values : {pixel_values.shape if pixel_values is not None else None}")
        # print(f"image_grid_thw : {image_grid_thw if image_grid_thw is not None else None}")
        # print(f"position_ids : {position_ids.shape if position_ids is not None else None}")
        # print(f"attention_mask : {attention_mask.shape if attention_mask is not None else None}")
        # print(f"past_key_values : {past_key_values.shape if past_key_values is not None else None}")
        # print(f"inputs_embeds : {inputs_embeds.shape if inputs_embeds is not None else None}")
        # print(f"cache_position : {cache_position.shape if cache_position is not None else None}")
        if (input_ids is None) ^ (inputs_embeds is not None):
            raise ValueError("You must specify exactly one of input_ids or inputs_embeds")

        if inputs_embeds is None:
            inputs_embeds = self.get_input_embeddings()(input_ids)

        image_mask = None
        video_mask = None

        if pixel_values is not None:
            image_embeds, deepstack_image_embeds = self.get_image_features(pixel_values, image_grid_thw)
            image_embeds = torch.cat(image_embeds, dim=0).to(inputs_embeds.device, inputs_embeds.dtype)
            if self._colt_cache_visual_features:
                self._colt_visual_embeds = image_embeds
                self._colt_image_grid_thw = image_grid_thw
            image_mask, _ = self.get_placeholder_mask(
                input_ids, inputs_embeds=inputs_embeds, image_features=image_embeds
            )
            inputs_embeds = inputs_embeds.masked_scatter(image_mask, image_embeds)

        if pixel_values_videos is not None:
            video_embeds, deepstack_video_embeds = self.get_video_features(pixel_values_videos, video_grid_thw)
            video_embeds = torch.cat(video_embeds, dim=0).to(inputs_embeds.device, inputs_embeds.dtype)
            _, video_mask = self.get_placeholder_mask(
                input_ids, inputs_embeds=inputs_embeds, video_features=video_embeds
            )
            inputs_embeds = inputs_embeds.masked_scatter(video_mask, video_embeds)

        visual_pos_masks = None
        deepstack_visual_embeds = None
        if image_mask is not None and video_mask is not None:
            # aggregate visual_pos_masks and deepstack_visual_embeds
            image_mask = image_mask[..., 0]
            video_mask = video_mask[..., 0]
            visual_pos_masks = image_mask | video_mask
            deepstack_visual_embeds = []
            image_mask_joint = image_mask[visual_pos_masks]
            video_mask_joint = video_mask[visual_pos_masks]
            for img_embed, vid_embed in zip(deepstack_image_embeds, deepstack_video_embeds):
                embed_joint = img_embed.new_zeros(visual_pos_masks.sum(), img_embed.shape[-1]).to(img_embed.device)
                embed_joint[image_mask_joint, :] = img_embed
                embed_joint[video_mask_joint, :] = vid_embed
                deepstack_visual_embeds.append(embed_joint)
        elif image_mask is not None:
            image_mask = image_mask[..., 0]
            visual_pos_masks = image_mask
            deepstack_visual_embeds = deepstack_image_embeds
        elif video_mask is not None:
            video_mask = video_mask[..., 0]
            visual_pos_masks = video_mask
            deepstack_visual_embeds = deepstack_video_embeds

        if position_ids is None:
            attention_mask_tensor = (
                attention_mask if not isinstance(attention_mask, dict) else attention_mask["full_attention"]
            )
            if attention_mask_tensor is not None and attention_mask_tensor.ndim == 4:
                attention_mask_tensor = torch.diagonal(attention_mask_tensor[:, 0], dim1=1, dim2=2)
                # Only apply conversion for floating point tensors (inverted masks)
                if attention_mask_tensor.dtype.is_floating_point:
                    attention_mask_tensor = attention_mask_tensor / torch.finfo(attention_mask_tensor.dtype).min
                    attention_mask_tensor = (1.0 - attention_mask_tensor).int()

            # Calculate RoPE index once per generation in the pre-fill stage only.
            # When compiling, we can't check tensor values thus we check only input length
            # It is safe to assume that `length!=1` means we're in pre-fill because compiled
            # models currently cannot do asssisted decoding
            prefill_compiled_stage = is_torchdynamo_compiling() and (
                (input_ids is not None and input_ids.shape[1] != 1)
                or (inputs_embeds is not None and inputs_embeds.shape[1] != 1)
            )
            prefill_noncompiled_stage = not is_torchdynamo_compiling() and (
                (cache_position is not None and cache_position[0] == 0)
                or (past_key_values is None or past_key_values.get_seq_length() == 0)
            )
            if (prefill_compiled_stage or prefill_noncompiled_stage) or self.rope_deltas is None:
                position_ids, rope_deltas = self.get_rope_index(
                    input_ids,
                    image_grid_thw,
                    video_grid_thw,
                    attention_mask=attention_mask_tensor,
                )
                self.rope_deltas = rope_deltas
            # then use the prev pre-calculated rope-deltas to get the correct position ids
            else:
                batch_size, seq_length, _ = inputs_embeds.shape
                delta = (
                    (cache_position[0] + self.rope_deltas).to(inputs_embeds.device)
                    if cache_position is not None
                    else 0
                )
                position_ids = torch.arange(seq_length, device=inputs_embeds.device)
                position_ids = position_ids.view(1, -1).expand(batch_size, -1)
                if cache_position is not None:  # otherwise `deltas` is an int `0`
                    delta = delta.repeat_interleave(batch_size // delta.shape[0], dim=0)
                position_ids = position_ids.add(delta)
                position_ids = position_ids.unsqueeze(0).expand(3, -1, -1)

        outputs = self.language_model(
            input_ids=None,
            position_ids=position_ids,
            attention_mask=attention_mask,
            past_key_values=past_key_values,
            inputs_embeds=inputs_embeds,
            cache_position=cache_position,
            visual_pos_masks=visual_pos_masks,
            deepstack_visual_embeds=deepstack_visual_embeds,
            # use_cache=use_cache,
            **kwargs,
        )

        return Qwen3VLModelOutputWithPast(
            last_hidden_state=outputs.last_hidden_state,
            past_key_values=outputs.past_key_values,
            rope_deltas=self.rope_deltas,
        )


@dataclass
@auto_docstring(
    custom_intro="""
    Base class for Qwen3VL causal language model (or autoregressive) outputs.
    """
)
class Qwen3VLCausalLMOutputWithPast(ModelOutput):
    r"""
    loss (`torch.FloatTensor` of shape `(1,)`, *optional*, returned when `labels` is provided):
        Language modeling loss (for next-token prediction).
    logits (`torch.FloatTensor` of shape `(batch_size, sequence_length, config.vocab_size)`):
        Prediction scores of the language modeling head (scores for each vocabulary token before SoftMax).
    past_key_values (`Cache`, *optional*, returned when `use_cache=True` is passed or when `config.use_cache=True`):
        It is a [`~cache_utils.Cache`] instance. For more details, see our [kv cache guide](https://huggingface.co/docs/transformers/en/kv_cache).

        Contains pre-computed hidden-states (key and values in the self-attention blocks) that can be used (see
        `past_key_values` input) to speed up sequential decoding.
    rope_deltas (`torch.LongTensor` of shape `(batch_size, )`, *optional*):
        The rope index difference between sequence length and multimodal rope.
    """

    loss: Optional[torch.FloatTensor] = None
    logits: Optional[torch.FloatTensor] = None
    past_key_values: Optional[Cache] = None
    hidden_states: Optional[tuple[torch.FloatTensor]] = None
    attentions: Optional[tuple[torch.FloatTensor]] = None
    rope_deltas: Optional[torch.LongTensor] = None
    k_logits: Optional[torch.FloatTensor] = None
    predicted_k: Optional[torch.LongTensor] = None
    # CoLT RL trajectory action diagnostics.  ``latent_noise`` is the exact
    # standard-normal draw used by each latent transition; it is replayed by
    # actor/reference scoring so rollout and training see the same trajectory.
    latent_noise: Optional[torch.FloatTensor] = None
    latent_log_probs: Optional[torch.FloatTensor] = None

class LowRankProjector(nn.Module):
    def __init__(self, input_dim, output_dim, rank=64):
        super(LowRankProjector, self).__init__()
        self.rank = rank
        self.U = nn.Parameter(torch.randn(input_dim, rank))
        self.V = nn.Parameter(torch.randn(rank, output_dim))

    def forward(self, x):
        return torch.matmul(torch.matmul(x, self.U), self.V)


def extract_think_content_robust(input_ids, think_token_id=151667, end_think_token_id=151668, answer_token_id=9217):

    ids_list = input_ids.tolist() if isinstance(input_ids, torch.Tensor) else input_ids
    # find <think> token from back
    think_start_pos = -1
    for i in range(len(ids_list)-1, -1, -1):
        if ids_list[i] == think_token_id:
            think_start_pos = i
            break
    
    if think_start_pos == -1:
        raise ValueError(f"Unable to find <think> in input_ids")
    
    # Find the first '/think' beginning from 'think_start_pos'
    think_end_pos = -1
    for i in range(think_start_pos + 1, len(ids_list)):
        if ids_list[i] == end_think_token_id:
            think_end_pos = i
            break
    
    if think_end_pos == -1:
        raise ValueError(f"Unable to find </think> in input_ids")
    
    # find <\answer> token from back
    # as qwen3-vl doesn't explicitly encode the <answer> and </answer> tokens, we have to find them based on the 'answer' token
    answer_end_pos = -1
    for i in range(len(ids_list)-1, -1, -1):
        if ids_list[i] == answer_token_id:
            answer_end_pos = i+1 # add the '>' token
            break
    
    if answer_end_pos == -1:
        raise ValueError(f"Unable to find </answer> in input_ids")
    
    # answer_start_pos is the subsquent 2 token of </think> 
    answer_start_pos = think_end_pos + 2 # start from '<' for '<answer>'
    
    # extract CoT thoughts
    question_ids = ids_list[:think_start_pos] # not contain <think>
    content_ids = ids_list[think_start_pos+1:think_end_pos] # not contain <think> and </think>
    answer_ids = ids_list[answer_start_pos:answer_end_pos+4] # contain <answer> and </answer></im_end>\n<|endoftext>
    
    device = input_ids.device
    id_type = input_ids.dtype 
    return torch.tensor(question_ids, device=device, dtype=id_type), torch.tensor(content_ids, device=device, dtype=id_type), torch.tensor(answer_ids, device=device, dtype=id_type)

def split_cot_by_dynamic_boundaries(
    cot_ids: torch.Tensor,
    num_steps: int,
    eos_token_id: int,
    boundary_token_ids: set[int],
    min_step_tokens: int = 8,
):
    """Split visible CoT into the fixed latent-step contract.

    This is the canonical CoLT partition: every latent step has exactly one
    target span, even when a fallback cut is necessary.  Call
    :func:`split_cot_by_dynamic_boundaries_with_metadata` when an auxiliary
    objective also needs to know whether a span is semantically safe to use as
    a teacher target.
    """
    cot_step_id_list, cot_step_len_list, _ = split_cot_by_dynamic_boundaries_with_metadata(
        cot_ids,
        num_steps=num_steps,
        eos_token_id=eos_token_id,
        boundary_token_ids=boundary_token_ids,
        min_step_tokens=min_step_tokens,
    )
    return cot_step_id_list, cot_step_len_list


def split_cot_by_dynamic_boundaries_with_metadata(
    cot_ids: torch.Tensor,
    num_steps: int,
    eos_token_id: int,
    boundary_token_ids: set[int],
    min_step_tokens: int = 8,
):
    """Return CoLT's three spans plus boundary-quality metadata.

    ``teacher_eligible`` does *not* create a second segmentation.  It only
    tells an optional teacher-loss caller whether the exact canonical span was
    bounded without a forced intra-sentence cut.  The main CoLT losses always
    keep all ``num_steps`` spans, including ineligible ones.
    """
    if num_steps <= 0:
        return [], [], {"split_points": [], "split_at_boundary": [], "teacher_eligible": []}

    total_len = cot_ids.shape[0]
    if total_len == 0:
        eos = torch.tensor([eos_token_id], device=cot_ids.device, dtype=cot_ids.dtype)
        return (
            [eos.clone() for _ in range(num_steps)],
            [1 for _ in range(num_steps)],
            {
                "split_points": [0] * (num_steps + 1),
                "split_at_boundary": [False] * (num_steps + 1),
                "teacher_eligible": [False] * num_steps,
            },
        )

    boundaries = [
        idx + 1
        for idx, token_id in enumerate(cot_ids.tolist())
        if token_id in boundary_token_ids and idx + 1 < total_len
    ]
    split_points = [0]
    # The outer CoT boundaries are valid by construction.  Interior entries
    # record whether CoLT found a punctuation/newline boundary or had to fall
    # back to a positional cut.
    split_at_boundary = [True]
    start = 0

    for step_idx in range(1, num_steps):
        remaining_steps = num_steps - step_idx
        remaining_tokens = total_len - start
        dynamic_min_tokens = min(min_step_tokens, max(1, remaining_tokens // (remaining_steps + 1)))
        lower = min(total_len, start + dynamic_min_tokens)
        upper = max(lower, total_len - remaining_steps * dynamic_min_tokens)
        target = round(total_len * step_idx / num_steps)
        target = min(max(target, lower), upper)

        candidates = [pos for pos in boundaries if lower <= pos <= upper]
        if candidates:
            split_at = min(candidates, key=lambda pos: (abs(pos - target), pos))
        else:
            split_at = target

        if split_at <= start:
            split_at = min(total_len, start + 1)
        split_points.append(split_at)
        split_at_boundary.append(split_at in boundaries)
        start = split_at

    split_points.append(total_len)
    split_at_boundary.append(True)

    cot_step_id_list = []
    cot_step_len_list = []
    eos = torch.tensor([eos_token_id], device=cot_ids.device, dtype=cot_ids.dtype)
    for start, end in zip(split_points[:-1], split_points[1:]):
        step_ids = torch.concat([cot_ids[start:end], eos], 0)
        cot_step_id_list.append(step_ids)
        cot_step_len_list.append(end - start + 1)

    teacher_eligible = [
        split_at_boundary[index] and split_at_boundary[index + 1]
        for index in range(num_steps)
    ]
    metadata = {
        "split_points": split_points,
        "split_at_boundary": split_at_boundary,
        "teacher_eligible": teacher_eligible,
    }
    return cot_step_id_list, cot_step_len_list, metadata

def pad_input_ids_by_position(input_ids_list, pad_token_id, max_len=None, device="cuda"):
    """
    Extract input ids from nested list by position, pad each position group to the same length,
    convert to PyTorch Tensor, and return a list of tensors ordered by position.
    
    Args:
        input_ids_list: Nested list in format list[List[Tensor]], where each Tensor is a 1D sequence 
                        of token ids with variable length.
                        Example: [[tensor1_1, tensor1_2], [tensor2_1, tensor2_2], ...]
        pad_token_id: Token id used for padding (usually tokenizer.pad_token_id)
        max_len: Optional, specify target length for padding. If None, automatically use the maximum 
                 length of all samples in the corresponding position.
    
    Returns:
        list[torch.Tensor]: List of tensors ordered by position, each tensor has shape [batch_size, max_seq_len]
                            Example: [padded_tensor_for_position_1, padded_tensor_for_position_2, ...]
    """
    # Step 1: Validate input structure - ensure all sublists have the same length (same number of positions per sample)
    if not input_ids_list:
        return []
    position_num = len(input_ids_list[0])
    for sublist in input_ids_list:
        if len(sublist) != position_num:
            raise ValueError(f"All sublists must have the same length. First sublist has length {position_num}, "
                             f"but found sublist with length {len(sublist)}")
    
    # Step 2: Group tensors by their position index
    position_groups = []
    for pos in range(position_num):
        # Extract the pos-th Tensor from each sample
        pos_tensors = [sublist[pos] for sublist in input_ids_list]
        position_groups.append(pos_tensors)
    
    # Step 3: Pad each position group and convert to Tensor
    result_list = []
    for pos_group in position_groups:
        # Convert tensors to lists for easier processing
        pos_ids = []
        for tensor in pos_group:
            # Ensure each tensor is 1-dimensional (valid token id sequence)
            if tensor.dim() != 1:
                raise ValueError(f"Each token id sequence must be a 1D Tensor, but received Tensor with dimension {tensor.dim()}")
            pos_ids.append(tensor.tolist())
        
        # Determine target padding length for current position
        if max_len is None:
            # Automatically use the maximum length of all samples in current position
            pos_max_len = max(len(ids) for ids in pos_ids) if pos_ids else 0
        else:
            # Use specified max length, truncate sequences longer than max_len
            pos_max_len = max_len
            pos_ids = [ids[:pos_max_len] for ids in pos_ids]
        
        # Perform right-padding (standard in NLP tasks)
        padded_pos = []
        for ids in pos_ids:
            pad_length = pos_max_len - len(ids)
            padded_seq = ids + [pad_token_id] * pad_length
            padded_pos.append(padded_seq)
        
        # Convert padded list to PyTorch LongTensor (standard for token ids)
        pos_tensor = torch.tensor(padded_pos, dtype=torch.long, device=device)
        result_list.append(pos_tensor)
    
    return result_list


def _compute_colt_forward_cot_loss(loss_function, ref_logits, ref_labels, vocab_size, has_targets=True):
    """Apply the causal LM loss exactly once to the full latent-prefix sequence."""
    if not has_targets:
        return ref_logits.sum() * 0.0
    return loss_function(logits=ref_logits, labels=ref_labels, vocab_size=vocab_size)


def _compute_colt_backward_alignment_loss(
    cot_hidden,
    latent_embd,
    projector,
    probe_positions=None,
    active_mask=None,
):
    """Align the latent state to the official fixed textual semantic anchor."""
    if probe_positions is None:
        cot_last_hidden = cot_hidden[:, -1, :]
    else:
        batch_indices = torch.arange(cot_hidden.shape[0], device=cot_hidden.device)
        cot_last_hidden = cot_hidden[batch_indices, probe_positions]
    cot_last_hidden = cot_last_hidden.detach()
    cot_to_latent = projector(cot_last_hidden).unsqueeze(1).to(latent_embd.dtype)
    per_sample_loss = (
        1 - F.cosine_similarity(cot_to_latent.float(), latent_embd.float(), dim=-1)
    ).squeeze(-1)
    if active_mask is None:
        return per_sample_loss.mean()
    active_mask = active_mask.to(device=per_sample_loss.device, dtype=per_sample_loss.dtype)
    active_count = active_mask.sum()
    if active_count.item() == 0:
        return per_sample_loss.sum() * 0.0
    return (per_sample_loss * active_mask).sum() / active_count


def _ensure_colt_decoder_initialized(
    decoder,
    already_checked,
    name_or_path,
    torch_dtype,
    device,
    enable_gradient_checkpointing=False,
    loader=None,
):
    """Check a nested decoder at most once and reload it if its embedding is all zero."""
    if decoder is None or already_checked:
        return decoder, already_checked

    # Set this before any CUDA reduction or reload so failures cannot repeat the scan.
    already_checked = True
    try:
        emb_w = decoder.get_input_embeddings().weight
        if emb_w is None or emb_w.numel() == 0 or emb_w.detach().abs().sum().item() != 0.0:
            return decoder, already_checked

        load_model = loader or AutoModelForCausalLM.from_pretrained
        decoder = load_model(name_or_path, torch_dtype=torch_dtype, resume_download=True).to(device)
        if enable_gradient_checkpointing:
            decoder.gradient_checkpointing_enable()
    except Exception:
        # Preserve the original non-fatal behavior, but never rescan on a later microbatch.
        pass
    return decoder, already_checked


def _pad_colt_sequence(tensor, target_length, value=0):
    pad_length = target_length - tensor.shape[1]
    if pad_length <= 0:
        return tensor
    if tensor.ndim == 2:
        return F.pad(tensor, (0, pad_length), value=value)
    if tensor.ndim == 3:
        return F.pad(tensor, (0, 0, 0, pad_length), value=value)
    raise ValueError(f"Expected a rank-2 or rank-3 sequence tensor, got shape {tuple(tensor.shape)}")


def _colt_aux_max_batch_tokens():
    try:
        return max(int(os.environ.get("COLT_AUX_MAX_BATCH_TOKENS", "4096")), 1)
    except ValueError:
        return 4096


def _chunk_colt_records(records, tensor_key, max_batch_tokens):
    """Greedily bound each auxiliary call by batch size times padded length."""
    chunks = []
    current_chunk = []
    current_batch_size = 0
    current_max_length = 0
    for record in records:
        tensor = record[tensor_key]
        record_batch_size, record_length = tensor.shape[:2]
        candidate_batch_size = current_batch_size + record_batch_size
        candidate_max_length = max(current_max_length, record_length)
        if current_chunk and candidate_batch_size * candidate_max_length > max_batch_tokens:
            chunks.append(current_chunk)
            current_chunk = []
            current_batch_size = 0
            current_max_length = 0

        current_chunk.append(record)
        current_batch_size += record_batch_size
        current_max_length = max(current_max_length, record_length)

    if current_chunk:
        chunks.append(current_chunk)
    return chunks


def _synchronize_colt_chunk_count(local_chunk_count, device):
    """Keep ZeRO-3 auxiliary decoder call counts identical on every rank."""
    if not (torch.distributed.is_available() and torch.distributed.is_initialized()):
        return local_chunk_count
    synchronized_count = torch.tensor(local_chunk_count, dtype=torch.long, device=device)
    torch.distributed.all_reduce(synchronized_count, op=torch.distributed.ReduceOp.MAX)
    return int(synchronized_count.item())


def _synchronize_colt_sequence_length(local_length, device):
    """Use one auxiliary-decoder sequence length on every ZeRO-3 rank."""
    if not (torch.distributed.is_available() and torch.distributed.is_initialized()):
        return local_length
    synchronized_length = torch.tensor(local_length, dtype=torch.long, device=device)
    torch.distributed.all_reduce(synchronized_length, op=torch.distributed.ReduceOp.MAX)
    return int(synchronized_length.item())


def _make_minimal_forward_dummy(record):
    inputs_embeds = record["inputs_embeds"][:1, :1]
    return {
        "inputs_embeds": inputs_embeds,
        "attention_mask": torch.ones(inputs_embeds.shape[:2], dtype=torch.long, device=inputs_embeds.device),
        "position_ids": torch.zeros(inputs_embeds.shape[:2], dtype=torch.long, device=inputs_embeds.device),
        "labels": torch.full(inputs_embeds.shape[:2], -100, dtype=torch.long, device=inputs_embeds.device),
        "has_targets": False,
    }


def _make_minimal_backward_dummy(record):
    input_ids = record["input_ids"][:1, -1:]
    return {
        "input_ids": input_ids,
        "attention_mask": torch.ones_like(input_ids),
        "probe_positions": torch.zeros((1,), dtype=torch.long, device=input_ids.device),
        "latent_embd": record["latent_embd"][:1],
        "active": False,
        "active_mask": torch.zeros((1,), dtype=torch.bool, device=input_ids.device),
    }


def _run_colt_forward_decoder_steps(
    decoder,
    projector,
    loss_function,
    records,
    vocab_size,
    batched,
    max_batch_tokens=None,
):
    """Run latent-to-CoT supervision while preserving equal weighting across latent steps."""
    if not records:
        return []

    if not batched:
        losses = []
        for record in records:
            original_length = record["inputs_embeds"].shape[1]
            synchronized_length = _synchronize_colt_sequence_length(
                original_length, record["inputs_embeds"].device
            )
            inputs_embeds = _pad_colt_sequence(record["inputs_embeds"], synchronized_length)
            attention_mask = _pad_colt_sequence(record["attention_mask"], synchronized_length)
            position_ids = _pad_colt_sequence(record["position_ids"], synchronized_length)
            outputs = decoder(
                inputs_embeds=inputs_embeds,
                attention_mask=attention_mask,
                position_ids=position_ids,
                use_cache=False,
            )
            logits = projector(outputs.logits)[:, :original_length]
            losses.append(
                _compute_colt_forward_cot_loss(
                    loss_function,
                    logits,
                    record["labels"],
                    vocab_size,
                    has_targets=record["has_targets"],
                )
            )
        return losses

    active_records = [record for record in records if record["has_targets"]]
    chunks = _chunk_colt_records(
        active_records,
        "inputs_embeds",
        max_batch_tokens or _colt_aux_max_batch_tokens(),
    )
    synchronized_chunk_count = _synchronize_colt_chunk_count(len(chunks), records[0]["inputs_embeds"].device)
    dummy_record = _make_minimal_forward_dummy(records[0])
    record_positions = {id(record): index for index, record in enumerate(records)}
    losses = [record["inputs_embeds"][:1, :1].sum() * 0.0 for record in records]
    synchronization_loss = records[0]["inputs_embeds"][:1, :1].sum() * 0.0

    for chunk_index in range(synchronized_chunk_count):
        chunk = chunks[chunk_index] if chunk_index < len(chunks) else [dummy_record]
        local_max_length = max(record["inputs_embeds"].shape[1] for record in chunk)
        # Different ranks can own CoT steps of very different lengths.  ZeRO-3
        # also requires the auxiliary decoder's shape-dependent execution path
        # to match, so pad each synchronized chunk to the global maximum.
        max_length = _synchronize_colt_sequence_length(
            local_max_length, records[0]["inputs_embeds"].device
        )
        batch_sizes = [record["inputs_embeds"].shape[0] for record in chunk]
        inputs_embeds = torch.cat(
            [_pad_colt_sequence(record["inputs_embeds"], max_length) for record in chunk], dim=0
        )
        attention_mask = torch.cat(
            [_pad_colt_sequence(record["attention_mask"], max_length) for record in chunk], dim=0
        )
        position_ids = torch.cat(
            [_pad_colt_sequence(record["position_ids"], max_length) for record in chunk], dim=0
        )
        outputs = decoder(
            inputs_embeds=inputs_embeds,
            attention_mask=attention_mask,
            position_ids=position_ids,
            use_cache=False,
        )
        step_logits = projector(outputs.logits).split(batch_sizes, dim=0)

        if chunk_index >= len(chunks):
            synchronization_loss = synchronization_loss + step_logits[0].sum() * 0.0
            continue
        for logits, record in zip(step_logits, chunk):
            original_length = record["inputs_embeds"].shape[1]
            losses[record_positions[id(record)]] = _compute_colt_forward_cot_loss(
                loss_function,
                logits[:, :original_length],
                record["labels"],
                vocab_size,
                has_targets=True,
            )
    losses[0] = losses[0] + synchronization_loss
    return losses


def _get_colt_decoder_backbone(decoder):
    return decoder.get_decoder() if hasattr(decoder, "get_decoder") else getattr(decoder, "model", None)


def _run_colt_backward_decoder_steps(
    decoder,
    projector,
    records,
    pad_token_id,
    batched,
    max_batch_tokens=None,
):
    """Run CoT-to-latent supervision and select each step's original probe position."""
    if not records:
        return []

    decoder_backbone = _get_colt_decoder_backbone(decoder)

    def run_backbone(input_ids, attention_mask):
        if decoder_backbone is not None:
            return decoder_backbone(input_ids=input_ids, attention_mask=attention_mask, use_cache=False)[0]
        outputs = decoder(
            input_ids=input_ids,
            attention_mask=attention_mask,
            use_cache=False,
            output_hidden_states=True,
        )
        return outputs.hidden_states[-1]

    if not batched:
        losses = []
        for record in records:
            original_length = record["input_ids"].shape[1]
            synchronized_length = _synchronize_colt_sequence_length(
                original_length, record["input_ids"].device
            )
            input_ids = _pad_colt_sequence(record["input_ids"], synchronized_length, value=pad_token_id)
            attention_mask = _pad_colt_sequence(record["attention_mask"], synchronized_length)
            with torch.no_grad():
                hidden = run_backbone(input_ids, attention_mask)
            loss = _compute_colt_backward_alignment_loss(
                hidden,
                record["latent_embd"],
                projector,
                probe_positions=record["probe_positions"],
                active_mask=record.get("active_mask"),
            )
            losses.append(loss)
        return losses

    active_records = [record for record in records if record.get("active", True)]
    chunks = _chunk_colt_records(
        active_records,
        "input_ids",
        max_batch_tokens or _colt_aux_max_batch_tokens(),
    )
    synchronized_chunk_count = _synchronize_colt_chunk_count(len(chunks), records[0]["input_ids"].device)
    dummy_record = _make_minimal_backward_dummy(records[0])
    record_positions = {id(record): index for index, record in enumerate(records)}
    losses = [record["latent_embd"].float().sum() * 0.0 for record in records]
    synchronization_loss = records[0]["latent_embd"].float().sum() * 0.0

    for chunk_index in range(synchronized_chunk_count):
        chunk = chunks[chunk_index] if chunk_index < len(chunks) else [dummy_record]
        local_max_length = max(record["input_ids"].shape[1] for record in chunk)
        # Match the forward auxiliary path: synchronize the padded length so
        # the frozen backward decoder follows an identical ZeRO-3 call graph.
        max_length = _synchronize_colt_sequence_length(
            local_max_length, records[0]["input_ids"].device
        )
        batch_sizes = [record["input_ids"].shape[0] for record in chunk]
        input_ids = torch.cat(
            [_pad_colt_sequence(record["input_ids"], max_length, value=pad_token_id) for record in chunk], dim=0
        )
        attention_mask = torch.cat(
            [_pad_colt_sequence(record["attention_mask"], max_length) for record in chunk], dim=0
        )
        with torch.no_grad():
            hidden = run_backbone(input_ids, attention_mask)
        probe_positions = torch.cat([record["probe_positions"] for record in chunk], dim=0)
        batch_indices = torch.arange(hidden.shape[0], device=hidden.device)
        cot_last_hidden = hidden[batch_indices, probe_positions].detach()
        projected_anchors = projector(cot_last_hidden).unsqueeze(1).split(batch_sizes, dim=0)

        if chunk_index >= len(chunks):
            dummy_anchor = projected_anchors[0].to(dummy_record["latent_embd"].dtype)
            synchronization_loss = synchronization_loss + (
                1
                - F.cosine_similarity(
                    dummy_anchor.float(),
                    dummy_record["latent_embd"].float(),
                    dim=-1,
                ).mean()
            ) * 0.0
            continue
        for anchor, record in zip(projected_anchors, chunk):
            anchor = anchor.to(record["latent_embd"].dtype)
            per_sample_loss = 1 - F.cosine_similarity(
                anchor.float(), record["latent_embd"].float(), dim=-1
            ).squeeze(-1)
            active_mask = record.get("active_mask")
            if active_mask is None:
                losses[record_positions[id(record)]] = per_sample_loss.mean()
            else:
                active_mask = active_mask.to(
                    device=per_sample_loss.device,
                    dtype=per_sample_loss.dtype,
                )
                active_count = active_mask.sum()
                if active_count.item() == 0:
                    losses[record_positions[id(record)]] = per_sample_loss.sum() * 0.0
                else:
                    losses[record_positions[id(record)]] = (
                        per_sample_loss * active_mask
                    ).sum() / active_count
    losses[0] = losses[0] + synchronization_loss
    return losses


def _is_colt_paper_faithful_enabled():
    return os.environ.get("COLT_PAPER_FAITHFUL", "0").strip().lower() in {"1", "true", "yes", "on"}


def _is_colt_aux_batching_enabled():
    return os.environ.get("COLT_BATCH_AUX_DECODERS", "1").strip().lower() in {"1", "true", "yes", "on"}


def _is_colt_rl_mode_enabled():
    return os.environ.get("COLT_RL_MODE", "0").strip().lower() in {"1", "true", "yes", "on"}


COLT_ANSWER_VISIBILITIES = {"full", "latent_only"}


def _resolve_colt_answer_visibility(environ: Optional[Mapping[str, str]] = None) -> str:
    environ = os.environ if environ is None else environ
    visibility = environ.get("COLT_ANSWER_VISIBILITY", "full").strip().lower()
    if visibility not in COLT_ANSWER_VISIBILITIES:
        choices = ", ".join(sorted(COLT_ANSWER_VISIBILITIES))
        raise ValueError(f"COLT_ANSWER_VISIBILITY must be one of {choices}, got {visibility!r}")
    return visibility


def _resolve_colt_lare_bool(config, env_name: str, config_name: str, default: bool) -> bool:
    raw_value = os.environ.get(env_name)
    if raw_value is None:
        return bool(getattr(config, config_name, default))
    normalized = raw_value.strip().lower()
    if normalized in {"1", "true", "yes", "on"}:
        return True
    if normalized in {"0", "false", "no", "off"}:
        return False
    raise ValueError(f"{env_name} must be a boolean flag, got {raw_value!r}")


def _resolve_colt_lare_value(config, env_name: str, config_name: str, default, cast):
    raw_value = os.environ.get(env_name)
    return cast(getattr(config, config_name, default) if raw_value is None else raw_value)


def _is_colt_bootstrap_enabled():
    return os.environ.get("COLT_BOOTSTRAP_ENABLED", "0").strip().lower() in {"1", "true", "yes", "on"}


def _colt_bootstrap_float(name, default):
    raw_value = os.environ.get(name, str(default)).strip()
    try:
        value = float(raw_value)
    except ValueError as exc:
        raise ValueError(f"{name} must be a finite non-negative float, got {raw_value!r}") from exc
    if not math.isfinite(value) or value < 0:
        raise ValueError(f"{name} must be a finite non-negative float, got {raw_value!r}")
    return value


def _is_colt_bootstrap_stopgrad_h_enabled():
    return os.environ.get("COLT_BOOTSTRAP_STOPGRAD_H", "1").strip().lower() in {
        "1",
        "true",
        "yes",
        "on",
    }


def _is_colt_rank_zero():
    if torch.distributed.is_available() and torch.distributed.is_initialized():
        return torch.distributed.get_rank() == 0
    return int(os.environ.get("RANK", "0")) == 0


def _synchronize_colt_oracle_k(local_k, device):
    """Return the largest GT K so ZeRO-3 ranks execute identical module calls."""
    if not (torch.distributed.is_available() and torch.distributed.is_initialized()):
        return local_k
    synchronized_k = torch.tensor(local_k, dtype=torch.long, device=device)
    torch.distributed.all_reduce(synchronized_k, op=torch.distributed.ReduceOp.MAX)
    return int(synchronized_k.item())


def _colt_component_log_interval():
    try:
        return max(int(os.environ.get("COLT_COMPONENT_LOG_EVERY", "8")), 0)
    except ValueError:
        return 8


class Qwen3VLForConditionalGeneration(Qwen3VLPreTrainedModel, GenerationMixin):
    _checkpoint_conversion_mapping = {}
    _tied_weights_keys = ["lm_head.weight"]
    _keys_to_ignore_on_load_unexpected = [
        r"^(decoder|backward_decoder|pj_in|pj_out|pj_back)\."
    ]
    # Reference: fix gemma3 grad acc #37208
    accepts_loss_kwargs = False
    config: Qwen3VLConfig

    def __init__(self, config):
        super().__init__(config)
        self.model = Qwen3VLModel(config)
        self.lm_head = nn.Linear(config.text_config.hidden_size, config.text_config.vocab_size, bias=False)
        self.paper_faithful = _is_colt_paper_faithful_enabled()
        self.colt_rl_mode = _is_colt_rl_mode_enabled()
        self.batch_aux_decoders = self.paper_faithful and _is_colt_aux_batching_enabled()
        self._colt_forward_microbatch_count = 0
        self.inference_latent_transition = resolve_colt_inference_latent_transition()
        oracle_k_settings = resolve_oracle_k_settings(config)
        self.oracle_k_enabled = oracle_k_settings.enabled
        self.oracle_k_max = oracle_k_settings.max_k
        self.oracle_k_budget_conditioning = oracle_k_settings.budget_conditioning
        self.oracle_k_predictor_enabled = oracle_k_settings.predictor_enabled
        self.oracle_k_predictor_loss_weight = oracle_k_settings.predictor_loss_weight
        self.oracle_k_dynamic_inference = oracle_k_settings.dynamic_inference
        self.last_oracle_k_prediction = None
        self.last_oracle_k_used = None
        self.last_oracle_k_conditioning = None
        self._oracle_k_predictor_preflight_done = False
        self._oracle_k_first_batch_logged = False
        self._oracle_k_metric_loss_sum = None
        self._oracle_k_metric_correct = None
        self._oracle_k_metric_count = None
        if self.oracle_k_enabled and self.oracle_k_predictor_enabled:
            self.oracle_k_predictor = OracleKPredictor(
                self.oracle_k_max,
                config.text_config.hidden_size,
            )
        else:
            self.oracle_k_predictor = None
        # NOTE: When training under some sharding/initialization contexts (e.g. init_empty_weights / ZeRO init),
        # loading a nested decoder inside __init__ can silently produce zero/empty parameters.
        # We still initialize here, but also support lazy re-loading in forward if we detect zeroed weights.
        self.latent_reasoning_mode = os.environ.get("COLT_DISABLE_LATENT_REASONING", "0") != "1"
        if not self.latent_reasoning_mode:
            self.post_init()
            return
        self.decoder = None
        self.backward_decoder = None
        self._decoder_name_or_path = os.environ.get("COLT_DECODER_MODEL_PATH", "Qwen/Qwen3-0.6B")
        if self.training and not self.colt_rl_mode:
            self.decoder = AutoModelForCausalLM.from_pretrained(
                self._decoder_name_or_path,
                torch_dtype=config.text_config.dtype,
                resume_download=True,
            )
            self.backward_decoder = AutoModelForCausalLM.from_pretrained(
                self._decoder_name_or_path,
                torch_dtype=config.text_config.dtype,
                resume_download=True,
            )
        self._decoder_reload_attempted = False
        self._backward_decoder_reload_attempted = False
        
        if self.decoder is not None:
            if self.lm_head.in_features == self.decoder.lm_head.in_features:
                self.pj_in = nn.Identity()
                self.pj_back = nn.Identity()
            else:
                self.pj_in = nn.Sequential(nn.Linear(self.lm_head.in_features, self.decoder.lm_head.in_features), nn.LayerNorm(self.decoder.lm_head.in_features),)
                self.pj_back = nn.Sequential(
                    nn.Linear(self.decoder.lm_head.in_features, self.lm_head.in_features),
                    nn.LayerNorm(self.lm_head.in_features),
                )
            input_dim = self.decoder.lm_head.out_features
            output_dim = self.lm_head.out_features
            if input_dim == output_dim:
                self.pj_out = nn.Identity()
            else:
                self.pj_out = LowRankProjector(input_dim, output_dim, rank=input_dim // 4)
        else:
            self.pj_in = nn.Identity()
            self.pj_out = nn.Identity()
            self.pj_back = nn.Identity()

        self.num_latent = 3
        if self.oracle_k_enabled and self.oracle_k_budget_conditioning:
            self.oracle_k_conditioner = OracleKBudgetConditioner(
                self.oracle_k_max,
                config.text_config.hidden_size,
            )
        else:
            self.oracle_k_conditioner = None
        self.prj = nn.Sequential(
                nn.Dropout(0.0),
                nn.Linear(config.text_config.hidden_size, config.text_config.hidden_size//2),
                nn.GELU(),
                nn.Linear(config.text_config.hidden_size//2, config.text_config.hidden_size),
                nn.LayerNorm(config.text_config.hidden_size),
            )
        # The residual latent transition must start as an identity.  The base
        # Qwen checkpoint has no ``prj`` keys, so relying on an arbitrary
        # missing-key initialization can create a huge residual before the
        # first optimizer step (and overflow the next cached decoder call).
        # Zeroing the last projection preserves the intended learnable path
        # while making the initial transition numerically safe.
        nn.init.zeros_(self.prj[3].weight)
        nn.init.zeros_(self.prj[3].bias)
        self.backward_align_weight = 0.2
        self.forward_align_weight = 0.2
        self.prediction_weight = 0.2
        self.bootstrap_enabled = _is_colt_bootstrap_enabled()
        self.bootstrap_med_weight = _colt_bootstrap_float("COLT_BOOTSTRAP_MEDIATED_WEIGHT", 1.0)
        self.bootstrap_kl_weight = _colt_bootstrap_float("COLT_BOOTSTRAP_KL_WEIGHT", 0.5)
        self.bootstrap_med_prob = _colt_bootstrap_float("COLT_BOOTSTRAP_MEDIATED_PROB", 0.5)
        if self.bootstrap_med_prob > 1.0:
            raise ValueError(
                "COLT_BOOTSTRAP_MEDIATED_PROB must be in [0, 1], "
                f"got {self.bootstrap_med_prob}"
            )
        self.bootstrap_stopgrad_h = _is_colt_bootstrap_stopgrad_h_enabled()
        if self.bootstrap_enabled:
            # The bootstrap experiment deliberately isolates factual CE and the
            # trajectory-level mediated CE/KL.  Existing step-level auxiliary
            # objectives are disabled for this experiment only.
            self.forward_align_weight = 0.0
            self.backward_align_weight = 0.0
            self.prediction_weight = 0.0
        self._bootstrap_forward_microbatch_count = 0
        # Two-stage question-latent curriculum, Stage 1. This is intentionally
        # separate from the older bootstrap experiment: it keeps the original
        # question sequence length and mRoPE positions, zeroes only visual
        # placeholders, and conditions the answer on *only* the final latent.
        self.causal_grounded_latent_enabled = _resolve_colt_lare_bool(
            config,
            "COLT_CAUSAL_GROUNDED_LATENT",
            "colt_causal_grounded_latent",
            False,
        )
        self.causal_grounded_roi_weight = _resolve_colt_lare_value(
            config,
            "COLT_CAUSAL_GROUNDED_ROI_WEIGHT",
            "colt_causal_grounded_roi_weight",
            0.0,
            float,
        )
        self.causal_grounded_geometry_weight = _resolve_colt_lare_value(
            config,
            "COLT_CAUSAL_GROUNDED_GEOMETRY_WEIGHT",
            "colt_causal_grounded_geometry_weight",
            0.0,
            float,
        )
        self.causal_grounded_inference_mediated = _resolve_colt_lare_bool(
            config,
            "COLT_CAUSAL_GROUNDED_INFERENCE_MEDIATED",
            "colt_causal_grounded_inference_mediated",
            False,
        )
        if not math.isfinite(self.causal_grounded_roi_weight) or self.causal_grounded_roi_weight < 0:
            raise ValueError("COLT_CAUSAL_GROUNDED_ROI_WEIGHT must be a finite non-negative float.")
        if not math.isfinite(self.causal_grounded_geometry_weight) or self.causal_grounded_geometry_weight < 0:
            raise ValueError("COLT_CAUSAL_GROUNDED_GEOMETRY_WEIGHT must be a finite non-negative float.")
        if self.causal_grounded_latent_enabled and (
            self.causal_grounded_roi_weight != 0.0 or self.causal_grounded_geometry_weight != 0.0
        ):
            raise ValueError(
                "The documented Stage-1 causal-grounded objective has ROI/geometry weights fixed at 0.0; "
                "non-zero values would be a different experiment."
            )
        if self.causal_grounded_inference_mediated:
            raise ValueError(
                "COLT_CAUSAL_GROUNDED_INFERENCE_MEDIATED=1 is not implemented: Stage 1 is a training-only "
                "curriculum and its documented inference setting is 0."
            )
        if self.causal_grounded_latent_enabled:
            config.colt_causal_grounded_latent = True
            config.colt_causal_grounded_roi_weight = self.causal_grounded_roi_weight
            config.colt_causal_grounded_geometry_weight = self.causal_grounded_geometry_weight
            config.colt_causal_grounded_inference_mediated = self.causal_grounded_inference_mediated
        self.latent_predictor = nn.Sequential(
            nn.Linear(config.text_config.hidden_size, config.text_config.hidden_size),
            nn.GELU(),
            nn.Linear(config.text_config.hidden_size, config.text_config.hidden_size),
            nn.LayerNorm(config.text_config.hidden_size),
        )
        self.stochastic_latent_enabled = os.environ.get("COLT_STOCHASTIC_LATENT", "0") == "1"
        self.latent_noise_std = float(os.environ.get("COLT_LATENT_NOISE_STD", "0.1"))
        self.latent_temperature = float(os.environ.get("COLT_LATENT_TEMPERATURE", "1.0"))
        self.image_mask_prob = float(os.environ.get("COLT_IMAGE_MASK_PROB", "0.0"))
        self.answer_visibility = _resolve_colt_answer_visibility()
        self.latent_stochastic_head = LatentStochasticHead(config.text_config.hidden_size)
        self.lowrank_exploration_enabled = os.environ.get("COLT_LOWRANK_EXPLORE", "0") == "1"
        self.lowrank_rank = int(os.environ.get("COLT_LOWRANK_RANK", "16"))
        self.lowrank_exploration_head = (
            LowRankExplorationHead(config.text_config.hidden_size, rank=self.lowrank_rank)
            if self.lowrank_exploration_enabled
            else None
        )
        self.visual_grounding_enabled = os.environ.get("COLT_VISUAL_GROUNDING", "0") == "1"
        self.visual_grounding_weight = float(os.environ.get("COLT_VISUAL_GROUNDING_WEIGHT", "0.1"))
        self.visual_grounding_temperature = float(
            os.environ.get("COLT_GROUNDING_TEMPERATURE", "0.07")
        )
        global _COLT_TEACHER_LOADING
        self.lare_refocus_enabled = _resolve_colt_lare_bool(
            config, "COLT_LARE_REFOCUS", "colt_lare_refocus", False
        )
        self.lare_extractor_dim = _resolve_colt_lare_value(
            config, "COLT_LARE_DIM", "colt_lare_dim", 1536, int
        )
        self.lare_layers = _resolve_colt_lare_value(
            config, "COLT_LARE_LAYERS", "colt_lare_layers", 2, int
        )
        self.lare_heads = _resolve_colt_lare_value(
            config, "COLT_LARE_HEADS", "colt_lare_heads", 12, int
        )
        self.lare_queries = _resolve_colt_lare_value(
            config, "COLT_LARE_QUERIES", "colt_lare_queries", 4, int
        )
        self.lare_max_steps = _resolve_colt_lare_value(
            config, "COLT_LARE_MAX_STEPS", "colt_lare_max_steps", 16, int
        )
        self.lare_dropout = _resolve_colt_lare_value(
            config, "COLT_LARE_DROPOUT", "colt_lare_dropout", 0.0, float
        )
        self.lare_visual_dropout = _resolve_colt_lare_value(
            config, "COLT_LARE_VISUAL_DROPOUT", "colt_lare_visual_dropout", 0.1, float
        )
        self.lare_attention_topk = _resolve_colt_lare_value(
            config, "COLT_LARE_ATTN_TOPK", "colt_lare_attention_topk", 0, int
        )
        self.lare_gate_bias = _resolve_colt_lare_value(
            config, "COLT_LARE_GATE_BIAS", "colt_lare_gate_bias", -2.0, float
        )
        self.lare_reconstruction_weight = _resolve_colt_lare_value(
            config, "COLT_LARE_RECON_WEIGHT", "colt_lare_reconstruction_weight", 0.1, float
        )
        self.lare_reconstruction_steps = _resolve_colt_lare_value(
            config, "COLT_LARE_RECON_STEPS", "colt_lare_reconstruction_steps", 1000, int
        )
        self.lare_detach_visual = _resolve_colt_lare_bool(
            config, "COLT_LARE_DETACH_VISUAL", "colt_lare_detach_visual", True
        )
        self.lare_record_attention = _resolve_colt_lare_bool(
            config, "COLT_LARE_RECORD_ATTENTION", "colt_lare_record_attention", False
        )
        self.cot_attention_align_enabled = _resolve_colt_lare_bool(
            config, "COLT_COT_ATTN_ALIGN", "colt_cot_attention_align", False
        )
        self.cot_attention_align_weight = _resolve_colt_lare_value(
            config, "COLT_COT_ATTN_ALIGN_WEIGHT", "colt_cot_attention_align_weight", 0.05, float
        )
        self.cot_attention_min_confidence = _resolve_colt_lare_value(
            config,
            "COLT_COT_ATTN_MIN_CONFIDENCE",
            "colt_cot_attention_min_confidence",
            0.05,
            float,
        )
        self._cot_attention_missing_targets_warned = False
        if self.lare_reconstruction_weight < 0:
            raise ValueError(
                "COLT_LARE_RECON_WEIGHT must be non-negative, "
                f"got {self.lare_reconstruction_weight!r}"
            )
        if self.cot_attention_align_weight < 0:
            raise ValueError(
                "COLT_COT_ATTN_ALIGN_WEIGHT must be non-negative, "
                f"got {self.cot_attention_align_weight!r}"
            )
        if not 0.0 <= self.cot_attention_min_confidence <= 1.0:
            raise ValueError(
                "COLT_COT_ATTN_MIN_CONFIDENCE must be in [0, 1], "
                f"got {self.cot_attention_min_confidence!r}"
            )
        self.lare_refocusing_extractor = (
            LaReLatentRefocusingExtractor(
                model_hidden_size=config.text_config.hidden_size,
                extractor_hidden_size=self.lare_extractor_dim,
                num_layers=self.lare_layers,
                num_heads=self.lare_heads,
                num_queries=self.lare_queries,
                max_steps=self.lare_max_steps,
                dropout=self.lare_dropout,
                visual_dropout=self.lare_visual_dropout,
                attention_topk=self.lare_attention_topk,
                gate_bias=self.lare_gate_bias,
                reconstruction_steps=self.lare_reconstruction_steps,
            )
            if self.lare_refocus_enabled
            else None
        )
        self._last_lare_attention_maps = []
        if self.lare_refocus_enabled:
            # Persist architecture settings with the checkpoint.  Explicit env
            # values still take precedence, including COLT_LARE_REFOCUS=0.
            config.colt_lare_refocus = True
            config.colt_lare_dim = self.lare_extractor_dim
            config.colt_lare_layers = self.lare_layers
            config.colt_lare_heads = self.lare_heads
            config.colt_lare_queries = self.lare_queries
            config.colt_lare_max_steps = self.lare_max_steps
            config.colt_lare_dropout = self.lare_dropout
            config.colt_lare_visual_dropout = self.lare_visual_dropout
            config.colt_lare_attention_topk = self.lare_attention_topk
            config.colt_lare_gate_bias = self.lare_gate_bias
            config.colt_lare_reconstruction_weight = self.lare_reconstruction_weight
            config.colt_lare_reconstruction_steps = self.lare_reconstruction_steps
            config.colt_lare_detach_visual = self.lare_detach_visual
            config.colt_lare_record_attention = self.lare_record_attention
            config.colt_cot_attention_align = self.cot_attention_align_enabled
            config.colt_cot_attention_align_weight = self.cot_attention_align_weight
            config.colt_cot_attention_min_confidence = self.cot_attention_min_confidence
        self.kl_anchor_enabled = os.environ.get("COLT_KL_ANCHOR", "0") == "1"
        self.kl_anchor_weight = float(os.environ.get("COLT_KL_ANCHOR_WEIGHT", "0.1"))
        self.colt_teacher = None
        if self.kl_anchor_enabled and not self.colt_rl_mode and not _COLT_TEACHER_LOADING:
            teacher_path = os.environ.get(
                "COLT_TEACHER_PATH",
                "/home/dataset-local/lkl/CoLT-reproduction/checkpoints/colt_paper_faithful_v2",
            )
            _COLT_TEACHER_LOADING = True
            try:
                from transformers import AutoModelForImageTextToText

                self.colt_teacher = AutoModelForImageTextToText.from_pretrained(
                    teacher_path,
                    torch_dtype=config.text_config.dtype,
                    low_cpu_mem_usage=True,
                    local_files_only=True,
                    trust_remote_code=True,
                )
                for param in self.colt_teacher.parameters():
                    param.requires_grad_(False)
            finally:
                _COLT_TEACHER_LOADING = False
        self.latent_answer_grad_norm = None
        self.latent_used_steps = 0
        # Latent hidden states after LayerNorm typically have std~1, while token embeddings are much smaller.
        # Without scaling, fp16/bf16 attention can overflow and produce NaNs in early decoder layers.
        # FSDP cannot flatten zero-dimensional Parameters. Keep these as
        # one-element vectors; multiplication retains scalar broadcasting.
        self.latent_to_decoder_scale = nn.Parameter(torch.tensor([0.02], dtype=torch.float32))
        self.alpha = nn.Parameter(torch.tensor([0.1], dtype=torch.float32))

        tokenizer_source = self._decoder_name_or_path
        if self.colt_rl_mode:
            tokenizer_source = os.environ.get("COLT_RL_TOKENIZER_PATH", getattr(config, "_name_or_path", ""))
            if not tokenizer_source:
                raise ValueError("COLT_RL_MODE requires COLT_RL_TOKENIZER_PATH or config._name_or_path")
        tokenizer = AutoTokenizer.from_pretrained(tokenizer_source)
        self.think_token_id = tokenizer.encode("<think>", add_special_tokens=False)[0]
        self.end_think_token_id = tokenizer.encode("</think>", add_special_tokens=False)[0]
        self.answer_token_id = tokenizer.encode("answer", add_special_tokens=False)[0]
        self.pad_token_id = tokenizer.pad_token_id if tokenizer.pad_token_id is not None else tokenizer.eos_token_id
        self.eos_token_id = tokenizer.encode(tokenizer.eos_token, add_special_tokens=False)[0]
        cot_boundary_texts = ["\n", "\n\n", ".", "。", "?", "？", "!", "！", ";", "；", ":", "：", ",", "，"]
        self.cot_boundary_token_ids = {
            token_id
            for text in cot_boundary_texts
            for token_id in tokenizer.encode(text, add_special_tokens=False)
        }
        self.post_init()
        if self.lare_refocusing_extractor is not None:
            initializer_range = float(getattr(config.text_config, "initializer_range", 0.02))
            self.lare_refocusing_extractor.reset_safe_output(initializer_range)
            # ``post_init`` (and the direct reset above) run while
            # DeepSpeed's construction context may expose only rank-local
            # parameter partitions.  Mark the newly added LaRe tensors as
            # missing-key-initialization candidates so ``from_pretrained``
            # later gathers them before the extractor's zero-residual reset.
            # When loading a trained LaRe checkpoint, Transformers marks every
            # present tensor initialized again, so this cannot overwrite saved
            # weights.
            self._mark_lare_parameters_for_missing_key_initialization()
            if _is_colt_rank_zero():
                print(
                    "[colt-lare] enabled "
                    f"dim={self.lare_extractor_dim} layers={self.lare_layers} "
                    f"heads={self.lare_heads} queries={self.lare_queries} "
                    f"visual_dropout={self.lare_visual_dropout} "
                    f"topk={self.lare_attention_topk} "
                    f"recon_weight={self.lare_reconstruction_weight}",
                    flush=True,
                )
        if self.training and self.decoder is not None:
            self.decoder.gradient_checkpointing_enable()
        self.tokenizer = tokenizer

    def _mark_lare_parameters_for_missing_key_initialization(self):
        """Force new LaRe tensors through HF's gathered missing-key path.

        Under ZeRO-3, direct initialization during construction can operate on
        empty or rank-local parameter views.  Clearing these flags is safe:
        ``_initialize_missing_keys`` restores them for every key found in a
        checkpoint, while genuinely absent (base-Qwen) LaRe keys are gathered
        and then initialized by :meth:`_init_weights`.
        """
        extractor = self.lare_refocusing_extractor
        if extractor is None:
            return
        for module in extractor.modules():
            module._is_hf_initialized = False
        for parameter in extractor.parameters():
            parameter._is_hf_initialized = False
        for buffer in extractor.buffers():
            buffer._is_hf_initialized = False

    def _load_from_state_dict(
        self,
        state_dict,
        prefix,
        local_metadata,
        strict,
        missing_keys,
        unexpected_keys,
        error_msgs,
    ):
        """Load pre-FSDP CoLT checkpoints that stored scalar parameters."""
        for parameter_name in ("latent_to_decoder_scale", "alpha"):
            checkpoint_key = prefix + parameter_name
            checkpoint_value = state_dict.get(checkpoint_key)
            if checkpoint_value is not None and checkpoint_value.ndim == 0:
                state_dict[checkpoint_key] = checkpoint_value.reshape(1)
        return super()._load_from_state_dict(
            state_dict,
            prefix,
            local_metadata,
            strict,
            missing_keys,
            unexpected_keys,
            error_msgs,
        )

    def _parse_oracle_k_steps(self, cot_ids):
        cot_text = self.tokenizer.decode(
            cot_ids.tolist(),
            skip_special_tokens=False,
            clean_up_tokenization_spaces=False,
        )
        annotation = parse_oracle_k_cot(cot_text, min_k=1, max_k=self.oracle_k_max)
        eos = torch.tensor([self.eos_token_id], device=cot_ids.device, dtype=cot_ids.dtype)
        step_ids = []
        step_lens = []
        for block in annotation.blocks:
            block_ids = torch.tensor(
                self.tokenizer.encode(block, add_special_tokens=False),
                device=cot_ids.device,
                dtype=cot_ids.dtype,
            )
            block_with_eos = torch.cat([block_ids, eos], dim=0)
            step_ids.append(block_with_eos)
            step_lens.append(block_with_eos.shape[0])
        return annotation.k, step_ids, step_lens

    def _condition_latent_with_oracle_k(self, latent_embd, oracle_k, step_index):
        if not self.oracle_k_enabled or not self.oracle_k_budget_conditioning:
            return latent_embd
        return self.oracle_k_conditioner(latent_embd, oracle_k, step_index)

    def _pool_question_hidden(self, hidden_states, attention_mask):
        return pool_last_valid_hidden(hidden_states, attention_mask)

    def _predict_oracle_k(self, hidden_states, attention_mask):
        if self.oracle_k_predictor is None:
            return None
        if (
            self.training
            and self._oracle_k_flag("COLT_ORACLE_K_REQUIRE_PREOPTIMIZER_INIT")
            and not self._oracle_k_predictor_preflight_done
        ):
            raise RuntimeError(
                "Oracle-K predictor must be initialized after model loading and before optimizer creation"
            )
        self._prepare_oracle_k_predictor()
        pooled_hidden = self._pool_question_hidden(hidden_states, attention_mask)
        return self.oracle_k_predictor(pooled_hidden)

    def _prepare_lare_visual_inputs(self, prompt_input_ids, reference_hidden):
        """Return padded native image features for every prompt row.

        Placeholder counts, rather than ``image_grid_thw`` row counts, define
        sample ownership.  This supports variable resolution and multiple
        images in one sample and fails loudly if the cached features are stale.
        """
        if not self.lare_refocus_enabled or self.lare_refocusing_extractor is None:
            return None, None
        sample_token_counts = (prompt_input_ids == self.config.image_token_id).sum(dim=-1)
        cached_visual = self.model._colt_visual_embeds
        if cached_visual is not None and self.lare_detach_visual:
            cached_visual = cached_visual.detach()
        return pack_visual_tokens_by_sample(
            cached_visual,
            sample_token_counts,
            hidden_size=self.config.text_config.hidden_size,
            dtype=reference_hidden.dtype,
            device=reference_hidden.device,
        )

    def _apply_lare_refocusing(
        self,
        latent_hidden,
        base_next_latent,
        visual_tokens,
        visual_mask,
        *,
        step_index,
        compute_reconstruction,
    ):
        if not self.lare_refocus_enabled or self.lare_refocusing_extractor is None:
            zero = base_next_latent.float().sum() * 0.0
            return base_next_latent, None, None, zero
        if visual_tokens is None or visual_mask is None:
            raise RuntimeError("LaRe refocusing is enabled but visual inputs were not prepared")
        delta, attention, gate, reconstruction_loss = self.lare_refocusing_extractor(
            latent_hidden,
            visual_tokens,
            visual_mask,
            step_index=step_index,
            compute_reconstruction=compute_reconstruction,
        )
        if self.lare_record_attention:
            self._last_lare_attention_maps.append(attention.detach())
        next_latent = base_next_latent + delta.to(base_next_latent.dtype)
        return next_latent, attention, gate, reconstruction_loss

    def prepare_oracle_k_predictor_for_training(self):
        """Finalize new-head initialization before ZeRO creates FP32 optimizer master weights."""
        self._prepare_oracle_k_predictor()

    @staticmethod
    def _oracle_k_flag(name, default="0"):
        return os.environ.get(name, default).strip().lower() in {"1", "true", "yes", "on"}

    @staticmethod
    def _oracle_k_parameter_stats(name, parameter):
        values = parameter.detach().float()
        finite = torch.isfinite(values)
        finite_values = values[finite]
        stats = {
            "name": name,
            "shape": list(values.shape),
            "numel": values.numel(),
            "nonfinite": int((~finite).sum().item()),
        }
        if finite_values.numel() > 0:
            stats.update(
                mean=float(finite_values.mean().item()),
                std=float(finite_values.std(unbiased=False).item()),
                min=float(finite_values.min().item()),
                max=float(finite_values.max().item()),
                abs_max=float(finite_values.abs().max().item()),
            )
        return stats

    def _oracle_k_predictor_audit(self, phase):
        parameters = [
            self._oracle_k_parameter_stats(name, parameter)
            for name, parameter in self.oracle_k_predictor.named_parameters()
        ]
        output_weight = self.oracle_k_predictor.network[-1].weight.detach().float()
        pairwise = []
        for left in range(output_weight.shape[0]):
            for right in range(left + 1, output_weight.shape[0]):
                difference = (output_weight[left] - output_weight[right]).abs().max()
                pairwise.append(
                    {
                        "rows": [left + 1, right + 1],
                        "max_abs_diff": float(difference.item()),
                        "cosine": float(
                            F.cosine_similarity(output_weight[left], output_weight[right], dim=0).item()
                        ),
                    }
                )
        closest_rows = min(pairwise, key=lambda item: item["max_abs_diff"])
        row_norms = output_weight.norm(dim=1).cpu().tolist()
        print(
            "[oracle-k-predictor-audit] "
            + json.dumps(
                {
                    "phase": phase,
                    "parameters": parameters,
                    "output_row_norms": row_norms,
                    "closest_output_rows": closest_rows,
                    "exact_duplicate_output_rows": [
                        item["rows"] for item in pairwise if item["max_abs_diff"] == 0.0
                    ],
                },
                sort_keys=True,
            )
        )

    def _reset_oracle_k_predictor(self):
        initializer_range = float(getattr(self.config.get_text_config(), "initializer_range", 0.02))
        output_std = float(os.environ.get("COLT_ORACLE_K_PREDICTOR_OUTPUT_STD", "0.001"))
        seed = int(os.environ.get("COLT_ORACLE_K_PREDICTOR_INIT_SEED", "1234"))
        parameter = next(self.oracle_k_predictor.parameters())
        devices = [parameter.device.index] if parameter.is_cuda else []
        with torch.random.fork_rng(devices=devices):
            torch.manual_seed(seed)
            self.oracle_k_predictor.reset_parameters(initializer_range, output_std)

    def _prepare_oracle_k_predictor(self):
        if self._oracle_k_predictor_preflight_done or self.oracle_k_predictor is None:
            return

        initialize = self.training and self._oracle_k_flag("COLT_ORACLE_K_INITIALIZE_PREDICTOR")
        diagnostics = self._oracle_k_flag("COLT_ORACLE_K_DIAGNOSTICS")
        parameters = list(self.oracle_k_predictor.parameters())
        zero_partitioned = any(hasattr(parameter, "ds_id") for parameter in parameters)
        rank = torch.distributed.get_rank() if torch.distributed.is_initialized() else 0

        gathered_context = contextlib.nullcontext()
        if zero_partitioned:
            import deepspeed

            gathered_context = deepspeed.zero.GatheredParameters(
                parameters,
                modifier_rank=0 if initialize else None,
            )

        with gathered_context:
            if diagnostics and rank == 0:
                self._oracle_k_predictor_audit("loaded")
            if initialize and (zero_partitioned is False or rank == 0):
                self._reset_oracle_k_predictor()
            if diagnostics and initialize and rank == 0:
                self._oracle_k_predictor_audit("reset")

        if initialize and not zero_partitioned and torch.distributed.is_initialized():
            for parameter in parameters:
                torch.distributed.broadcast(parameter.data, src=0)

        self._oracle_k_predictor_preflight_done = True

    def _log_oracle_k_first_batch(self, k_logits, k_targets, predicted_k):
        if self._oracle_k_first_batch_logged:
            return
        diagnostics = self._oracle_k_flag("COLT_ORACLE_K_DIAGNOSTICS")
        strict = self._oracle_k_flag("COLT_ORACLE_K_STRICT_INITIALIZATION")
        if not diagnostics and not strict:
            self._oracle_k_first_batch_logged = True
            return

        local_loss_sum = F.cross_entropy(k_logits.float(), k_targets, reduction="sum").detach()
        local_count = torch.tensor(k_targets.numel(), dtype=torch.float32, device=k_logits.device)
        local_abs_max = k_logits.detach().float().abs().max()
        summary = torch.stack([local_loss_sum, local_count, local_abs_max])
        if torch.distributed.is_initialized():
            torch.distributed.all_reduce(summary[:2], op=torch.distributed.ReduceOp.SUM)
            torch.distributed.all_reduce(summary[2], op=torch.distributed.ReduceOp.MAX)
        global_loss = summary[0] / summary[1].clamp_min(1)

        gathered_logits = [k_logits.detach().float()]
        gathered_targets = [k_targets.detach()]
        gathered_predictions = [predicted_k.detach()]
        if torch.distributed.is_initialized():
            world_size = torch.distributed.get_world_size()
            gathered_logits = [torch.empty_like(gathered_logits[0]) for _ in range(world_size)]
            gathered_targets = [torch.empty_like(gathered_targets[0]) for _ in range(world_size)]
            gathered_predictions = [torch.empty_like(gathered_predictions[0]) for _ in range(world_size)]
            torch.distributed.all_gather(gathered_logits, k_logits.detach().float())
            torch.distributed.all_gather(gathered_targets, k_targets.detach())
            torch.distributed.all_gather(gathered_predictions, predicted_k.detach())

        if _is_colt_rank_zero() and diagnostics:
            records = []
            for rank, (rank_logits, rank_targets, rank_predictions) in enumerate(
                zip(gathered_logits, gathered_targets, gathered_predictions)
            ):
                for index in range(rank_targets.numel()):
                    records.append(
                        {
                            "rank": rank,
                            "sample": index,
                            "logits": rank_logits[index].cpu().tolist(),
                            "gt_k": int(rank_targets[index].item()) + 1,
                            "predicted_k": int(rank_predictions[index].item()),
                        }
                    )
            print(
                "[oracle-k-initial-batch] "
                + json.dumps(
                    {
                        "global_cross_entropy": float(global_loss.item()),
                        "global_abs_max_logit": float(summary[2].item()),
                        "records": records,
                    },
                    sort_keys=True,
                )
            )

        if strict:
            loss_value = float(global_loss.item())
            logit_abs_max = float(summary[2].item())
            if not (1.0 <= loss_value <= 4.0) or not (logit_abs_max <= 10.0):
                raise RuntimeError(
                    "Oracle-K predictor initialization failed: "
                    f"global CE={loss_value:.6g}, max_abs_logit={logit_abs_max:.6g}"
                )
        self._oracle_k_first_batch_logged = True

    def _accumulate_oracle_k_metrics(self, k_logits, k_targets, predicted_k):
        loss_sum = F.cross_entropy(k_logits.float(), k_targets, reduction="sum").detach()
        correct = (predicted_k == k_targets + 1).detach().float().sum()
        count = torch.tensor(k_targets.numel(), dtype=torch.float32, device=k_logits.device)
        if self._oracle_k_metric_loss_sum is None:
            self._oracle_k_metric_loss_sum = loss_sum
            self._oracle_k_metric_correct = correct
            self._oracle_k_metric_count = count
        else:
            self._oracle_k_metric_loss_sum += loss_sum
            self._oracle_k_metric_correct += correct
            self._oracle_k_metric_count += count

    def _flush_oracle_k_metrics(self):
        if self._oracle_k_metric_loss_sum is None:
            return None
        totals = torch.stack(
            [self._oracle_k_metric_loss_sum, self._oracle_k_metric_correct, self._oracle_k_metric_count]
        )
        if torch.distributed.is_initialized():
            torch.distributed.all_reduce(totals, op=torch.distributed.ReduceOp.SUM)
        self._oracle_k_metric_loss_sum = None
        self._oracle_k_metric_correct = None
        self._oracle_k_metric_count = None
        count = totals[2].clamp_min(1)
        return totals[0] / count, totals[1] / count, totals[2]

    def _resolve_oracle_k_inference_plan(self, num_hidden_generations, predicted_k=None):
        if not self.oracle_k_enabled:
            latent_steps = num_hidden_generations if num_hidden_generations > 0 else self.num_latent
            return OracleKInferencePlan(
                transition_steps=latent_steps,
                conditioning_k=latent_steps,
            )

        forced_k = None
        forced_transition_steps = resolve_forced_inference_transition_steps(self.oracle_k_max)
        if num_hidden_generations <= 0:
            forced_k = resolve_forced_inference_k(self.oracle_k_max)
        predicted_k_value = None
        if predicted_k is not None:
            if predicted_k.numel() != 1 and forced_transition_steps is not None:
                raise ValueError(
                    "Decoupled transition-step inference currently requires batch size 1; "
                    f"received {predicted_k.numel()} predicted K values"
                )
            if (
                predicted_k.numel() != 1
                and self.oracle_k_dynamic_inference
                and num_hidden_generations <= 0
                and forced_k is None
            ):
                raise ValueError(
                    "Dynamic Oracle-K inference currently requires batch size 1; "
                    f"received {predicted_k.numel()} predicted K values"
                )
            if predicted_k.numel() == 1:
                predicted_k_value = int(predicted_k.reshape(-1)[0].item())
        return select_oracle_k_inference_plan(
            max_k=self.oracle_k_max,
            default_k=self.num_latent,
            num_hidden_generations=num_hidden_generations,
            forced_k=forced_k,
            forced_transition_steps=forced_transition_steps,
            predicted_k=predicted_k_value,
            dynamic_inference=self.oracle_k_dynamic_inference,
        )

    def _resolve_latent_steps_for_inference(self, num_hidden_generations, predicted_k=None):
        return self._resolve_oracle_k_inference_plan(
            num_hidden_generations,
            predicted_k=predicted_k,
        ).transition_steps
        

    def get_input_embeddings(self):
        return self.model.get_input_embeddings()

    def set_input_embeddings(self, value):
        self.model.set_input_embeddings(value)

    def set_decoder(self, decoder):
        self.model.set_decoder(decoder)

    def get_decoder(self):
        return self.model.get_decoder()

    def get_video_features(
        self, pixel_values_videos: torch.FloatTensor, video_grid_thw: Optional[torch.LongTensor] = None
    ):
        return self.model.get_video_features(pixel_values_videos, video_grid_thw)

    def get_image_features(self, pixel_values: torch.FloatTensor, image_grid_thw: Optional[torch.LongTensor] = None):
        return self.model.get_image_features(pixel_values, image_grid_thw)

    # Make modules available through conditional class for BC
    @property
    def language_model(self):
        return self.model.language_model

    @property
    def visual(self):
        return self.model.visual

    def _colt_image_free_question(self, question_ids, attention_mask_question):
        """Remove media placeholders before rebuilding the question KV cache."""
        media_token_ids = {
            token_id
            for token_id in (
                getattr(self.config, "image_token_id", None),
                getattr(self.config, "video_token_id", None),
                getattr(self.config, "vision_start_token_id", None),
                getattr(self.config, "vision_end_token_id", None),
            )
            if token_id is not None
        }
        if not media_token_ids:
            return question_ids, attention_mask_question

        image_free_rows = []
        for row_ids, row_mask in zip(question_ids, attention_mask_question):
            valid_ids = row_ids[row_mask.bool()]
            keep_mask = torch.ones_like(valid_ids, dtype=torch.bool)
            for media_token_id in media_token_ids:
                keep_mask &= valid_ids.ne(media_token_id)
            image_free_row = valid_ids[keep_mask]
            if image_free_row.numel() == 0:
                raise ValueError("The image-free mediated branch received an empty question after media removal")
            image_free_rows.append(image_free_row)
        image_free_ids = torch.nn.utils.rnn.pad_sequence(
            image_free_rows,
            batch_first=True,
            padding_value=self.pad_token_id,
        )
        image_free_mask = (image_free_ids != self.pad_token_id).long()
        remaining_media = sum(
            int((image_free_ids == media_token_id).sum().item())
            for media_token_id in media_token_ids
        )
        if remaining_media:
            raise AssertionError("Image-free question reconstruction retained a visual placeholder")
        return image_free_ids, image_free_mask

    @staticmethod
    def _colt_answer_loss_per_sample(logits, labels):
        if logits.shape[:2] != labels.shape:
            raise ValueError(
                "Bootstrap answer logits/labels must have identical batch and sequence dimensions: "
                f"logits={tuple(logits.shape)}, labels={tuple(labels.shape)}"
            )
        token_losses = F.cross_entropy(
            logits.float().reshape(-1, logits.shape[-1]),
            labels.reshape(-1),
            ignore_index=-100,
            reduction="none",
        ).reshape(labels.shape)
        valid = labels.ne(-100)
        valid_count = valid.sum(dim=1).clamp_min(1)
        return (token_losses * valid).sum(dim=1) / valid_count

    def _colt_mediated_answer_logits(
        self,
        question_ids,
        attention_mask_question,
        latent_history,
        answer_id_list,
        kwargs,
    ):
        """Run answer decoding from an image-free question cache followed by H."""
        if not latent_history:
            raise RuntimeError("Bootstrap mediation requires at least one latent state")
        image_free_ids, image_free_mask = self._colt_image_free_question(
            question_ids,
            attention_mask_question,
        )
        mediated_cache = DynamicCache(config=self.config.text_config)
        question_outputs = self.model(
            input_ids=image_free_ids,
            attention_mask=image_free_mask,
            past_key_values=mediated_cache,
            inputs_embeds=None,
            **kwargs,
        )
        mediated_cache = question_outputs.past_key_values
        latent_sequence = torch.cat(
            [latent.detach() if self.bootstrap_stopgrad_h else latent for latent in latent_history],
            dim=1,
        )
        question_cache_length = mediated_cache.get_seq_length()
        latent_positions = torch.arange(
            question_cache_length,
            question_cache_length + latent_sequence.shape[1],
            device=latent_sequence.device,
        )
        latent_outputs = self.model(
            inputs_embeds=latent_sequence,
            past_key_values=mediated_cache,
            cache_position=latent_positions,
            attention_mask=torch.ones(
                (latent_sequence.shape[0], latent_sequence.shape[1]),
                dtype=torch.long,
                device=latent_sequence.device,
            ),
            position_ids=None,
            **kwargs,
        )
        mediated_cache = latent_outputs.past_key_values

        answer_ids = torch.nn.utils.rnn.pad_sequence(
            answer_id_list,
            batch_first=True,
            padding_value=self.pad_token_id,
        )
        answer_embeddings = self.model.get_input_embeddings()(answer_ids)
        answer_cache_length = mediated_cache.get_seq_length()
        answer_positions = torch.arange(
            answer_cache_length,
            answer_cache_length + answer_embeddings.shape[1],
            device=answer_embeddings.device,
        )
        answer_outputs = self.model(
            inputs_embeds=answer_embeddings,
            past_key_values=mediated_cache,
            cache_position=answer_positions,
            attention_mask=torch.ones(
                (answer_embeddings.shape[0], answer_embeddings.shape[1]),
                dtype=torch.long,
                device=answer_embeddings.device,
            ),
            position_ids=None,
            **kwargs,
        )
        # The last latent position predicts the first answer token.  The
        # subsequent answer call returns logits only for answer inputs, so
        # prepend that final latent-position output for causal-LM alignment.
        mediated_hidden_states = torch.cat(
            [latent_outputs[0][:, -1:, :], answer_outputs[0]],
            dim=1,
        )
        return self.lm_head(mediated_hidden_states)

    def _colt_clean_question_final_latent_answer_logits(
        self,
        *,
        question_ids: torch.Tensor,
        attention_mask_question: torch.Tensor,
        image_grid_thw: Optional[torch.Tensor],
        video_grid_thw: Optional[torch.Tensor],
        final_latent: torch.Tensor,
        answer_id_list: list[torch.Tensor],
        kwargs,
    ) -> torch.Tensor:
        """Stage-1 answer decoder: clean question KV, then only the final latent.

        The latent trajectory is produced from the normal image-conditioned
        prompt elsewhere.  This branch deliberately retains the *same token
        positions and question text*, but replaces image/video placeholder
        embeddings with zeros and never passes pixel values.  Consequently the
        final-answer CE can use visual information only through ``final_latent``.
        """
        if final_latent.ndim != 3 or final_latent.shape[1] != 1:
            raise ValueError(
                "Causal-grounded Stage 1 requires exactly one final latent token; "
                f"received {tuple(final_latent.shape)}."
            )
        placeholder_ids = {
            token_id
            for token_id in (
                getattr(self.config, "image_token_id", None),
                getattr(self.config, "video_token_id", None),
            )
            if token_id is not None
        }
        if not placeholder_ids:
            raise RuntimeError("Causal-grounded Stage 1 could not resolve image/video placeholder token ids.")
        placeholder_mask = torch.zeros_like(question_ids, dtype=torch.bool)
        for token_id in placeholder_ids:
            placeholder_mask |= question_ids.eq(token_id)
        placeholder_mask &= attention_mask_question.bool()
        if not placeholder_mask.any(dim=1).all():
            missing_rows = (~placeholder_mask.any(dim=1)).nonzero(as_tuple=False).flatten().tolist()
            raise ValueError(
                "Causal-grounded Stage 1 requires an image/video placeholder in every question row; "
                f"missing rows={missing_rows}."
            )

        clean_embeddings = self.model.get_input_embeddings()(question_ids)
        clean_embeddings = clean_embeddings.masked_fill(placeholder_mask.unsqueeze(-1), 0.0)
        # Compute Qwen-VL's original multimodal mRoPE coordinates before the
        # clean prefill. Supplying them explicitly prevents the image-free
        # forward from silently falling back to ordinary 1-D text positions.
        clean_position_ids, _ = self.model.get_rope_index(
            input_ids=question_ids,
            image_grid_thw=image_grid_thw,
            video_grid_thw=video_grid_thw,
            attention_mask=attention_mask_question,
        )
        clean_cache = DynamicCache(config=self.config.text_config)
        clean_question_outputs = self.model(
            input_ids=None,
            inputs_embeds=clean_embeddings,
            attention_mask=attention_mask_question,
            position_ids=clean_position_ids,
            past_key_values=clean_cache,
            # No pixel_values/pixel_values_videos: the zeroed placeholders
            # must remain zero rather than being overwritten by vision features.
            **kwargs,
        )
        clean_cache = clean_question_outputs.past_key_values
        clean_question_length = clean_cache.get_seq_length()
        latent_positions = torch.arange(
            clean_question_length,
            clean_question_length + 1,
            device=final_latent.device,
        )
        latent_outputs = self.model(
            inputs_embeds=final_latent,
            past_key_values=clean_cache,
            cache_position=latent_positions,
            attention_mask=_extend_colt_cached_attention_mask(
                attention_mask_question,
                past_seen_tokens=clean_question_length,
                current_length=1,
                batch_size=final_latent.shape[0],
                device=final_latent.device,
            ),
            position_ids=None,
            **kwargs,
        )
        clean_cache = latent_outputs.past_key_values

        answer_ids = torch.nn.utils.rnn.pad_sequence(
            answer_id_list,
            batch_first=True,
            padding_value=self.pad_token_id,
        )
        answer_embeddings = self.model.get_input_embeddings()(answer_ids)
        answer_attention_mask = answer_ids.ne(self.pad_token_id).long()
        answer_cache_length = clean_cache.get_seq_length()
        answer_positions = torch.arange(
            answer_cache_length,
            answer_cache_length + answer_embeddings.shape[1],
            device=answer_embeddings.device,
        )
        answer_outputs = self.model(
            inputs_embeds=answer_embeddings,
            past_key_values=clean_cache,
            cache_position=answer_positions,
            attention_mask=_extend_colt_cached_attention_mask(
                attention_mask_question,
                past_seen_tokens=answer_cache_length,
                current_length=answer_embeddings.shape[1],
                batch_size=answer_embeddings.shape[0],
                device=answer_embeddings.device,
                current_attention_mask=answer_attention_mask,
            ),
            position_ids=None,
            **kwargs,
        )
        clean_hidden_states = torch.cat(
            [latent_outputs[0][:, -1:, :], answer_outputs[0]],
            dim=1,
        )
        return self.lm_head(clean_hidden_states)

    @check_model_inputs
    def forward(
        self,
        input_ids: torch.LongTensor = None,
        attention_mask: Optional[torch.Tensor] = None,
        position_ids: Optional[torch.LongTensor] = None,
        past_key_values: Optional[Cache] = None,
        inputs_embeds: Optional[torch.FloatTensor] = None,
        labels: Optional[torch.LongTensor] = None,
        pixel_values: Optional[torch.Tensor] = None,
        pixel_values_videos: Optional[torch.FloatTensor] = None,
        image_grid_thw: Optional[torch.LongTensor] = None,
        video_grid_thw: Optional[torch.LongTensor] = None,
        cache_position: Optional[torch.LongTensor] = None,
        logits_to_keep: Union[int, torch.Tensor] = 0,
        num_hidden_generations: int = 0,  # The num of generate latent states
        hidden_generation_mode: bool = False,  # enable latent model or not
        colt_rl_response_length: Optional[int] = None,
        colt_cached_latent_outputs: Optional[Qwen3VLCausalLMOutputWithPast] = None,
        colt_shared_prompt_prefix: bool = False,
        colt_bboxes: Optional[List[List[List[float]]]] = None,
        colt_step_bboxes: Optional[List[List[List[List[float]]]]] = None,
        colt_visual_only: Optional[torch.Tensor] = None,
        colt_visual_cot: Optional[torch.Tensor] = None,
        colt_causal_grounded: Optional[torch.Tensor] = None,
        colt_cot_attention_targets: Optional[torch.FloatTensor] = None,
        colt_cot_attention_target_mask: Optional[torch.BoolTensor] = None,
        colt_latent_noise: Optional[torch.FloatTensor] = None,
        colt_latent_sampling_sigma: float = 0.0,
        **kwargs: Unpack[TransformersKwargs],
    ) -> Union[tuple, Qwen3VLCausalLMOutputWithPast]:
        r"""
        labels (`torch.LongTensor` of shape `(batch_size, sequence_length)`, *optional*):
            Labels for computing the masked language modeling loss. Indices should either be in `[0, ...,
            config.vocab_size]` or -100 (see `input_ids` docstring). Tokens with indices set to `-100` are ignored
            (masked), the loss is only computed for the tokens with labels in `[0, ..., config.vocab_size]`.
        image_grid_thw (`torch.LongTensor` of shape `(num_images, 3)`, *optional*):
            The temporal, height and width of feature shape of each image in LLM.
        video_grid_thw (`torch.LongTensor` of shape `(num_videos, 3)`, *optional*):
            The temporal, height and width of feature shape of each video in LLM.

        Example:
            TODO: Add example
        """
        k_logits = None
        predicted_k = None
        if self.latent_reasoning_mode and colt_rl_response_length is not None:
            if labels is not None:
                raise ValueError("CoLT RL response scoring accepts response tokens through input_ids, not labels.")
            kwargs.pop("use_cache", None)
            return self._forward_latent_response(
                input_ids=input_ids,
                attention_mask=attention_mask,
                position_ids=position_ids,
                pixel_values=pixel_values,
                pixel_values_videos=pixel_values_videos,
                image_grid_thw=image_grid_thw,
                video_grid_thw=video_grid_thw,
                response_length=colt_rl_response_length,
                num_hidden_generations=num_hidden_generations,
                latent_outputs=colt_cached_latent_outputs,
                shared_prompt_prefix=colt_shared_prompt_prefix,
                latent_noise=colt_latent_noise,
                latent_sampling_sigma=colt_latent_sampling_sigma,
                **kwargs,
            )
        if self.latent_reasoning_mode:
            colt_loss_row_mask = _resolve_colt_loss_row_mask(
                labels,
                batch_size=input_ids.shape[0],
                device=input_ids.device,
                visual_only=colt_visual_only,
            )
            colt_visual_cot_rows = _resolve_colt_visual_cot_rows(
                colt_visual_cot,
                batch_size=input_ids.shape[0],
                device=input_ids.device,
                bboxes=colt_bboxes,
                step_bboxes=colt_step_bboxes,
            )
            colt_visual_only_rows = (
                _normalize_colt_row_mask(
                    colt_visual_only,
                    batch_size=input_ids.shape[0],
                    device=input_ids.device,
                    name="colt_visual_only",
                )
                if colt_visual_only is not None
                else torch.zeros_like(colt_loss_row_mask)
            )
            colt_causal_grounded_rows = _normalize_colt_row_mask(
                colt_causal_grounded,
                batch_size=input_ids.shape[0],
                device=input_ids.device,
                name="colt_causal_grounded",
            )
            if colt_causal_grounded_rows is None:
                colt_causal_grounded_rows = torch.zeros_like(colt_loss_row_mask)
            if self.causal_grounded_latent_enabled:
                if not colt_causal_grounded_rows.all():
                    raise ValueError(
                        "COLT_CAUSAL_GROUNDED_LATENT=1 requires every model row to set colt_causal_grounded=true."
                    )
                if colt_bboxes is None or len(colt_bboxes) != input_ids.shape[0] or any(
                    len(sample_bboxes) != 1 for sample_bboxes in colt_bboxes
                ):
                    raise ValueError(
                        "Causal-grounded Stage 1 requires exactly one bbox per model row."
                    )
            # Prepare the inputs of each process
            # seperate the question, cot procedure and answer of each sample
            question_id_list, cot_id_list, answer_id_list = map(
                list,
                zip(*[
                    extract_think_content_robust(
                        input_ids_i,
                        self.think_token_id,
                        self.end_think_token_id,
                        self.answer_token_id,
                    )
                    for input_ids_i in input_ids
                ])
            )
            cot_step_id_list = []
            cot_step_len_list = []

            if self.oracle_k_enabled:
                if len(cot_id_list) != 1:
                    raise ValueError(
                        "Oracle-K training currently requires per-device batch size 1; "
                        f"received {len(cot_id_list)} samples"
                    )
                oracle_k, cot_step_id_list_i, cot_step_len_list_i = self._parse_oracle_k_steps(cot_id_list[0])
                cot_step_id_list.append(cot_step_id_list_i)
                cot_step_len_list.append(cot_step_len_list_i)
                training_latent_steps = oracle_k
            else:
                # Split CoT steps by nearby punctuation/newline boundaries instead of fixed equal chunks.
                for i in range(len(cot_id_list)):
                    num_steps = max(self.num_latent, 1)
                    cot_step_id_list_i, cot_step_len_list_i = split_cot_by_dynamic_boundaries(
                        cot_id_list[i],
                        num_steps=num_steps,
                        eos_token_id=self.eos_token_id,
                        boundary_token_ids=self.cot_boundary_token_ids,
                    )
                    cot_step_id_list.append(cot_step_id_list_i)
                    cot_step_len_list.append(cot_step_len_list_i)
                training_latent_steps = self.num_latent
            cot_step_id = pad_input_ids_by_position(cot_step_id_list, self.pad_token_id, device=input_ids.device)
            # Encode the question (right padding for alignment)
            question_ids = torch.nn.utils.rnn.pad_sequence(
                question_id_list, batch_first=True, padding_value=self.pad_token_id
            )
            attention_mask_question = (question_ids != self.pad_token_id).long()
            position_ids_question = None

            if hidden_generation_mode and labels is None:
                if self.oracle_k_enabled:
                    latent_steps = num_hidden_generations
                else:
                    latent_steps = num_hidden_generations if num_hidden_generations > 0 else self.num_latent
                latent_outputs = self._forward_latent_reasoning(
                    input_ids=question_ids,
                    attention_mask=attention_mask_question,
                    position_ids=position_ids_question,
                    pixel_values=pixel_values,
                    pixel_values_videos=pixel_values_videos,
                    image_grid_thw=image_grid_thw,
                    video_grid_thw=video_grid_thw,
                    num_hidden_generations=latent_steps,
                    **kwargs,
                )
                return latent_outputs

            # Some ZeRO initialization paths have produced zeroed nested decoders. Check once
            # on the real device, then never scan these large embedding matrices again.
            decoder_device = input_ids.device
            self.decoder, self._decoder_reload_attempted = _ensure_colt_decoder_initialized(
                self.decoder,
                self._decoder_reload_attempted,
                self._decoder_name_or_path,
                self.config.text_config.dtype,
                decoder_device,
            )
            self.backward_decoder, self._backward_decoder_reload_attempted = _ensure_colt_decoder_initialized(
                self.backward_decoder,
                self._backward_decoder_reload_attempted,
                self._decoder_name_or_path,
                self.config.text_config.dtype,
                decoder_device,
            )

            past_key_values = DynamicCache(config=self.config.text_config)
            outputs = self.model(
                input_ids=question_ids,
                pixel_values=pixel_values,
                pixel_values_videos=pixel_values_videos,
                image_grid_thw=image_grid_thw,
                video_grid_thw=video_grid_thw,
                position_ids=position_ids_question,
                attention_mask=attention_mask_question,
                past_key_values=past_key_values,
                inputs_embeds=None,
                **kwargs,
            )

            hidden_states = outputs[0]
            if os.environ.get("COLT_DEBUG_NONFINITE", "0").strip().lower() in {"1", "true", "yes", "on"}:
                if _is_colt_rank_zero():
                    debug_initial = {
                        "question_ids": bool(torch.isfinite(question_ids.float()).all().item()),
                        "pixel_values": None if pixel_values is None else bool(torch.isfinite(pixel_values.float()).all().item()),
                        "initial_hidden": bool(torch.isfinite(hidden_states.float()).all().item()),
                        "initial_absmax": float(torch.nan_to_num(hidden_states.float(), nan=0.0).abs().max().item()),
                    }
                    print(f"[colt-debug-initial] {json.dumps(debug_initial, sort_keys=True)}", flush=True)
            latent_embd = self._pool_question_hidden(hidden_states, attention_mask_question).unsqueeze(1)
            current_seq_len = outputs.past_key_values.get_seq_length()
            lare_visual_tokens, lare_visual_mask = self._prepare_lare_visual_inputs(
                question_ids, hidden_states
            )
            if self.cot_attention_align_enabled:
                if self.lare_refocusing_extractor is None:
                    raise RuntimeError(
                        "COLT_COT_ATTN_ALIGN=1 requires COLT_LARE_REFOCUS=1 so the student has visual attention."
                    )
                if colt_cot_attention_targets is None or colt_cot_attention_target_mask is None:
                    if not self._cot_attention_missing_targets_warned and _is_colt_rank_zero():
                        print(
                            "[colt-cot-attn] this local microbatch has no non-empty cached teacher maps; "
                            "its alignment term is zero while target-bearing microbatches remain text-guided.",
                            flush=True,
                        )
                        self._cot_attention_missing_targets_warned = True
                else:
                    expected_batch = hidden_states.shape[0]
                    if colt_cot_attention_targets.ndim != 3 or colt_cot_attention_target_mask.ndim != 3:
                        raise ValueError(
                            "CoT attention targets and masks must have shape (batch, steps, visual_tokens), "
                            f"got {tuple(colt_cot_attention_targets.shape)} and "
                            f"{tuple(colt_cot_attention_target_mask.shape)}."
                        )
                    if (
                        colt_cot_attention_targets.shape != colt_cot_attention_target_mask.shape
                        or colt_cot_attention_targets.shape[0] != expected_batch
                    ):
                        raise ValueError(
                            "CoT attention target batch/mask dimensions are inconsistent: "
                            f"targets={tuple(colt_cot_attention_targets.shape)}, "
                            f"mask={tuple(colt_cot_attention_target_mask.shape)}, batch={expected_batch}."
                        )
                    if colt_cot_attention_targets.shape[1] < training_latent_steps:
                        raise ValueError(
                            "Cached CoT attention targets contain fewer semantic steps than this training run: "
                            f"cache={colt_cot_attention_targets.shape[1]}, required={training_latent_steps}."
                        )
            self._last_lare_attention_maps = []
            if self.oracle_k_predictor_enabled:
                k_logits = self._predict_oracle_k(hidden_states, attention_mask_question)
                predicted_k = torch.argmax(k_logits.detach(), dim=-1) + 1
                k_targets = torch.full(
                    (hidden_states.shape[0],),
                    oracle_k - 1,
                    dtype=torch.long,
                    device=k_logits.device,
                )
                k_loss_per_sample = F.cross_entropy(
                    k_logits.float(),
                    k_targets,
                    reduction="none",
                )
                active_count = colt_loss_row_mask.sum()
                if active_count.item() == 0:
                    k_loss_total = k_logits.sum() * 0.0
                else:
                    k_loss_total = (
                        k_loss_per_sample * colt_loss_row_mask.to(k_loss_per_sample.dtype)
                    ).sum() / active_count
                k_accuracy = (predicted_k == k_targets + 1).float().mean()
                self._log_oracle_k_first_batch(k_logits, k_targets, predicted_k)
                self._accumulate_oracle_k_metrics(k_logits, k_targets, predicted_k)
            else:
                k_loss_total = hidden_states.new_zeros(())
                k_accuracy = hidden_states.new_zeros(())

            # Loss buckets for three training objectives:
            # 1) forward_loss_total: latent -> CoT step decoding loss
            # 2) backward_loss_total: CoT step -> latent alignment loss
            # 3) prediction_loss_total: latent_t -> latent_{t+1} prediction loss
            # 4) ce_loss_total: final answer decoding loss
            forward_loss_total = 0.0
            backward_loss_total = 0.0
            prediction_loss_total = 0.0
            ce_loss_total = 0.0
            anchor_loss_total = hidden_states.new_zeros(())
            bootstrap_med_ce_total = hidden_states.new_zeros(())
            bootstrap_med_kl_total = hidden_states.new_zeros(())
            bootstrap_med_loss_total = hidden_states.new_zeros(())
            forward_steps_num = 0
            backward_steps_num = 0
            prediction_steps_num = 0
            batch_size = hidden_states.shape[0]
            batched_forward_records = []
            batched_backward_records = []
            debug_forward_decoder_calls = 0
            debug_backward_decoder_calls = 0
            lare_reconstruction_loss_total = hidden_states.new_zeros((), dtype=torch.float32)
            cot_attention_alignment_loss_total = hidden_states.new_zeros((), dtype=torch.float32)
            cot_attention_alignment_effective_rows = hidden_states.new_zeros((), dtype=torch.float32)
            cot_attention_alignment_target_rows = hidden_states.new_zeros((), dtype=torch.float32)
            cot_attention_alignment_candidate_rows = hidden_states.new_zeros((), dtype=torch.float32)
            cot_attention_alignment_support_abstain_rows = hidden_states.new_zeros((), dtype=torch.float32)
            cot_attention_alignment_confidence_abstain_rows = hidden_states.new_zeros((), dtype=torch.float32)
            cot_attention_alignment_confidences = []
            causal_mediated_ce_total = hidden_states.new_zeros((), dtype=torch.float32)
            colt_latent_hiddens = []
            image_mask_rows = torch.zeros_like(colt_loss_row_mask)
            latent_history = []

            lare_reconstruction_steps = 0
            lare_attention_entropies = []
            lare_gate_means = []
            synchronized_latent_steps = (
                _synchronize_colt_oracle_k(training_latent_steps, input_ids.device)
                if self.oracle_k_enabled
                else training_latent_steps
            )
            oracle_k_plan = (
                build_oracle_k_training_plan(training_latent_steps, synchronized_latent_steps)
                if self.oracle_k_enabled
                else None
            )
            if synchronized_latent_steps != 0:
                for i in range(synchronized_latent_steps):
                    active_step = oracle_k_plan[i].active if oracle_k_plan is not None else True
                    # ---------------------------
                    # A) latent transition step
                    # ---------------------------
                    # For RoPE index / causal mask, attention_mask should reflect the full (cached + current) length.
                    # Qwen3's DynamicCache path expects the attention mask to
                    # cover cached prefix plus the current token.  A one-token
                    # mask happens to work for the first latent step but can
                    # produce non-finite logits once the cache already holds
                    # a latent token.  Dummy inactive steps use a fresh cache.
                    step_attention_mask = torch.ones(
                        (
                            batch_size,
                            current_seq_len + i + 1 if active_step else 1,
                        ),
                        dtype=torch.long,
                        device=latent_embd.device,
                    )
                    latent_step_input = self._condition_latent_with_oracle_k(
                        latent_embd,
                        training_latent_steps,
                        min(i + 1, training_latent_steps),
                    )
                    current_latent_embd = latent_step_input
                    if active_step:
                        step_cache_position = torch.arange(
                            current_seq_len + i,
                            current_seq_len + i + 1,
                            device=latent_embd.device,
                        )
                        outputs = self.model(
                            inputs_embeds=latent_step_input,
                            past_key_values=past_key_values,
                            cache_position=step_cache_position,
                            attention_mask=step_attention_mask,
                            position_ids=None,
                            **kwargs,
                        )
                        past_key_values = outputs.past_key_values
                    else:
                        # Keep ZeRO-3 module/gradient-hook ordering identical without
                        # advancing the real latent state or its local-K KV cache.
                        dummy_cache = DynamicCache(config=self.config.text_config)
                        outputs = self.model(
                            inputs_embeds=latent_step_input,
                            past_key_values=dummy_cache,
                            cache_position=torch.arange(1, device=latent_embd.device),
                            attention_mask=step_attention_mask,
                            position_ids=None,
                            **kwargs,
                        )
                    hidden_states = outputs[0]
                    latent_hidden = hidden_states[:, -1:, :]
                    if os.environ.get("COLT_DEBUG_NONFINITE", "0").strip().lower() in {"1", "true", "yes", "on"} and _is_colt_rank_zero():
                        print(
                            f"[colt-debug-latent] i={i} model_hidden_finite={bool(torch.isfinite(hidden_states.float()).all().item())} "
                            f"latent_finite={bool(torch.isfinite(latent_hidden.float()).all().item())} "
                            f"latent_absmax={float(torch.nan_to_num(latent_hidden.float(), nan=0.0).abs().max().item())}",
                            flush=True,
                        )
                    if os.environ.get("COLT_DEBUG_NONFINITE", "0").strip().lower() in {"1", "true", "yes", "on"} and _is_colt_rank_zero():
                        print(
                            f"[colt-debug-lare-input] i={i} visual_finite={bool(torch.isfinite(lare_visual_tokens.float()).all().item())} "
                            f"visual_absmax={float(torch.nan_to_num(lare_visual_tokens.float(), nan=0.0).abs().max().item())} "
                            f"mask_any={bool(lare_visual_mask.any().item())}",
                            flush=True,
                        )
                    if (
                        active_step
                        and self.visual_grounding_enabled
                        and (colt_bboxes is not None or colt_step_bboxes is not None)
                    ):
                        colt_latent_hiddens.append(latent_hidden)
                    if self.stochastic_latent_enabled:
                        noise, latent_mean, latent_std = self.latent_stochastic_head(
                            latent_hidden,
                            temperature=self.latent_temperature,
                            sample=True,
                        )
                        residual = torch.nan_to_num(
                            self.prj(latent_hidden).float(), nan=0.0, posinf=0.0, neginf=0.0
                        ).clamp(-8.0, 8.0).to(latent_hidden.dtype)
                        alpha = torch.nan_to_num(self.alpha.float(), nan=0.1, posinf=0.1, neginf=-0.1).clamp(-1.0, 1.0).to(latent_hidden.dtype)
                        next_latent_embd = latent_hidden + alpha * residual + self.latent_noise_std * noise
                        if self.training:
                            self.latent_used_steps += 1
                            if self.latent_used_steps % 100 == 0:
                                grad_norm = self.latent_answer_grad_norm
                                grad_norm_str = (
                                    f"{grad_norm:.4f}" if grad_norm is not None else "n/a"
                                )
                                print(
                                    f"[latent-stochastic] step={self.latent_used_steps} "
                                    f"noise_std_mean={latent_std.float().mean().item():.4f} "
                                    f"alpha={self.alpha.detach().float().item():.4f} "
                                    f"answer_grad_norm={grad_norm_str}",
                                    flush=True,
                                )
                    else:
                        residual = torch.nan_to_num(
                            self.prj(latent_hidden).float(), nan=0.0, posinf=0.0, neginf=0.0
                        ).clamp(-8.0, 8.0).to(latent_hidden.dtype)
                        alpha = torch.nan_to_num(self.alpha.float(), nan=0.1, posinf=0.1, neginf=-0.1).clamp(-1.0, 1.0).to(latent_hidden.dtype)
                        next_latent_embd = latent_hidden + alpha * residual
                    if os.environ.get("COLT_DEBUG_NONFINITE", "0").strip().lower() in {"1", "true", "yes", "on"} and _is_colt_rank_zero():
                        print(
                            f"[colt-debug-next-latent] i={i} finite={bool(torch.isfinite(next_latent_embd.float()).all().item())} "
                            f"absmax={float(torch.nan_to_num(next_latent_embd.float(), nan=0.0).abs().max().item())}",
                            flush=True,
                        )
                    pred_next_latent = self.latent_predictor(current_latent_embd.to(next_latent_embd.dtype))
                    prediction_loss_per_sample = F.mse_loss(
                        pred_next_latent,
                        next_latent_embd.detach(),
                        reduction="none",
                    ).mean(dim=tuple(range(1, pred_next_latent.ndim)))
                    next_latent_embd, lare_attention, lare_gate, lare_reconstruction_loss = (
                        self._apply_lare_refocusing(
                            latent_hidden,
                            next_latent_embd,
                            lare_visual_tokens,
                            lare_visual_mask,
                            step_index=i,
                            compute_reconstruction=(
                                self.training and self.lare_reconstruction_weight > 0.0
                            ),
                        )
                    )
                    if os.environ.get("COLT_DEBUG_NONFINITE", "0").strip().lower() in {"1", "true", "yes", "on"} and _is_colt_rank_zero():
                        print(
                            f"[colt-debug-after-lare] i={i} latent_finite={bool(torch.isfinite(next_latent_embd.float()).all().item())} "
                            f"latent_absmax={float(torch.nan_to_num(next_latent_embd.float(), nan=0.0).abs().max().item())} "
                            f"attention_finite={lare_attention is None or bool(torch.isfinite(lare_attention.float()).all().item())} "
                            f"recon_finite={bool(torch.isfinite(lare_reconstruction_loss.float()).all().item())}",
                            flush=True,
                        )
                    if self.lare_refocus_enabled and lare_attention is not None:
                        if active_step:
                            lare_reconstruction_loss_total = (
                                lare_reconstruction_loss_total + lare_reconstruction_loss.float()
                            )
                            lare_reconstruction_steps += 1
                            attention_for_stats = lare_attention.float().clamp_min(1e-12)
                            lare_attention_entropies.append(
                                -(attention_for_stats * attention_for_stats.log())
                                .sum(dim=-1)
                                .mean()
                                .detach()
                            )
                            lare_gate_means.append(lare_gate.float().mean().detach())
                    if active_step and self.cot_attention_align_enabled and lare_attention is not None:
                        # A local microbatch can have no teacher sidecar entries.
                        # Pass None in that case so the loss uses its zero-target
                        # surrogate while preserving the same LaRe graph on all
                        # ZeRO-3 ranks; cached entries keep their normal text-guided
                        # attention supervision.
                        step_teacher_targets = (
                            colt_cot_attention_targets[:, i].to(device=lare_attention.device)
                            if colt_cot_attention_targets is not None
                            else None
                        )
                        step_teacher_target_mask = (
                            colt_cot_attention_target_mask[:, i].to(device=lare_attention.device)
                            if colt_cot_attention_target_mask is not None
                            else None
                        )
                        # Visual dropout intentionally hides random patches from
                        # the student.  Align only on its remaining support;
                        # otherwise the teacher would penalize an impossible
                        # prediction on dropped patches.
                        student_support = lare_visual_mask & (lare_attention.float().sum(dim=1) > 0.0)
                        if step_teacher_target_mask is not None:
                            intersection = student_support & step_teacher_target_mask.bool()
                            target_rows = (intersection.sum(dim=-1) > 0).to(torch.float32).sum()
                            candidate_rows = (intersection.sum(dim=-1) >= 2).to(torch.float32).sum()
                            cot_attention_alignment_target_rows = (
                                cot_attention_alignment_target_rows + target_rows
                            )
                            cot_attention_alignment_candidate_rows = (
                                cot_attention_alignment_candidate_rows + candidate_rows
                            )
                        step_alignment, effective_rows, mean_confidence = cot_attention_alignment_loss(
                            lare_attention,
                            step_teacher_targets,
                            step_teacher_target_mask,
                            student_support,
                            min_confidence=self.cot_attention_min_confidence,
                        )
                        cot_attention_alignment_loss_total = (
                            cot_attention_alignment_loss_total + step_alignment.float() * effective_rows
                        )
                        cot_attention_alignment_effective_rows = (
                            cot_attention_alignment_effective_rows + effective_rows
                        )
                        if step_teacher_target_mask is not None:
                            cot_attention_alignment_support_abstain_rows = (
                                cot_attention_alignment_support_abstain_rows
                                + (target_rows - candidate_rows)
                            )
                            cot_attention_alignment_confidence_abstain_rows = (
                                cot_attention_alignment_confidence_abstain_rows
                                + (candidate_rows - effective_rows)
                            )
                        if effective_rows.item() > 0:
                            cot_attention_alignment_confidences.append(mean_confidence.detach())
                    prediction_loss_total += (
                        prediction_loss_per_sample
                        * colt_loss_row_mask.to(prediction_loss_per_sample.dtype)
                    ).sum() if active_step else prediction_loss_per_sample.sum() * 0.0
                    if active_step:
                        prediction_steps_num += int(colt_loss_row_mask.sum().item())

                    # -----------------------------------------------
                    # B) forward supervision: latent -> CoT decoding
                    # -----------------------------------------------
                    if active_step:
                        latent_embd = next_latent_embd
                        latent_history.append(latent_embd)
                    supervised_latent_embd = latent_embd if active_step else next_latent_embd
                    step_ref_idx = oracle_k_plan[i].forward_index if oracle_k_plan is not None else i
                    decoder_embeddings = self.decoder.get_input_embeddings()
                    decoder_embed_dtype = decoder_embeddings.weight.dtype
                    cot_step_embed = decoder_embeddings(cot_step_id[step_ref_idx]).to(decoder_embed_dtype)
                    latent_for_ref = self.pj_in(supervised_latent_embd) * self.latent_to_decoder_scale.to(
                        supervised_latent_embd.device, supervised_latent_embd.dtype
                    )
                    latent_for_ref = latent_for_ref.to(decoder_embed_dtype)
                    ref_embds = torch.concat([latent_for_ref, cot_step_embed], dim=1)
                    
                    current_ref_ids = cot_step_id[step_ref_idx]
                    current_ref_lens_cpu = [cot_step_len_list[b][step_ref_idx] for b in range(batch_size)]
                    current_ref_lens = torch.tensor(
                        current_ref_lens_cpu,
                        dtype=torch.long,
                        device=current_ref_ids.device,
                    )
                    current_ref_valid = (
                        torch.arange(current_ref_ids.shape[1], device=current_ref_ids.device)
                        .unsqueeze(0)
                        .expand(batch_size, -1)
                        < current_ref_lens.unsqueeze(1)
                    )
                    current_ref_valid &= colt_loss_row_mask.unsqueeze(1)
                    if not active_step:
                        current_ref_valid = torch.zeros_like(current_ref_valid)
                    has_forward_targets = active_step and bool(current_ref_valid.any().item())
                    prefix_mask = torch.ones((batch_size, 1), dtype=torch.long, device=current_ref_ids.device)
                    ref_attention_mask = torch.cat([prefix_mask, current_ref_valid.long()], dim=1)
                    ref_labels = current_ref_ids.masked_fill(~current_ref_valid, -100)
                    ref_labels = torch.cat(
                        [
                            torch.full((batch_size, 1), -100, dtype=ref_labels.dtype, device=ref_labels.device),
                            ref_labels,
                        ],
                        dim=1,
                    )

                    ref_position_ids = (
                        torch.arange(ref_embds.shape[1], device=ref_embds.device, dtype=torch.long)
                        .unsqueeze(0)
                        .expand(batch_size, -1)
                    )
                    forward_record = {
                        "inputs_embeds": ref_embds,
                        "attention_mask": ref_attention_mask,
                        "position_ids": ref_position_ids,
                        "labels": ref_labels,
                        "has_targets": has_forward_targets,
                        "target_mask": colt_loss_row_mask & (current_ref_lens > 0) & active_step,
                    }
                    if self.batch_aux_decoders:
                        batched_forward_records.append(forward_record)
                    else:
                        debug_forward_decoder_calls += 1
                        original_ref_length = ref_embds.shape[1]
                        synchronized_ref_length = _synchronize_colt_sequence_length(
                            original_ref_length, ref_embds.device
                        )
                        decoder_ref_embds = _pad_colt_sequence(ref_embds, synchronized_ref_length)
                        decoder_ref_attention_mask = _pad_colt_sequence(
                            ref_attention_mask, synchronized_ref_length
                        )
                        decoder_ref_position_ids = _pad_colt_sequence(
                            ref_position_ids, synchronized_ref_length
                        )
                        ref_outputs = self.decoder(
                            inputs_embeds=decoder_ref_embds,
                            attention_mask=decoder_ref_attention_mask,
                            position_ids=decoder_ref_position_ids,
                            use_cache=False,
                        )
                        ref_logits = self.pj_out(ref_outputs.logits)[:, :original_ref_length]

                        if self.paper_faithful:
                            forward_loss = _compute_colt_forward_cot_loss(
                                self.loss_function,
                                ref_logits,
                                ref_labels,
                                self.config.text_config.vocab_size,
                                has_targets=has_forward_targets,
                            )
                        else:
                            shift_ref_logits = ref_logits[..., :-1, :].contiguous()
                            shift_ref_labels = ref_labels[..., 1:].contiguous()
                            if not has_forward_targets:
                                forward_loss = shift_ref_logits.sum() * 0.0
                            else:
                                forward_loss = self.loss_function(
                                    shift_ref_logits,
                                    shift_ref_labels,
                                    vocab_size=self.config.text_config.vocab_size,
                                )
                        if has_forward_targets:
                            forward_steps_num += int(forward_record["target_mask"].sum().item())
                        forward_loss_total += forward_loss
                    # ----------------------------------------------------
                    # C) backward alignment: CoT step (+probe) -> latent
                    # ----------------------------------------------------
                    if self.backward_decoder is not None and i >= 1:
                        backward_ref_idx = (
                            oracle_k_plan[i].backward_index if oracle_k_plan is not None else i - 1
                        )
                        backward_ref_ids = cot_step_id[backward_ref_idx]
                        backward_ref_lens_cpu = [
                            cot_step_len_list[b][backward_ref_idx] for b in range(batch_size)
                        ]
                        backward_ref_lens = torch.tensor(
                            backward_ref_lens_cpu,
                            dtype=torch.long,
                            device=backward_ref_ids.device,
                        )
                        cot_step_attention_mask = (
                            torch.arange(backward_ref_ids.shape[1], device=backward_ref_ids.device)
                            .unsqueeze(0)
                            .expand(batch_size, -1)
                            < backward_ref_lens.unsqueeze(1)
                        ).long()
                        backward_active_mask = colt_loss_row_mask & (backward_ref_lens > 0) & active_step
                        has_backward_targets = bool(backward_active_mask.any().item())
                        # In batched mode every rank must contribute a record to the
                        # synchronized auxiliary call graph.  A rank with no local
                        # backward target contributes an inactive record; the helper
                        # filters it out of real batches and replaces it with a 1x1
                        # dummy when another rank has active chunks.  Keep the
                        # historical early-continue for the sequential path.
                        # Even when this rank has no valid backward target, keep
                        # the decoder call in the graph.  The previous early
                        # ``continue`` made the per-rank submodule order depend
                        # on local CoT eligibility, which is invalid under
                        # ZeRO-3.  ``active_mask`` below turns this into a
                        # zero-gradient dummy loss while preserving the call
                        # count on every rank.
                        backward_active = has_backward_targets
                        # Encode CoT step, then force one extra "probe" step.
                        # Dummy records keep the same ZeRO-3 call graph but carry zero loss.
                        probe_token = torch.full(
                            (batch_size, 1),
                            self.eos_token_id,
                            dtype=backward_ref_ids.dtype,
                            device=backward_ref_ids.device,
                        )
                        cot_plus_probe_ids = torch.cat([backward_ref_ids, probe_token], dim=1)
                        cot_plus_probe_mask = torch.cat(
                            [
                                cot_step_attention_mask,
                                torch.ones((batch_size, 1), dtype=torch.long, device=current_ref_ids.device),
                            ],
                            dim=1,
                        )
                        probe_positions = torch.full(
                            (batch_size,),
                            cot_plus_probe_ids.shape[1] - 1,
                            dtype=torch.long,
                            device=cot_plus_probe_ids.device,
                        )
                        backward_record = {
                            "input_ids": cot_plus_probe_ids,
                            "attention_mask": cot_plus_probe_mask,
                            "probe_positions": probe_positions,
                            "latent_embd": supervised_latent_embd,
                            "active": backward_active,
                            "active_mask": backward_active_mask,
                        }
                        if self.batch_aux_decoders:
                            batched_backward_records.append(backward_record)
                        else:
                            debug_backward_decoder_calls += 1
                            original_backward_length = cot_plus_probe_ids.shape[1]
                            synchronized_backward_length = _synchronize_colt_sequence_length(
                                original_backward_length, cot_plus_probe_ids.device
                            )
                            decoder_backward_ids = _pad_colt_sequence(
                                cot_plus_probe_ids,
                                synchronized_backward_length,
                                value=self.pad_token_id,
                            )
                            decoder_backward_mask = _pad_colt_sequence(
                                cot_plus_probe_mask, synchronized_backward_length
                            )
                            with torch.no_grad():
                                decoder_backbone = _get_colt_decoder_backbone(self.backward_decoder)
                                if decoder_backbone is not None:
                                    cot_hidden = decoder_backbone(
                                        input_ids=decoder_backward_ids,
                                        attention_mask=decoder_backward_mask,
                                        use_cache=False,
                                    )[0]
                                else:
                                    cot_outputs = self.backward_decoder(
                                        input_ids=decoder_backward_ids,
                                        attention_mask=decoder_backward_mask,
                                        use_cache=False,
                                        output_hidden_states=True,
                                    )
                                    cot_hidden = cot_outputs.hidden_states[-1]
                            backward_loss = _compute_colt_backward_alignment_loss(
                                cot_hidden,
                                supervised_latent_embd,
                                self.pj_back,
                                active_mask=backward_active_mask,
                            )
                            backward_loss_total += backward_loss
                            if backward_active:
                                backward_steps_num += int(backward_active_mask.sum().item())

                # D) Decode the final answer once all ranks have completed the
                # synchronized latent loop, using this rank's local-K state.
                IGNORE_INDEX = -100
                labels = torch.nn.utils.rnn.pad_sequence(
                    answer_id_list, batch_first=True, padding_value=IGNORE_INDEX
                )
                labels = torch.cat(
                    [
                        torch.full((batch_size, 1), IGNORE_INDEX, dtype=labels.dtype, device=labels.device),
                        labels,
                    ],
                    dim=1,
                )
                label_input_ids = torch.nn.utils.rnn.pad_sequence(
                    answer_id_list, batch_first=True, padding_value=self.pad_token_id
                )
                embds = self.model.get_input_embeddings()(label_input_ids)
                if self.stochastic_latent_enabled and self.training and latent_embd.requires_grad:
                    latent_embd.register_hook(
                        lambda grad: setattr(self, "latent_answer_grad_norm", grad.float().norm().item())
                    )
                factual_latent_embd = (
                    latent_embd.detach() if self.bootstrap_enabled and self.bootstrap_stopgrad_h else latent_embd
                )
                embds = torch.concat([factual_latent_embd, embds], dim=1)
                past_seen_tokens = (
                    past_key_values.get_seq_length() if past_key_values is not None else current_seq_len + training_latent_steps
                )
                step_cache_position = torch.arange(
                    past_seen_tokens,
                    past_seen_tokens + embds.shape[1],
                    device=latent_embd.device,
                )
                step_attention_mask = torch.ones(
                    (batch_size, embds.shape[1]), dtype=torch.long, device=latent_embd.device
                )
                if self.training and self.answer_visibility == "latent_only":
                    # Permanent causal bottleneck: the answer may attend only
                    # the latent trajectory and its own decoded history.  This
                    # removes both direct image access and the residual
                    # image leakage that can flow through question KV states.
                    full_seq_len = past_seen_tokens + embds.shape[1]
                    full_mask = torch.zeros(
                        (batch_size, full_seq_len), dtype=torch.long, device=latent_embd.device
                    )
                    prompt_length = attention_mask_question.shape[1]
                    full_mask[:, prompt_length:] = 1
                    step_attention_mask = full_mask
                elif (
                    self.training
                    and self.image_mask_prob > 0.0
                ):
                    full_seq_len = past_seen_tokens + embds.shape[1]
                    full_mask = torch.ones(
                        (batch_size, full_seq_len), dtype=torch.long, device=latent_embd.device
                    )
                    # The bottleneck is sampled per row and only for explicit
                    # visual-CoT examples. Masking the whole question KV prefix
                    # is required: masking image-token positions alone still
                    # leaks image information through question KV states.
                    sampled_rows = torch.rand(batch_size, device=latent_embd.device) < self.image_mask_prob
                    rows_to_mask = colt_visual_cot_rows & colt_loss_row_mask & sampled_rows
                    image_mask_rows |= rows_to_mask
                    if rows_to_mask.any():
                        step_attention_mask = _mask_colt_visual_cot_prompt_rows(
                            full_mask,
                            current_seq_len=current_seq_len,
                            rows_to_mask=rows_to_mask,
                        )
                outputs = self.model(
                    inputs_embeds=embds,
                    past_key_values=past_key_values,
                    cache_position=step_cache_position,
                    attention_mask=step_attention_mask,
                    position_ids=None,
                    **kwargs,
                )

                logits = self.lm_head(outputs[0])
                fact_shift_logits = logits[:, :-1, :]
                fact_shift_labels = labels[:, 1:]
                factual_answer_rows = colt_loss_row_mask & ~colt_causal_grounded_rows
                if factual_answer_rows.any():
                    ce_loss_total += self.loss_function(
                        logits=logits,
                        labels=labels.masked_fill(~factual_answer_rows.unsqueeze(1), IGNORE_INDEX),
                        vocab_size=self.config.text_config.vocab_size,
                    )
                else:
                    ce_loss_total += logits.sum() * 0.0
                if self.causal_grounded_latent_enabled:
                    clean_logits = self._colt_clean_question_final_latent_answer_logits(
                        question_ids=question_ids,
                        attention_mask_question=attention_mask_question,
                        image_grid_thw=image_grid_thw,
                        video_grid_thw=video_grid_thw,
                        final_latent=latent_embd,
                        answer_id_list=answer_id_list,
                        kwargs=kwargs,
                    )
                    causal_mediated_ce_total = self.loss_function(
                        logits=clean_logits,
                        labels=labels.masked_fill(~colt_causal_grounded_rows.unsqueeze(1), IGNORE_INDEX),
                        vocab_size=self.config.text_config.vocab_size,
                    )
                    ce_loss_total += causal_mediated_ce_total
                if self.colt_teacher is not None:
                    with torch.no_grad():
                        teacher_outputs = self.colt_teacher(
                            input_ids=input_ids,
                            attention_mask=attention_mask,
                            pixel_values=pixel_values,
                            image_grid_thw=image_grid_thw,
                        )
                    valid = (labels != IGNORE_INDEX) & colt_loss_row_mask.unsqueeze(1)
                    if valid.any():
                        student_lp = F.log_softmax(logits.float()[valid], dim=-1)
                        teacher_lp = F.log_softmax(teacher_outputs.logits.float()[valid], dim=-1)
                        anchor_loss_total = F.kl_div(
                            student_lp,
                            teacher_lp,
                            reduction="batchmean",
                            log_target=True,
                        )
                    else:
                        anchor_loss_total = k_loss_total.new_zeros(())
                if self.bootstrap_enabled:
                    mediated_logits = self._colt_mediated_answer_logits(
                        question_ids=question_ids,
                        attention_mask_question=attention_mask_question,
                        latent_history=latent_history,
                        answer_id_list=answer_id_list,
                        kwargs=kwargs,
                    )
                    mediated_labels = labels
                    mediated_sample_ce = self._colt_answer_loss_per_sample(
                        mediated_logits[:, :-1, :],
                        mediated_labels[:, 1:],
                    )
                    factual_sample_ce = self._colt_answer_loss_per_sample(
                        fact_shift_logits,
                        fact_shift_labels,
                    )
                    mediated_mask = (
                        torch.rand(batch_size, device=labels.device) < self.bootstrap_med_prob
                    ).to(mediated_sample_ce.dtype)
                    selected_count = mediated_mask.sum().clamp_min(1.0)
                    bootstrap_med_ce_total = (mediated_sample_ce * mediated_mask).sum() / selected_count

                    answer_length = labels.shape[1] - 1
                    fact_answer_logits = logits[:, :answer_length, :]
                    mediated_answer_logits = mediated_logits[
                        :, :answer_length, :
                    ]
                    answer_valid = fact_shift_labels.ne(IGNORE_INDEX)
                    fact_probabilities = F.softmax(fact_answer_logits.detach().float(), dim=-1)
                    mediated_log_probabilities = F.log_softmax(mediated_answer_logits.float(), dim=-1)
                    token_kl = F.kl_div(
                        mediated_log_probabilities,
                        fact_probabilities,
                        reduction="none",
                    ).sum(dim=-1)
                    answer_token_count = answer_valid.sum(dim=1).clamp_min(1)
                    mediated_sample_kl = (token_kl * answer_valid).sum(dim=1) / answer_token_count
                    bootstrap_med_kl_total = (mediated_sample_kl * mediated_mask).sum() / selected_count
                    bootstrap_med_loss_total = bootstrap_med_ce_total + (
                        self.bootstrap_kl_weight * bootstrap_med_kl_total
                    )
                    if _is_colt_rank_zero() and _colt_component_log_interval() > 0:
                        print(
                            "bootstrap_batch_metrics : "
                            f"fact_ce={factual_sample_ce.mean().detach().float().item():.6f} "
                            f"med_ce={bootstrap_med_ce_total.detach().float().item():.6f} "
                            f"med_kl={bootstrap_med_kl_total.detach().float().item():.6f} "
                            f"med_fraction={mediated_mask.mean().detach().float().item():.3f}"
                        )
            if os.environ.get("COLT_DEBUG_CALL_GRAPH", "0") == "1" and self._colt_forward_microbatch_count < 1:
                debug_rank = (
                    torch.distributed.get_rank()
                    if torch.distributed.is_available() and torch.distributed.is_initialized()
                    else 0
                )
                print(
                    "[colt-call-graph] "
                    f"rank={debug_rank} latent_steps={training_latent_steps} "
                    f"num_latent={self.num_latent} batch_aux={self.batch_aux_decoders} "
                    f"decoder={self.decoder is not None} backward_decoder={self.backward_decoder is not None} "
                    f"forward_calls={debug_forward_decoder_calls} backward_calls={debug_backward_decoder_calls} "
                    f"loss_rows={int(colt_loss_row_mask.sum().item())}",
                    flush=True,
                )

            if self.batch_aux_decoders:
                forward_losses = _run_colt_forward_decoder_steps(
                    self.decoder,
                    self.pj_out,
                    self.loss_function,
                    batched_forward_records,
                    self.config.text_config.vocab_size,
                    batched=True,
                )
                for forward_loss, record in zip(forward_losses, batched_forward_records):
                    forward_loss_total += forward_loss
                    forward_steps_num += int(record["target_mask"].sum().item())

                backward_losses = _run_colt_backward_decoder_steps(
                    self.backward_decoder,
                    self.pj_back,
                    batched_backward_records,
                    self.pad_token_id,
                    batched=True,
                )
                for backward_loss, record in zip(backward_losses, batched_backward_records):
                    backward_loss_total += backward_loss
                    active_mask = record.get("active_mask")
                    if active_mask is None:
                        backward_steps_num += int(bool(record.get("active", True)))
                    else:
                        backward_steps_num += int(active_mask.sum().item())

            forward_loss_total = forward_loss_total / max(forward_steps_num, 1)
            backward_loss_total = backward_loss_total / max(backward_steps_num, 1)
            prediction_loss_total = prediction_loss_total / max(prediction_steps_num, 1)
            self._colt_forward_microbatch_count += 1
            component_log_interval = _colt_component_log_interval()
            should_log_components = (
                component_log_interval > 0
                and self._colt_forward_microbatch_count % component_log_interval == 0
            )
            lare_reconstruction_loss_total = (
                lare_reconstruction_loss_total / max(lare_reconstruction_steps, 1)
            )
            cot_attention_alignment_loss_total = cot_attention_alignment_loss_total / (
                cot_attention_alignment_effective_rows.clamp_min(1.0)
            )
            global_k_metrics = None
            if should_log_components and self.oracle_k_predictor_enabled:
                # Every rank must participate. This aggregates the full effective
                # optimizer batch instead of reporting rank 0's final microbatch.
                global_k_metrics = self._flush_oracle_k_metrics()
            if (
                should_log_components
                and _is_colt_rank_zero()
            ):
                # These diagnostics are emitted from the model forward, not
                # from the Trainer's optimizer hook. With the default
                # interval (8) and fix-v2 accumulation (8), the line usually
                # lands next to an optimizer-step record, but the counters
                # below still describe this rank's current micro-batch.
                print(
                    "colt_component_log_scope : local_microbatch "
                    f"component_log_every={component_log_interval}"
                )
                component_losses = torch.stack(
                    [
                        ce_loss_total.detach().float(),
                        forward_loss_total.detach().float(),
                        backward_loss_total.detach().float(),
                        prediction_loss_total.detach().float(),
                    ]
                ).cpu().tolist()
                print(f"ce_loss_total : {component_losses[0]}")
                print(f"forward_loss_total : {component_losses[1]}")
                print(f"backward_loss_total : {component_losses[2]}")
                print(f"prediction_loss_total : {component_losses[3]}")
                print(
                    "colt_control_rows : "
                    f"active={int(colt_loss_row_mask.sum().item())} "
                    f"visual_cot={int(colt_visual_cot_rows.sum().item())} "
                    f"visual_only={int(colt_visual_only_rows.sum().item())} "
                    f"causal_grounded={int(colt_causal_grounded_rows.sum().item())} "
                    f"image_mask_hit={int(image_mask_rows.sum().item())}"
                )
                if self.causal_grounded_latent_enabled:
                    print(
                        "causal_mediated_ce_total : "
                        f"{causal_mediated_ce_total.detach().float().item()}"
                    )
                if self.lare_refocus_enabled:
                    print(
                        "lare_reconstruction_loss_total : "
                        f"{lare_reconstruction_loss_total.detach().float().item()}"
                    )
                    print(
                        "weighted_lare_reconstruction : "
                        f"{(self.lare_reconstruction_weight * lare_reconstruction_loss_total).detach().float().item()}"
                    )
                    if lare_attention_entropies:
                        print(
                            "lare_attention_entropy : "
                            f"{torch.stack(lare_attention_entropies).mean().detach().float().item()}"
                        )
                    if lare_gate_means:
                        print(
                            "lare_gate_mean : "
                            f"{torch.stack(lare_gate_means).mean().detach().float().item()}"
                        )
                if self.cot_attention_align_enabled:
                    print(
                        "cot_attention_alignment_loss_total : "
                        f"{cot_attention_alignment_loss_total.detach().float().item()}"
                    )
                    print(
                        "weighted_cot_attention_alignment : "
                        f"{(self.cot_attention_align_weight * cot_attention_alignment_loss_total).detach().float().item()}"
                    )
                    print(
                        "cot_attention_alignment_effective_rows : "
                        f"{cot_attention_alignment_effective_rows.detach().float().item()}"
                    )
                    print(
                        "cot_attention_alignment_target_rows : "
                        f"{cot_attention_alignment_target_rows.detach().float().item()}"
                    )
                    print(
                        "cot_attention_alignment_candidate_rows : "
                        f"{cot_attention_alignment_candidate_rows.detach().float().item()}"
                    )
                    print(
                        "cot_attention_alignment_support_abstain_rows : "
                        f"{cot_attention_alignment_support_abstain_rows.detach().float().item()}"
                    )
                    print(
                        "cot_attention_alignment_confidence_abstain_rows : "
                        f"{cot_attention_alignment_confidence_abstain_rows.detach().float().item()}"
                    )
                    if cot_attention_alignment_confidences:
                        print(
                            "cot_attention_teacher_confidence : "
                            f"{torch.stack(cot_attention_alignment_confidences).mean().detach().float().item()}"
                        )
                if self.oracle_k_predictor_enabled:
                    global_k_loss, global_k_accuracy, global_k_samples = (
                        metric.detach().float().cpu().item() for metric in global_k_metrics
                    )
                    print(f"k_loss_total : {global_k_loss}")
                    print(f"k_accuracy : {global_k_accuracy}")
                    print(f"k_samples_global : {int(global_k_samples)}")
            grounding_loss_total = k_loss_total.new_zeros(())
            if (
                self.visual_grounding_enabled
                and colt_latent_hiddens
                and self.model._colt_visual_embeds is not None
                and self.model._colt_image_grid_thw is not None
            ):
                if colt_step_bboxes is not None:
                    z_Hs = torch.cat(colt_latent_hiddens, dim=1)
                    gqa_idx = [i for i, b in enumerate(colt_step_bboxes) if b]
                    if gqa_idx:
                        z_Hs = z_Hs[gqa_idx]
                        step_bboxes_valid = [colt_step_bboxes[i] for i in gqa_idx]
                        z_pos, z_neg_same = pool_step_roi_and_nonroi_features(
                            self.model._colt_visual_embeds,
                            self.model._colt_image_grid_thw,
                            step_bboxes_valid,
                        )
                        grounding_loss_total = compute_step_contrastive_loss(
                            z_Hs,
                            z_pos.detach(),
                            z_neg_same.detach(),
                            self.visual_grounding_temperature,
                        )
                elif colt_bboxes is not None:
                    z_H = torch.cat(colt_latent_hiddens, dim=1).mean(dim=1)
                    z_V_pos, z_V_neg = pool_roi_and_non_roi_features(
                        self.model._colt_visual_embeds,
                        self.model._colt_image_grid_thw,
                        colt_bboxes,
                    )
                    grounding_loss_total = compute_grounding_contrastive_loss(
                        z_H,
                        z_V_pos.detach(),
                        z_V_neg.detach(),
                        self.visual_grounding_temperature,
                    )
            if should_log_components and _is_colt_rank_zero():
                print(f"grounding_loss_total : {grounding_loss_total.detach().float().item()}")
                print(
                    "weighted_visual_term : "
                    f"{(self.visual_grounding_weight * grounding_loss_total).detach().float().item()}"
                )
                if self.colt_teacher is not None:
                    print(f"kl_anchor_loss_total : {anchor_loss_total.detach().float().item()}")
                    print(
                        "weighted_kl_anchor : "
                        f"{(self.kl_anchor_weight * anchor_loss_total).detach().float().item()}"
                    )
            loss = (
                ce_loss_total
                + self.bootstrap_med_weight * bootstrap_med_loss_total
                + self.forward_align_weight * forward_loss_total
                + self.backward_align_weight * backward_loss_total
                + self.prediction_weight * prediction_loss_total
                + self.oracle_k_predictor_loss_weight * k_loss_total
                + self.visual_grounding_weight * grounding_loss_total
                + self.kl_anchor_weight * anchor_loss_total
                + self.lare_reconstruction_weight * lare_reconstruction_loss_total
                + self.cot_attention_align_weight * cot_attention_alignment_loss_total
            )
            if os.environ.get("COLT_DEBUG_NONFINITE", "0").strip().lower() in {"1", "true", "yes", "on"}:
                debug_values = {
                    "ce": ce_loss_total,
                    "forward": forward_loss_total,
                    "backward": backward_loss_total,
                    "prediction": prediction_loss_total,
                    "lare_recon": lare_reconstruction_loss_total,
                    "cot_align": cot_attention_alignment_loss_total,
                    "causal_mediated_ce": causal_mediated_ce_total,
                    "loss": loss,
                    "latent": latent_embd,
                    "question_hidden": hidden_states,
                }
                nonfinite = {
                    name: {
                        "finite": bool(torch.isfinite(value).all().item()),
                        "min": float(torch.nan_to_num(value.detach().float(), nan=0.0).min().item()),
                        "max": float(torch.nan_to_num(value.detach().float(), nan=0.0).max().item()),
                    }
                    for name, value in debug_values.items()
                }
                if _is_colt_rank_zero():
                    print(f"[colt-debug-nonfinite] {json.dumps(nonfinite, sort_keys=True)}", flush=True)

        elif self.latent_reasoning_mode == False:
            outputs = self.model(
                input_ids=input_ids,
                pixel_values=pixel_values,
                pixel_values_videos=pixel_values_videos,
                image_grid_thw=image_grid_thw,
                video_grid_thw=video_grid_thw,
                position_ids=position_ids,
                attention_mask=attention_mask,
                past_key_values=past_key_values,
                inputs_embeds=inputs_embeds,
                cache_position=cache_position,
                **kwargs,
            )

            hidden_states = outputs[0]

            # Only compute necessary logits, and do not upcast them to float if we are not computing the loss
            slice_indices = slice(-logits_to_keep, None) if isinstance(logits_to_keep, int) else logits_to_keep
            logits = self.lm_head(hidden_states[:, slice_indices, :])

            loss = None
            if labels is not None:
                loss = self.loss_function(logits=logits, labels=labels, vocab_size=self.config.text_config.vocab_size)

        return Qwen3VLCausalLMOutputWithPast(
            loss=loss,
            logits=logits,
            past_key_values=outputs.past_key_values,
            rope_deltas=outputs.rope_deltas,
            k_logits=k_logits,
            predicted_k=predicted_k,
        )

    def _forward_latent_response(
        self,
        input_ids: torch.LongTensor,
        response_length: int,
        attention_mask: Optional[torch.Tensor] = None,
        position_ids: Optional[torch.LongTensor] = None,
        pixel_values: Optional[torch.Tensor] = None,
        pixel_values_videos: Optional[torch.FloatTensor] = None,
        image_grid_thw: Optional[torch.LongTensor] = None,
        video_grid_thw: Optional[torch.LongTensor] = None,
        num_hidden_generations: int = 0,
        latent_outputs: Optional[Qwen3VLCausalLMOutputWithPast] = None,
        shared_prompt_prefix: bool = False,
        latent_noise: Optional[torch.FloatTensor] = None,
        latent_sampling_sigma: float = 0.0,
        **kwargs: Unpack[TransformersKwargs],
    ) -> Qwen3VLCausalLMOutputWithPast:
        if input_ids is None or input_ids.ndim != 2:
            raise ValueError("CoLT RL response scoring requires rank-2 input_ids.")
        if not isinstance(response_length, int) or response_length <= 0 or response_length >= input_ids.shape[1]:
            raise ValueError(
                "colt_rl_response_length must be a positive integer smaller than the full sequence length; "
                f"received {response_length!r} for sequence length {input_ids.shape[1]}."
            )

        prompt_length = input_ids.shape[1] - response_length
        prompt_input_ids = input_ids[:, :prompt_length]
        response_ids = input_ids[:, prompt_length:]
        prompt_attention_mask = attention_mask[:, :prompt_length] if attention_mask is not None else None
        response_attention_mask = attention_mask[:, prompt_length:] if attention_mask is not None else None
        prompt_position_ids = position_ids[..., :prompt_length] if position_ids is not None else None
        if latent_outputs is None:
            latent_input_ids = prompt_input_ids
            latent_attention_mask = prompt_attention_mask
            latent_position_ids = prompt_position_ids
            if shared_prompt_prefix:
                if input_ids.shape[0] <= 1:
                    raise ValueError(
                        "CoLT shared-prefix scoring requires a response group with batch size greater than one."
                    )
                if not torch.all(prompt_input_ids == prompt_input_ids[:1]):
                    raise ValueError("CoLT shared-prefix scoring requires identical prompt token ids within the group.")
                if prompt_attention_mask is not None and not torch.all(
                    prompt_attention_mask == prompt_attention_mask[:1]
                ):
                    raise ValueError("CoLT shared-prefix scoring requires identical prompt masks within the group.")
                latent_input_ids = prompt_input_ids[:1]
                latent_attention_mask = prompt_attention_mask[:1] if prompt_attention_mask is not None else None
                if prompt_position_ids is not None:
                    latent_position_ids = (
                        prompt_position_ids[:, :1]
                        if prompt_position_ids.ndim == 3
                        else prompt_position_ids[:1]
                    )
            latent_outputs = self._forward_latent_reasoning(
                input_ids=latent_input_ids,
                attention_mask=latent_attention_mask,
                position_ids=latent_position_ids,
                pixel_values=pixel_values,
                pixel_values_videos=pixel_values_videos,
                image_grid_thw=image_grid_thw,
                video_grid_thw=video_grid_thw,
                num_hidden_generations=num_hidden_generations,
                latent_noise=latent_noise,
                latent_sampling_sigma=latent_sampling_sigma,
                **kwargs,
            )
            if shared_prompt_prefix:
                group_size = input_ids.shape[0]
                latent_outputs.hidden_states = tuple(
                    hidden_state.repeat_interleave(group_size, dim=0)
                    if isinstance(hidden_state, torch.Tensor)
                    else hidden_state
                    for hidden_state in latent_outputs.hidden_states
                )
                latent_outputs.past_key_values.batch_repeat_interleave(group_size)
                if latent_outputs.k_logits is not None:
                    latent_outputs.k_logits = latent_outputs.k_logits.repeat_interleave(group_size, dim=0)
                if latent_outputs.predicted_k is not None:
                    latent_outputs.predicted_k = latent_outputs.predicted_k.repeat_interleave(group_size, dim=0)
                if getattr(latent_outputs, "latent_noise", None) is not None:
                    latent_outputs.latent_noise = latent_outputs.latent_noise.repeat_interleave(group_size, dim=0)
                if getattr(latent_outputs, "latent_log_probs", None) is not None:
                    latent_outputs.latent_log_probs = latent_outputs.latent_log_probs.repeat_interleave(
                        group_size, dim=0
                    )

        latent_embd = latent_outputs.hidden_states[0]
        teacher_inputs = [latent_embd]
        if response_length > 1:
            teacher_inputs.append(self.model.get_input_embeddings()(response_ids[:, :-1]))
        answer_embeds = torch.cat(teacher_inputs, dim=1)
        past_seen_tokens = latent_outputs.past_key_values.get_seq_length()
        cache_position = torch.arange(
            past_seen_tokens,
            past_seen_tokens + response_length,
            device=input_ids.device,
        )
        answer_attention_mask = _extend_colt_cached_attention_mask(
            prompt_attention_mask,
            past_seen_tokens=past_seen_tokens,
            current_length=response_length,
            batch_size=input_ids.shape[0],
            device=input_ids.device,
            current_attention_mask=response_attention_mask,
            mask_prompt=getattr(self, "answer_visibility", "full") == "latent_only",
        )
        outputs = self.model(
            inputs_embeds=answer_embeds,
            past_key_values=latent_outputs.past_key_values,
            cache_position=cache_position,
            attention_mask=answer_attention_mask,
            position_ids=None,
            use_cache=True,
            **kwargs,
        )
        logits = self.lm_head(outputs[0])
        return Qwen3VLCausalLMOutputWithPast(
            loss=None,
            logits=logits,
            past_key_values=outputs.past_key_values,
            hidden_states=outputs.hidden_states,
            rope_deltas=outputs.rope_deltas,
            k_logits=latent_outputs.k_logits,
            predicted_k=latent_outputs.predicted_k,
            latent_noise=getattr(latent_outputs, "latent_noise", None),
            latent_log_probs=getattr(latent_outputs, "latent_log_probs", None),
        )

    def _forward_latent_reasoning(
        self,
        input_ids: torch.LongTensor,
        attention_mask: Optional[torch.Tensor] = None,
        position_ids: Optional[torch.LongTensor] = None,
        pixel_values: Optional[torch.Tensor] = None,
        pixel_values_videos: Optional[torch.FloatTensor] = None,
        image_grid_thw: Optional[torch.LongTensor] = None,
        video_grid_thw: Optional[torch.LongTensor] = None,
        num_hidden_generations: int = 0,
        latent_noise: Optional[torch.FloatTensor] = None,
        latent_sampling_sigma: float = 0.0,
        **kwargs: Unpack[TransformersKwargs],
    ) -> Qwen3VLCausalLMOutputWithPast:
        intervention = os.environ.get("COLT_LATENT_INTERVENTION", "none").strip().lower()
        if intervention not in ("none", "skip", "zero", "random"):
            raise ValueError(
                "COLT_LATENT_INTERVENTION must be one of none|skip|zero|random, "
                f"got {intervention!r}"
            )
        intervention_seed = int(os.environ.get("COLT_LATENT_INTERVENTION_SEED", "1234"))
        if position_ids is not None:
            if position_ids.ndim == 2:
                max_position_ids = position_ids.max(dim=-1, keepdim=True).values
            elif position_ids.ndim == 3:
                max_position_ids = position_ids.max(dim=0).values.max(dim=-1, keepdim=True).values
            else:
                raise ValueError(
                    "CoLT latent reasoning expects rank-2 or rank-3 position_ids; "
                    f"received shape {tuple(position_ids.shape)}."
                )
            prompt_sequence_length = attention_mask.shape[-1] if attention_mask is not None else input_ids.shape[-1]
            self.model.rope_deltas = max_position_ids + 1 - prompt_sequence_length

        outputs = self.model(
            input_ids=input_ids,
            pixel_values=pixel_values,
            pixel_values_videos=pixel_values_videos,
            image_grid_thw=image_grid_thw,
            video_grid_thw=video_grid_thw,
            position_ids=position_ids,
            attention_mask=attention_mask,
            past_key_values=DynamicCache(config=self.config.text_config),
            inputs_embeds=None,
            **kwargs,
        )

        past_key_values = outputs.past_key_values
        hidden_states = outputs[0]
        latent_dtype = (
            self.lm_head.weight.dtype
            if getattr(self.lm_head, "weight", None) is not None
            else hidden_states.dtype
        )
        latent_embd = initialize_colt_inference_latent(
            self._pool_question_hidden(hidden_states, attention_mask).unsqueeze(1),
            self.prj,
            self.inference_latent_transition,
        ).to(latent_dtype)
        k_logits = self._predict_oracle_k(hidden_states, attention_mask)
        predicted_k = torch.argmax(k_logits, dim=-1) + 1 if k_logits is not None else None
        inference_plan = self._resolve_oracle_k_inference_plan(
            num_hidden_generations,
            predicted_k=predicted_k,
        )
        answer_only_latent = getattr(self, "answer_visibility", "full") == "latent_only"
        if answer_only_latent and intervention in ("skip", "zero", "random"):
            inference_plan = OracleKInferencePlan(transition_steps=0, conditioning_k=0)
        elif intervention == "skip":
            inference_plan = OracleKInferencePlan(transition_steps=0, conditioning_k=0)
        if intervention != "none":
            print(
                f"[latent-intervention] mode={intervention} "
                f"transition_steps={inference_plan.transition_steps} "
                f"conditioning_k={inference_plan.conditioning_k} "
                f"seed={intervention_seed}",
                flush=True,
            )
        self.last_oracle_k_prediction = predicted_k.detach().cpu() if predicted_k is not None else None
        self.last_oracle_k_used = inference_plan.transition_steps
        self.last_oracle_k_conditioning = inference_plan.conditioning_k
        latent_scale = 1.0
        if intervention in ("zero", "random"):
            latent_scale = float(latent_embd.detach().float().abs().mean().item()) or 1.0
        if getattr(self, "lare_refocus_enabled", False):
            lare_visual_tokens, lare_visual_mask = self._prepare_lare_visual_inputs(
                input_ids, hidden_states
            )
            self._last_lare_attention_maps = []
        else:
            lare_visual_tokens, lare_visual_mask = None, None
        if answer_only_latent and intervention in ("skip", "zero"):
            latent_embd = torch.zeros_like(latent_embd)
        elif answer_only_latent and intervention == "random":
            torch.manual_seed(intervention_seed)
            latent_embd = torch.randn_like(latent_embd) * latent_scale
        self._last_latent_hiddens = []
        transition_steps = inference_plan.transition_steps
        if latent_sampling_sigma < 0.0:
            raise ValueError(
                "colt_latent_sampling_sigma must be non-negative, "
                f"received {latent_sampling_sigma!r}."
            )
        if latent_noise is not None:
            if latent_noise.ndim != 3:
                raise ValueError(
                    "colt_latent_noise must have shape [batch, transition_steps, hidden_size], "
                    f"received {tuple(latent_noise.shape)}."
                )
            if latent_noise.shape[0] != latent_embd.shape[0] or latent_noise.shape[-1] != latent_embd.shape[-1]:
                raise ValueError(
                    "colt_latent_noise batch/hidden dimensions do not match the latent state: "
                    f"noise={tuple(latent_noise.shape)}, latent={tuple(latent_embd.shape)}."
                )
            if latent_noise.shape[1] < transition_steps:
                raise ValueError(
                    "colt_latent_noise does not contain enough transition draws: "
                    f"noise_steps={latent_noise.shape[1]}, transition_steps={transition_steps}."
                )
            latent_noise = latent_noise[:, :transition_steps].to(
                device=latent_embd.device, dtype=latent_embd.dtype
            )
        elif latent_sampling_sigma > 0.0 and transition_steps > 0:
            latent_noise = torch.randn(
                latent_embd.shape[0],
                transition_steps,
                latent_embd.shape[-1],
                device=latent_embd.device,
                dtype=latent_embd.dtype,
            )
        latent_log_probs = None
        if latent_noise is not None and transition_steps > 0:
            if latent_sampling_sigma > 0.0:
                log_sigma = torch.log(torch.as_tensor(latent_sampling_sigma, device=latent_embd.device))
                latent_log_probs = -0.5 * (
                    latent_noise.float().square() + 2.0 * log_sigma + math.log(2.0 * math.pi)
                ).sum(dim=-1)
            else:
                if torch.any(latent_noise != 0):
                    raise ValueError("Non-zero colt_latent_noise requires colt_latent_sampling_sigma > 0.")
                latent_log_probs = torch.zeros(
                    latent_noise.shape[:2], device=latent_embd.device, dtype=torch.float32
                )
        for i in range(inference_plan.transition_steps):
            past_seen_tokens = past_key_values.get_seq_length()
            step_cache_position = torch.arange(
                past_seen_tokens,
                past_seen_tokens + 1,
                device=latent_embd.device,
            )
            step_attention_mask = _extend_colt_cached_attention_mask(
                attention_mask,
                past_seen_tokens=past_seen_tokens,
                current_length=1,
                batch_size=latent_embd.shape[0],
                device=latent_embd.device,
            )
            conditioning_step = select_oracle_k_conditioning_step(
                i + 1,
                inference_plan.conditioning_k,
            )
            transition_input = latent_embd
            if latent_noise is not None:
                transition_input = transition_input + latent_sampling_sigma * latent_noise[:, i : i + 1]
            latent_step_input = self._condition_latent_with_oracle_k(
                transition_input,
                inference_plan.conditioning_k,
                conditioning_step,
            )
            if intervention == "zero":
                latent_step_input = torch.zeros_like(latent_step_input)
            elif intervention == "random":
                torch.manual_seed(intervention_seed + i)
                latent_step_input = torch.randn_like(latent_step_input) * latent_scale
            step_outputs = self.model(
                inputs_embeds=latent_step_input,
                past_key_values=past_key_values,
                cache_position=step_cache_position,
                attention_mask=step_attention_mask,
                position_ids=None,
                **kwargs,
            )
            past_key_values = step_outputs.past_key_values
            latent_hidden = step_outputs[0][:, -1:, :]
            self._last_latent_hiddens.append(latent_hidden)
            base_next_latent = advance_colt_inference_latent(
                latent_hidden,
                self.prj,
                self.alpha,
                self.inference_latent_transition,
            )
            latent_embd, _, _, _ = self._apply_lare_refocusing(
                latent_hidden,
                base_next_latent,
                lare_visual_tokens,
                lare_visual_mask,
                step_index=i,
                compute_reconstruction=False,
            )
            latent_embd = latent_embd.to(latent_dtype)
            outputs = step_outputs

        logits = self.lm_head(latent_embd)
        return Qwen3VLCausalLMOutputWithPast(
            loss=None,
            logits=logits,
            past_key_values=past_key_values,
            hidden_states=(latent_embd,),
            rope_deltas=outputs.rope_deltas,
            k_logits=k_logits,
            predicted_k=predicted_k,
            latent_noise=latent_noise,
            latent_log_probs=(latent_log_probs.sum(dim=1) if latent_log_probs is not None else None),
        )

    @torch.no_grad()
    def latent_reasoning_generate(
        self,
        input_ids: torch.LongTensor,
        attention_mask: Optional[torch.Tensor] = None,
        position_ids: Optional[torch.LongTensor] = None,
        pixel_values: Optional[torch.Tensor] = None,
        pixel_values_videos: Optional[torch.FloatTensor] = None,
        image_grid_thw: Optional[torch.LongTensor] = None,
        video_grid_thw: Optional[torch.LongTensor] = None,
        num_hidden_generations: int = 0,
        max_new_tokens: int = 128,
        do_sample: bool = False,
        temperature: float = 1.0,
        top_k: Optional[int] = None,
        top_p: float = 1.0,
        eos_token_id: Optional[int] = None,
        prevent_empty_response: bool = False,
        return_token_log_probs: bool = False,
        return_latent_trace: bool = False,
        colt_latent_noise: Optional[torch.FloatTensor] = None,
        colt_latent_sampling_sigma: float = 0.0,
        colt_cached_latent_outputs: Optional[Qwen3VLCausalLMOutputWithPast] = None,
        **kwargs: Unpack[TransformersKwargs],
    ) -> Union[torch.LongTensor, tuple[torch.LongTensor, torch.FloatTensor]]:
        if not 0.0 < top_p <= 1.0:
            raise ValueError(f"top_p must be in (0, 1], received {top_p}.")
        if colt_cached_latent_outputs is None:
            latent_outputs = self._forward_latent_reasoning(
                input_ids=input_ids,
                attention_mask=attention_mask,
                position_ids=position_ids,
                pixel_values=pixel_values,
                pixel_values_videos=pixel_values_videos,
                image_grid_thw=image_grid_thw,
                video_grid_thw=video_grid_thw,
                num_hidden_generations=num_hidden_generations,
                latent_noise=colt_latent_noise,
                latent_sampling_sigma=colt_latent_sampling_sigma,
                **kwargs,
            )
        else:
            latent_outputs = colt_cached_latent_outputs

        past_key_values = latent_outputs.past_key_values
        latent_embd = latent_outputs.hidden_states[0]
        generated_tokens = []
        generated_token_log_probs = []
        eos_id = self.eos_token_id if eos_token_id is None else eos_token_id
        next_input_ids = None
        visible_text_generated = [False] * input_ids.shape[0]

        def select_next_token(logits):
            if do_sample:
                sample_logits = logits / max(temperature, 1e-5)
                if top_k is not None and top_k > 0:
                    topk_values, _ = torch.topk(sample_logits, min(top_k, sample_logits.shape[-1]), dim=-1)
                    min_topk = topk_values[:, -1].unsqueeze(-1)
                    sample_logits = sample_logits.masked_fill(sample_logits < min_topk, float("-inf"))
                probs = torch.softmax(sample_logits, dim=-1)
                if top_p < 1.0:
                    sorted_probs, sorted_indices = torch.sort(probs, descending=True, dim=-1)
                    cumulative_probs = torch.cumsum(sorted_probs, dim=-1)
                    remove_mask = cumulative_probs - sorted_probs >= top_p
                    sorted_probs = sorted_probs.masked_fill(remove_mask, 0.0)
                    probs = torch.zeros_like(probs).scatter(-1, sorted_indices, sorted_probs)
                    probs = probs / probs.sum(dim=-1, keepdim=True).clamp_min(torch.finfo(probs.dtype).tiny)
                return torch.multinomial(probs, num_samples=1)
            return torch.argmax(logits, dim=-1, keepdim=True)

        for generation_step in range(max_new_tokens):
            past_seen_tokens = past_key_values.get_seq_length()
            step_cache_position = torch.arange(
                past_seen_tokens,
                past_seen_tokens + 1,
                device=input_ids.device,
            )
            step_attention_mask = _extend_colt_cached_attention_mask(
                attention_mask,
                past_seen_tokens=past_seen_tokens,
                current_length=1,
                batch_size=input_ids.shape[0],
                device=input_ids.device,
                mask_prompt=getattr(self, "answer_visibility", "full") == "latent_only",
            )

            if next_input_ids is None:
                step_outputs = self.model(
                    inputs_embeds=latent_embd,
                    past_key_values=past_key_values,
                    cache_position=step_cache_position,
                    attention_mask=step_attention_mask,
                    position_ids=None,
                    **kwargs,
                )
            else:
                step_outputs = self.model(
                    input_ids=next_input_ids,
                    past_key_values=past_key_values,
                    cache_position=step_cache_position,
                    attention_mask=step_attention_mask,
                    position_ids=None,
                    **kwargs,
                )

            past_key_values = step_outputs.past_key_values
            next_token_logits = self.lm_head(step_outputs[0][:, -1, :])
            next_token = select_next_token(next_token_logits)

            if prevent_empty_response and eos_id is not None:
                proposed_tokens = next_token.squeeze(-1).detach().cpu().tolist()
                blocked_rows = [
                    row
                    for row, token_id in enumerate(proposed_tokens)
                    if token_id == eos_id and not visible_text_generated[row]
                ]
                if blocked_rows:
                    replacement_logits = next_token_logits[blocked_rows].clone()
                    special_ids = [
                        token_id
                        for token_id in self.tokenizer.all_special_ids
                        if 0 <= token_id < replacement_logits.shape[-1]
                    ]
                    replacement_logits[:, special_ids] = float("-inf")
                    next_token[blocked_rows] = select_next_token(replacement_logits)
                    print(
                        f"[latent-generate] prevented_empty_eos step={generation_step} rows={blocked_rows}",
                        flush=True,
                    )

            generated_tokens.append(next_token)
            policy_logits = next_token_logits / max(temperature, 1e-5)
            generated_token_log_probs.append(
                torch.log_softmax(policy_logits.float(), dim=-1).gather(dim=-1, index=next_token)
            )
            next_input_ids = next_token
            if prevent_empty_response and not all(visible_text_generated):
                generated_so_far = torch.cat(generated_tokens, dim=1).detach().cpu().tolist()
                for row, token_ids in enumerate(generated_so_far):
                    if not visible_text_generated[row]:
                        visible_text_generated[row] = bool(
                            self.tokenizer.decode(
                                token_ids,
                                skip_special_tokens=True,
                                clean_up_tokenization_spaces=False,
                            ).strip()
                        )
            if eos_id is not None and torch.all(next_token.squeeze(-1) == eos_id):
                break

        if len(generated_tokens) == 0:
            if return_latent_trace:
                empty_log_probs = torch.empty(
                    (input_ids.shape[0], 0), dtype=torch.float32, device=input_ids.device
                )
                return (
                    input_ids,
                    empty_log_probs,
                    latent_outputs.latent_noise,
                    latent_outputs.latent_log_probs,
                )
            if return_token_log_probs:
                empty_log_probs = torch.empty(
                    (input_ids.shape[0], 0), dtype=torch.float32, device=input_ids.device
                )
                return input_ids, empty_log_probs
            return input_ids
        new_tokens = torch.cat(generated_tokens, dim=1)
        sequences = torch.cat([input_ids, new_tokens], dim=1)
        if return_latent_trace:
            return (
                sequences,
                torch.cat(generated_token_log_probs, dim=1),
                latent_outputs.latent_noise,
                latent_outputs.latent_log_probs,
            )
        if return_token_log_probs:
            return sequences, torch.cat(generated_token_log_probs, dim=1)
        return sequences

    @torch.no_grad()
    def generate(self, *args, **kwargs):
        if not self.latent_reasoning_mode:
            return super().generate(*args, **kwargs)
        requested_do_sample = kwargs.get("do_sample")
        requested_max_new_tokens = kwargs.get("max_new_tokens")

        if len(args) > 0:
            input_ids = args[0]
        else:
            input_ids = kwargs.pop("input_ids", None)
        if input_ids is None:
            raise ValueError("`input_ids` is required when `latent_reasoning_mode=True`.")

        attention_mask = kwargs.pop("attention_mask", None)
        position_ids = kwargs.pop("position_ids", None)
        pixel_values = kwargs.pop("pixel_values", None)
        pixel_values_videos = kwargs.pop("pixel_values_videos", None)
        image_grid_thw = kwargs.pop("image_grid_thw", None)
        video_grid_thw = kwargs.pop("video_grid_thw", None)
        default_hidden_generations = 0 if self.oracle_k_enabled else self.num_latent
        num_hidden_generations = kwargs.pop("num_hidden_generations", default_hidden_generations)
        respect_generation_args = os.environ.get("COLT_RESPECT_GENERATION_ARGS", "0").strip().lower() in {
            "1",
            "true",
            "yes",
            "on",
        }
        if respect_generation_args:
            max_new_tokens = kwargs.pop("max_new_tokens", 128)
            do_sample = kwargs.pop("do_sample", False)
        else:
            kwargs.pop("max_new_tokens", 128)
            max_new_tokens = 256
            kwargs.pop("do_sample", False)
            do_sample = True
        temperature = kwargs.pop("temperature", 0.6)
        top_k = kwargs.pop("top_k", 20)
        top_p = kwargs.pop("top_p", 1.0)
        eos_token_id = kwargs.pop("eos_token_id", None)
        prevent_empty_response = kwargs.pop("prevent_empty_response", False)

        generation_config_signature = (
            requested_do_sample,
            do_sample,
            requested_max_new_tokens,
            max_new_tokens,
            prevent_empty_response,
            self.inference_latent_transition,
        )
        if generation_config_signature != getattr(self, "_last_logged_generation_config", None):
            print(
                "[latent-generate] "
                f"requested_do_sample={requested_do_sample} "
                f"effective_do_sample={do_sample} "
                f"requested_max_new_tokens={requested_max_new_tokens} "
                f"effective_max_new_tokens={max_new_tokens} "
                f"prevent_empty_response={prevent_empty_response} "
                f"respect_generation_args={respect_generation_args} "
                f"inference_latent_transition={self.inference_latent_transition}",
                flush=True,
            )
            self._last_logged_generation_config = generation_config_signature

        return self.latent_reasoning_generate(
            input_ids=input_ids,
            attention_mask=attention_mask,
            position_ids=position_ids,
            pixel_values=pixel_values,
            pixel_values_videos=pixel_values_videos,
            image_grid_thw=image_grid_thw,
            video_grid_thw=video_grid_thw,
            num_hidden_generations=num_hidden_generations,
            max_new_tokens=max_new_tokens,
            do_sample=do_sample,
            temperature=temperature,
            top_k=top_k,
            top_p=top_p,
            eos_token_id=eos_token_id,
            prevent_empty_response=prevent_empty_response,
            **kwargs,
        )

    def prepare_inputs_for_generation(
        self,
        input_ids,
        past_key_values=None,
        attention_mask=None,
        inputs_embeds=None,
        cache_position=None,
        position_ids=None,
        use_cache=True,
        pixel_values=None,
        pixel_values_videos=None,
        image_grid_thw=None,
        video_grid_thw=None,
        **kwargs,
    ):
        # Overwritten -- in specific circumstances we don't want to forward image inputs to the model

        model_inputs = super().prepare_inputs_for_generation(
            input_ids,
            past_key_values=past_key_values,
            attention_mask=attention_mask,
            inputs_embeds=inputs_embeds,
            cache_position=cache_position,
            position_ids=position_ids,
            pixel_values=pixel_values,
            pixel_values_videos=pixel_values_videos,
            image_grid_thw=image_grid_thw,
            video_grid_thw=video_grid_thw,
            use_cache=use_cache,
            **kwargs,
        )

        # Qwen3VL position_ids are prepareed with rope_deltas in forward
        model_inputs["position_ids"] = None

        if cache_position[0] != 0:
            model_inputs["pixel_values"] = None
            model_inputs["pixel_values_videos"] = None

        return model_inputs

    def _get_image_nums_and_video_nums(
        self,
        input_ids: Optional[torch.LongTensor],
        inputs_embeds: Optional[torch.Tensor] = None,
    ) -> tuple[torch.Tensor, torch.Tensor]:
        """
        Get the number of images and videos for each sample to calculate the separation length of the sample tensor.
        These parameters are not passed through the processor to avoid unpredictable impacts from interface modifications.

        Args:
            input_ids (`torch.LongTensor` of shape `(batch_size, sequence_length)`):
                Indices of input sequence tokens in the vocabulary.

        Returns:
            image_nums (`torch.LongTensor` of shape `(batch_size, num_images_sample)`)
            video_nums (`torch.LongTensor` of shape `(batch_size, num_videos_sample)`)
        """
        image_token_id = self.config.image_token_id
        video_token_id = self.config.video_token_id
        vision_start_token_id = self.config.vision_start_token_id

        if inputs_embeds is not None:
            vision_start_mask = (
                inputs_embeds
                == self.get_input_embeddings()(
                    torch.tensor(vision_start_token_id, dtype=torch.long, device=inputs_embeds.device)
                )
            )[..., 0]
            image_mask = (
                inputs_embeds
                == self.get_input_embeddings()(
                    torch.tensor(image_token_id, dtype=torch.long, device=inputs_embeds.device)
                )
            )[..., 0]
            video_mask = (
                inputs_embeds
                == self.get_input_embeddings()(
                    torch.tensor(video_token_id, dtype=torch.long, device=inputs_embeds.device)
                )
            )[..., 0]
        else:
            vision_start_mask = input_ids == vision_start_token_id
            image_mask = input_ids == image_token_id
            video_mask = input_ids == video_token_id

        vision_first_mask = torch.roll(vision_start_mask, shifts=1, dims=1)
        image_nums = torch.sum(vision_first_mask & image_mask, dim=1)
        video_nums = torch.sum(vision_first_mask & video_mask, dim=1)

        return image_nums, video_nums

    def _expand_inputs_for_generation(
        self,
        expand_size: int = 1,
        is_encoder_decoder: bool = False,
        input_ids: Optional[torch.LongTensor] = None,
        **model_kwargs,
    ) -> tuple[torch.LongTensor, dict[str, Any]]:
        # Overwritten -- Support for expanding tensors without a batch size dimension
        # e.g., pixel_values, image_grid_thw, pixel_values_videos, video_grid_thw, second_per_grid_t
        # pixel_values.shape[0] is sum(seqlen_images for samples)
        # image_grid_thw.shape[0] is sum(num_images for samples)

        if expand_size == 1:
            return input_ids, model_kwargs

        visual_keys = ["pixel_values", "image_grid_thw", "pixel_values_videos", "video_grid_thw", "second_per_grid_ts"]

        def _expand_dict_for_generation_visual(dict_to_expand):
            image_grid_thw = model_kwargs.get("image_grid_thw", None)
            video_grid_thw = model_kwargs.get("video_grid_thw", None)
            image_nums, video_nums = self._get_image_nums_and_video_nums(
                input_ids, inputs_embeds=model_kwargs.get("inputs_embeds", None)
            )

            def _repeat_interleave_samples(x, lengths, repeat_times):
                samples = torch.split(x, lengths)
                repeat_args = [repeat_times] + [1] * (x.dim() - 1)
                result = torch.cat([sample.repeat(*repeat_args) for sample in samples], dim=0)
                return result

            for key in dict_to_expand:
                if key == "pixel_values":
                    # split images into samples
                    samples = torch.split(image_grid_thw, list(image_nums))
                    # compute the sequence length of images for each sample
                    lengths = [torch.prod(sample, dim=1).sum() for sample in samples]
                    dict_to_expand[key] = _repeat_interleave_samples(
                        dict_to_expand[key], lengths=lengths, repeat_times=expand_size
                    )
                elif key == "image_grid_thw":
                    # get the num of images for each sample
                    lengths = list(image_nums)
                    dict_to_expand[key] = _repeat_interleave_samples(
                        dict_to_expand[key], lengths=lengths, repeat_times=expand_size
                    )
                elif key == "pixel_values_videos":
                    samples = torch.split(video_grid_thw, list(video_nums))
                    lengths = [torch.prod(sample, dim=1).sum() for sample in samples]
                    dict_to_expand[key] = _repeat_interleave_samples(
                        dict_to_expand[key], lengths=lengths, repeat_times=expand_size
                    )
                elif key == "video_grid_thw":
                    lengths = list(video_nums)
                    dict_to_expand[key] = _repeat_interleave_samples(
                        dict_to_expand[key], lengths=lengths, repeat_times=expand_size
                    )
                elif key == "second_per_grid_ts":
                    dict_to_expand[key] = _repeat_interleave_samples(
                        dict_to_expand[key], lengths=list(video_nums), repeat_times=expand_size
                    )
            return dict_to_expand

        def _expand_dict_for_generation(dict_to_expand):
            for key in dict_to_expand:
                if (
                    key != "cache_position"
                    and dict_to_expand[key] is not None
                    and isinstance(dict_to_expand[key], torch.Tensor)
                    and key not in visual_keys
                ):
                    dict_to_expand[key] = dict_to_expand[key].repeat_interleave(expand_size, dim=0)
            return dict_to_expand

        model_kwargs = _expand_dict_for_generation_visual(model_kwargs)

        if input_ids is not None:
            input_ids = input_ids.repeat_interleave(expand_size, dim=0)

        model_kwargs = _expand_dict_for_generation(model_kwargs)

        if is_encoder_decoder:
            if model_kwargs.get("encoder_outputs") is None:
                raise ValueError("If `is_encoder_decoder` is True, make sure that `encoder_outputs` is defined.")
            model_kwargs["encoder_outputs"] = _expand_dict_for_generation(model_kwargs["encoder_outputs"])

        return input_ids, model_kwargs


__all__ = [
    "Qwen3VLVisionModel",
    "Qwen3VLForConditionalGeneration",
    "Qwen3VLModel",
    "Qwen3VLPreTrainedModel",
    "Qwen3VLTextModel",
]
